local config = {
  ui_story_5029_50290001_1_dialog_content = "<color=#828282>Ding...</color>",
  ui_story_5029_50290001_2_dialog_content = "Saat pelabuhan yang sibuk tertidur karena gumaman yang dibisikkan oleh bayi...",
  ui_story_5029_50290001_3_dialog_content = "Saat dunia sepi bersama angin malam dari laut dalam...",
  ui_story_5029_50290001_4_dialog_content = "Saat bel yang maha tahu di dekat jendela berbunyi untuk kesebelas kalinya...",
  ui_story_5029_50290001_5_dialog_content = "Hadirin yang saya hormati dan pelanggan yang terhormat.",
  ui_story_5029_50290001_6_dialog_content = "Anda akan merasakan denyut listrik perlahan mengalir dari akar rambut hingga ujung jari kaki.",
  ui_story_5029_50290001_7_dialog_content = "Anda akan merasa... santai dan damai tidak seperti sebelumnya.",
  ui_story_5029_50290001_8_dialog_content = "Lalu... <color=#793f76>tarik napas dalam-dalam, lalu keluarkan semuanya</color>.",
  ui_story_5029_50290001_9_option_content = "Tarik napas lalu hembuskan",
  ui_story_5029_50290001_10_option_content = "Buang napas lalu tarik napas",
  ui_story_5029_50290001_11_dialog_content = "Bagus. Anda tahu cara bernapas. Seseorang pernah membuat suara binatang pada langkah ini.",
  ui_story_5029_50290001_12_dialog_content = "Tapi bukan itu intinya. Sekarang...",
  ui_story_5029_50290001_13_dialog_content = "Anda mulai merasa pusing... Jangan khawatir. Kamu tetap bangun.",
  ui_story_5029_50290001_14_dialog_content = "Anda mulai mengingat...",
  ui_story_5029_50290001_15_dialog_content = "Siapa orang-orang dalam hidup Anda yang membuat Anda ingin memilah-milah petunjuk nasib dan mengintip ke mana cabang-cabang ini mengarah.",
  ui_story_5029_50290001_16_dialog_content = "Bagus. Mereka mungkin yang Anda lihat di kepala Anda sekarang.",
  ui_story_5029_50290001_17_dialog_content = "Apakah itu? <color=#793f76>cahaya yang menyilaukan</color> integritas dan tekad yang mengarah?",
  ui_story_5029_50290001_18_dialog_content = "Apakah itu? <color=#793f76>cahaya bulan yang lembut</color> kehangatan dan pertimbangan yang tidak pernah meninggalkan?",
  ui_story_5029_50290001_19_dialog_content = "Atau apakah itu? <color=#793f76>cahaya bintang yang berkedip-kedip</color> kebijaksanaan dan kenakalan yang memiliki kekuatan besar?",
  ui_story_5029_50290001_20_dialog_content = "Saya tidak bisa memberi Anda jawaban, hanya membantu Anda memahami beberapa di lautan petunjuk ...",
  ui_story_5029_50290001_21_dialog_content = "Tentu saja, itu hanyalah metafora, karena manusia tidak akan pernah bisa menangkap kesadaran dan inspirasi.",
  ui_story_5029_50290001_22_dialog_content = "Anda dapat mencoba untuk menemukan hal-hal yang mempesona...",
  ui_story_5029_50290001_23_dialog_content = "Dan berikan diri Anda kemungkinan arah ke depan.",
  ui_story_5029_50290001_24_dialog_content = "Dan Anda, mulai saat ini, adalah jiwa dari ramalan ini.",
  ui_story_5029_50290001_25_dialog_content = "Anda adalah pencipta cerita Anda, penenun mimpi, dan penentu nasib Anda.",
  ui_story_5029_50290001_26_dialog_content = "Tapi perhatikan saran saya bahwa menjadi terlalu bersemangat bukanlah ide yang baik.",
  ui_story_5029_50290001_27_dialog_content = "Ingat, kamu harus tetap <color=#793f76>tenang</color> dan <color=#793f76>terfokus</color> sepanjang ramalan ini.",
  ui_story_5029_50290001_28_dialog_content = "Atau arus waktu akan melahap semua yang telah Anda capai.",
  ui_story_5029_50290001_29_dialog_content = "<color=#828282>Ding...</color>",
  ui_story_5029_50290001_30_dialog_content = "Sudah waktunya.",
  ui_story_5029_50290001_31_dialog_content = "Sekarang, buat pilihan pertama Anda. Memilih <color=#793f76>satu</color> dari tiga kartu yang disajikan kepada Anda.",
  ui_story_5029_50290001_32_dialog_content = "Kartu ini akan menjadi kunci untuk membuka kunci perjalanan Anda ke masa depan.",
  ui_story_5029_50290001_33_option_content = "Kartu Asal: Matahari",
  ui_story_5029_50290001_34_dialog_content = "Matahari yang menyilaukan. Tidak semua berani menatap langsung...",
  ui_story_5029_50290001_35_dialog_content = "Ha ha. Apakah ini pilihanmu?",
  ui_story_5029_50290001_36_dialog_content = "Saya harap ini bagus, dan saya harap Anda dapat menemukan jawaban yang Anda butuhkan.",
  ui_story_5029_50290001_37_dialog_content = "Apapun itu, harap diingat...",
  ui_story_5029_50290001_38_dialog_content = "Keajaiban bersamamu.",
  ui_story_5029_50290001_39_option_content = "Kartu Asal: Bulan",
  ui_story_5029_50290001_40_dialog_content = "Bulan yang lembut. Tidak semua memiliki kesempatan untuk menenangkan kerutannya…",
  ui_story_5029_50290001_41_dialog_content = "Ha ha. Apakah ini pilihanmu?",
  ui_story_5029_50290001_42_dialog_content = "Saya harap ini bagus, dan saya harap Anda dapat menemukan jawaban yang Anda butuhkan.",
  ui_story_5029_50290001_43_dialog_content = "Apapun itu, ingatlah...",
  ui_story_5029_50290001_44_dialog_content = "Keajaiban bersamamu.",
  ui_story_5029_50290001_45_dialog_content = "Kartu Asal: Bintang",
  ui_story_5029_50290001_46_dialog_content = "Bintang yang berkedip. Tidak semua memiliki kesempatan untuk mengungkap misterinya ...",
  ui_story_5029_50290001_47_dialog_content = "Ha ha. Apakah ini pilihanmu?",
  ui_story_5029_50290001_48_dialog_content = "Saya harap ini bagus, dan saya harap Anda dapat menemukan jawaban yang Anda butuhkan.",
  ui_story_5029_50290001_49_dialog_content = "Apapun itu, harap diingat...",
  ui_story_5029_50290001_50_dialog_content = "Keajaiban bersamamu.",
  ui_story_5029_50290001_51_dialog_content = "Pilih apa-apa",
  ui_story_5029_50290001_52_dialog_content = "Ada apa, sayangku?",
  ui_story_5029_50290001_53_dialog_content = "Mengapa Anda tidak mengangkat jari Anda dan memilih satu masa depan dengan kemungkinan tak terbatas?",
  ui_story_5029_50290001_54_dialog_content = "Tidak...",
  ui_story_5029_50290001_55_dialog_content = "Anda tidak ingin mengetahui nasib Anda dan mengendalikannya?",
  ui_story_5029_50290001_56_dialog_content = "Saya membuat nasib saya sendiri.",
  ui_story_5029_50290001_57_dialog_content = "Haha, gairah mendidih Anda membakar udara malam yang padat.",
  ui_story_5029_50290001_58_dialog_content = "Jangan terlalu serius. Itu hanya tipuan dengan ilusi.",
  ui_story_5029_50290001_59_dialog_content = "Mengapa Anda tidak berpura-pura bahwa ini adalah mimpi Anda sendiri?",
  ui_story_5029_50290001_60_dialog_content = "Saya hampir bisa melihat bagaimana mimpi itu berubah berdasarkan kartu-kartu ini.",
  ui_story_5029_50290001_61_dialog_content = "Saya tahu, memilih jawaban tertentu akan menghasilkan akhir yang baik.",
  ui_story_5029_50290001_62_dialog_content = "Ada cahaya dari pantai, sisa-sisa cahaya dari hutan belantara, dan kedamaian di tengah keramaian…",
  ui_story_5029_50290001_63_dialog_content = "Tapi mereka hanya sementara dan sekilas.",
  ui_story_5029_50290001_64_dialog_content = "Daripada mencari kenyamanan mimpi, saya lebih suka memanfaatkan setiap kesempatan dalam kehidupan nyata.",
  ui_story_5029_50290001_65_dialog_content = "Mungkin akan ada penyesalan dan penyesalan...",
  ui_story_5029_50290001_66_dialog_content = "Tapi saya percaya saya hanya bisa belajar apa yang benar-benar perlu saya lakukan dengan melewatinya.",
  ui_story_5029_50290001_67_dialog_content = "Dan itulah masa depan yang benar-benar saya inginkan.",
  ui_story_5029_50290001_68_dialog_content = "Saya pikir ... sudah waktunya untuk bangun.",
  ui_story_5029_50290001_69_dialog_content = "Hadirin yang saya hormati, jika ini yang Anda inginkan... Saya tidak akan memaksa Anda.",
  ui_story_5029_50290001_70_dialog_content = "Sebuah pertunjukan membutuhkan penonton yang kooperatif.",
  ui_story_5029_50290001_71_dialog_content = "Sepertinya kita harus mencobanya lagi lain kali.",
  ui_story_5029_50290001_72_dialog_content = "Tapi mungkin... <color=#793f76>mereka</color> Bisa bantu saya.",
  ui_story_5029_50290001_73_dialog_content = "Tunggu!",
  ui_story_5029_50290001_74_dialog_content = "Siapa yang Anda maksud?",
  ui_story_5029_50290001_75_dialog_content = "Eh? Kenapa aku... berjemur di pantai?",
  ui_story_5029_50290001_76_dialog_content = "Apakah semua itu... hanya mimpi?",
  ui_story_5029_50290001_77_dialog_content = "Menarik. Apakah saya baru saja memiliki banyak mimpi di dalam mimpi?",
  ui_story_5029_50290001_78_dialog_content = "<color=#828282>Brak!</color>",
  ui_story_5029_50290001_79_dialog_content = "Pria! Hampir saja...",
  ui_story_5029_50290001_80_dialog_content = "Hei, Nama Pemain! Apakah kamu baik-baik saja?",
  ui_story_5029_50290001_81_dialog_content = "Bisakah Anda melempar bola kembali?",
  ui_story_5029_50290001_82_dialog_content = "Berapa lama Anda akan berbaring di sana? Ayo bergabung dengan kami!",
  ui_story_5029_50290001_83_dialog_content = "I-iya! Aku datang!",
  ui_story_5029_50290001_84_dialog_content = "Hm? Apakah saya menginjak sesuatu?",
  ui_story_5029_50290001_85_dialog_content = "Bukankah ini…",
  ui_story_5029_50290001_86_dialog_content = "Sebuah <color=#793f76>Kartu Asal</color>?",
  ui_story_5029_50290002_1_dialog_content = "PlayerName.",
  ui_story_5029_50290002_2_dialog_content = "...",
  ui_story_5029_50290002_3_dialog_content = "Apa kau bisa mendengarku?",
  ui_story_5029_50290002_4_dialog_content = "Apakah Anda menderita kerusakan otak karena jatuh yang berat itu...?",
  ui_story_5029_50290002_5_dialog_content = "PlayerName, tunggu saja...",
  ui_story_5029_50290002_6_dialog_content = "Saya akan mencoba untuk melihat apakah ada klinik di sekitar!",
  ui_story_5029_50290002_7_dialog_content = "Tunggu...",
  ui_story_5029_50290002_8_dialog_content = "Hah?",
  ui_story_5029_50290002_9_option_content = "Jangan pergi.",
  ui_story_5029_50290002_10_dialog_content = "Kamu sudah sadar?",
  ui_story_5029_50290002_11_dialog_content = "Jangan khawatir. Aku tidak akan meninggalkanmu.",
  ui_story_5029_50290002_12_dialog_content = "Sekarang... Bisakah kau melepaskan tanganku?",
  ui_story_5029_50290002_13_dialog_content = "Oh...",
  ui_story_5029_50290002_14_option_content = "Tidak ada dokter.",
  ui_story_5029_50290002_15_dialog_content = "Anda sudah bangun? Kurasa kau tidak membutuhkan dokter.",
  ui_story_5029_50290002_16_dialog_content = "Aku tidak tahu kau takut dokter.",
  ui_story_5029_50290002_17_dialog_content = "Tapi saya menyarankan fisik jika Anda punya waktu.",
  ui_story_5029_50290002_18_dialog_content = "Bukan itu...",
  ui_story_5029_50290002_19_option_content = "Itu bukan urusan Anda.",
  ui_story_5029_50290002_20_dialog_content = "Bukannya aku ingin menjadikannya bisnisku.",
  ui_story_5029_50290002_21_dialog_content = "Karena tempat ini berada dalam yurisdiksi Lumopolis, saya memiliki hak untuk menjaga jalanan tetap bersih dari sampah.",
  ui_story_5029_50290002_22_dialog_content = "Sekarang setelah Anda bangun. Jaga dirimu.",
  ui_story_5029_50290002_23_dialog_content = "Hah? Carleen, biar saya jelaskan...!",
  ui_story_5029_50290002_24_option_content = "Jangan pukul aku!",
  ui_story_5029_50290002_25_dialog_content = "Ahem... Apa yang kamu katakan?",
  ui_story_5029_50290002_26_dialog_content = "Mengapa saya memukul Anda tanpa alasan?",
  ui_story_5029_50290002_27_dialog_content = "Oh...",
  ui_story_5029_50290002_28_dialog_content = "Maafkan aku!",
  ui_story_5029_50290002_29_dialog_content = "Kurasa aku belum sepenuhnya terbangun dari mimpi... Tolong, lupakan omong kosong itu.",
  ui_story_5029_50290002_30_dialog_content = "Mimpi...?",
  ui_story_5029_50290002_31_dialog_content = "Baik. Selama kamu baik-baik saja. Anda perlu tangan untuk bangun?",
  ui_story_5029_50290002_32_dialog_content = "...",
  ui_story_5029_50290002_33_dialog_content = "Carleen! Jadi di sana Anda ... Hah? Anda di sini juga, PlayerName?",
  ui_story_5029_50290002_34_dialog_content = "Mengapa Anda berbaring di tanah? Anda akan masuk angin!",
  ui_story_5029_50290002_35_dialog_content = "Sini, biarkan aku membantumu berdiri.",
  ui_story_5029_50290002_36_option_content = "T-Terima kasih!",
  ui_story_5029_50290002_37_dialog_content = "Tidak ada masalah besar. Sama-sama.",
  ui_story_5029_50290002_38_option_content = "Tidak masalah. Saya bisa melakukannya sendiri.",
  ui_story_5029_50290002_39_dialog_content = "Eh... Baiklah.",
  ui_story_5029_50290002_39X1_dialog_content = "Ugh...! aku kram...!",
  ui_story_5029_50290002_40_dialog_content = "Makanya saya bilang jangan memaksakan diri...",
  ui_story_5029_50290002_41_dialog_content = "Omong-omong...",
  ui_story_5029_50290002_42_dialog_content = "Apa yang kalian berdua lakukan di sini?",
  ui_story_5029_50290002_43_dialog_content = "Sejujurnya... Saya tidak ingat.",
  ui_story_5029_50290002_44_dialog_content = "Anda tidak? Sama sekali?",
  ui_story_5029_50290002_45_dialog_content = "Ya...",
  ui_story_5029_50290002_46_dialog_content = "Anda jatuh mencoba untuk mencatat itu <color=#793f76>pemberitahuan hadiah</color> di dinding.",
  ui_story_5029_50290002_47_dialog_content = "Karunia?",
  ui_story_5029_50290002_48_dialog_content = "Ya. Anda memegangnya di tangan Anda.",
  ui_story_5029_50290002_49_dialog_content = "Tanganku... Kau tidak bercanda!",
  ui_story_5029_50290002_50_dialog_content = "<color=#828282>Detektif ingin membantu mengambil pusaka keluarga yang hilang. PEMBAYARAN TINGGI.</color>",
  ui_story_5029_50290002_51_dialog_content = "<color=#828282>Catat pemberitahuan ini untuk dihubungi.</color>",
  ui_story_5029_50290002_52_dialog_content = "Ini benar-benar pekerjaan, yang bergaji tinggi!",
  ui_story_5029_50290002_53_dialog_content = "Apakah saya benar-benar menurunkannya sendiri? Kenapa aku tidak mengingatnya sama sekali?",
  ui_story_5029_50290002_54_dialog_content = "Tapi Anda bahkan tidak ragu-ragu untuk menurunkannya.",
  ui_story_5029_50290002_55_dialog_content = "Saya hanya membaca beberapa novel detektif... Saya belum pernah melakukannya sebelumnya!",
  ui_story_5029_50290002_56_dialog_content = "Saya tidak tahu apa yang saya pikirkan!",
  ui_story_5029_50290002_57_dialog_content = "Gaji tinggi yang Anda terima, mungkin.",
  ui_story_5029_50290002_58_dialog_content = "Tidak perlu menjelaskan. Saya mengerti.",
  ui_story_5029_50290002_59_dialog_content = "Saya pikir Harbour City aman dan makmur. Saya tidak percaya ada pencurian yang begitu serius di sini!",
  ui_story_5029_50290002_60_dialog_content = "Dan mengapa korban tidak mendekati sarangnya sejak awal?",
  ui_story_5029_50290002_61_dialog_content = "Saya tidak berpikir laird bisa membantu dengan ini ...",
  ui_story_5029_50290002_62_dialog_content = "Semua lebih baik untuk kita? Untuk apa kita berdiri?",
  ui_story_5029_50290002_63_dialog_content = "Karena kita punya waktu, ayo jadi detektif dan dapatkan uang!",
  ui_story_5029_50290002_64_dialog_content = "Aku akan menyetujuinya—sebagai Penjaga Lumo.",
  ui_story_5029_50290002_65_dialog_content = "Ini terjadi di dalam yurisdiksi Lumopolis. Saya ingin berurusan dengan kriminal secara hukum.",
  ui_story_5029_50290002_66_dialog_content = "Apakah itu berarti ... kita tidak akan bisa mendapatkan hadiahnya?",
  ui_story_5029_50290002_67_dialog_content = "...",
  ui_story_5029_50290002_68_dialog_content = "Kyllo. Pergi untuk rencana B, sekarang!",
  ui_story_5029_50290002_69_dialog_content = "Lihat!",
  ui_story_5029_50290002_70_dialog_content = "Seseorang mengalahkan kami dengan pemberitahuan hadiah...!",
  ui_story_5029_50290002_71_dialog_content = "Ha ha! Kerja bagus, Kylo.",
  ui_story_5029_50290002_72_dialog_content = "Fi? Dari mana asalmu kali ini?",
  ui_story_5029_50290002_73_option_content = "Saya pikir Anda adalah seorang bandit ...",
  ui_story_5029_50290002_74_dialog_content = "PlayerName, aku akan marah jika kamu mengatakan itu!",
  ui_story_5029_50290002_74X1_dialog_content = "Ayo. Aku bukan bandit!",
  ui_story_5029_50290002_75_dialog_content = "Saya hanya ingin tahu apa yang dilihat oleh binatang ajaib saya, PlayerName.",
  ui_story_5029_50290002_76_option_content = "Mengesankan untuk seorang extrozoologist...",
  ui_story_5029_50290002_77_dialog_content = "Anda menyembunyikan aroma Anda dengan baik.",
  ui_story_5029_50290002_78_dialog_content = "Hehe. Tentu saja.",
  ui_story_5029_50290002_79_dialog_content = "Bagaimana lagi saya bisa menangkap Anda di tempat pertama?",
  ui_story_5029_50290002_80_dialog_content = "Bagaimanapun, biarkan aku melihat apa yang kamu lihat.",
  ui_story_5029_50290002_81_dialog_content = "Hanya, jangan beri aku ketakutan melompat lain kali.",
  ui_story_5029_50290002_82_dialog_content = "Wow! Ini adalah karunia!",
  ui_story_5029_50290002_83_dialog_content = "Kyllo, ini hari keberuntungan kita! Kami dapat membayar akomodasi kami!",
  ui_story_5029_50290002_84_dialog_content = "Lo, lo, lo!",
  ui_story_5029_50290002_85_dialog_content = "Tuanku yang bodoh hanya memberiku sedikit biaya perjalanan untuk perjalanan yang begitu jauh.",
  ui_story_5029_50290002_86_dialog_content = "Hampir tidak cukup bagi saya untuk menikmati makanan enak dan melakukan hal-hal menyenangkan! Huh! Aku akan menunjukkan kepada tuanku bahwa...",
  ui_story_5029_50290002_87_dialog_content = "Saya bisa menyelesaikan tugas yang diberikan dan mendapatkan uang di sepanjang jalan!",
  ui_story_5029_50290002_88_dialog_content = "Lo, lo, lo!",
  ui_story_5029_50290002_89_dialog_content = "Fia, kamu tidak berpikir untuk mengambil hadiah ini juga, kan?",
  ui_story_5029_50290002_90_dialog_content = "Ini bukan permainan.",
  ui_story_5029_50290002_91_dialog_content = "Karunia ini berarti kita akan berurusan dengan penjahat yang sebenarnya.",
  ui_story_5029_50290002_92_dialog_content = "Aku, aku...",
  ui_story_5029_50290002_93_dialog_content = "Jangan meremehkan saya!",
  ui_story_5029_50290002_94_dialog_content = "Aku bahkan bisa menjinakkan binatang buas yang paling ganas! Aku takut tidak ada penjahat!",
  ui_story_5029_50290002_95_dialog_content = "Fia, penjahat sangat berbeda dari binatang ajaib.",
  ui_story_5029_50290002_96_dialog_content = "Bahkan PlayerName tidak akan memihakku!?",
  ui_story_5029_50290002_97_dialog_content = "Saya tahu! Itu karena Anda menginginkan hadiah ini untuk diri Anda sendiri!",
  ui_story_5029_50290002_98_dialog_content = "Kalau begitu, kira kita akan memiliki <color=#793f76>kompetisi</color>.",
  ui_story_5029_50290002_99_dialog_content = "Siapa yang menangkap penjahat mendapat hadiah? Itu sebenarnya ide yang bagus.",
  ui_story_5029_50290002_100_dialog_content = "Jika itu masalahnya, Anda lebih baik bersiap-siap.",
  ui_story_5029_50290002_101_dialog_content = "Saya memiliki banyak pengalaman di sisi saya melayani sebagai Penjaga Lumo.",
  ui_story_5029_50290002_102_dialog_content = "Uhm... Tapi aku...",
  ui_story_5029_50290002_103_dialog_content = "Maaf membuatmu menunggu lama.",
  ui_story_5029_50290002_104_dialog_content = "Saya kontak Anda untuk karunia ini. Saya Zane.",
  ui_story_5029_50290002_105_dialog_content = "Ikuti saya jika Anda telah memutuskan untuk mengambil tugas ini.",
  ui_story_5029_50290003_1_dialog_content = "PlayerName.",
  ui_story_5029_50290003_2_dialog_content = "...",
  ui_story_5029_50290003_3_dialog_content = "PlayerName, jangan menakuti saya!",
  ui_story_5029_50290003_4_dialog_content = "Anda berhasil melewati begitu banyak bahaya dan krisis!",
  ui_story_5029_50290003_5_dialog_content = "Anda tidak akan mati otak karena jatuh, kan?",
  ui_story_5029_50290003_6_dialog_content = "Oh, saya ingat ada alat pendukung kehidupan di Colossus.",
  ui_story_5029_50290003_7_dialog_content = "Nama Pemain, tunggu. Aku akan membawamu!",
  ui_story_5029_50290003_8_dialog_content = "Kamu akan baik-baik saja!",
  ui_story_5029_50290003_9_dialog_content = "Aku…",
  ui_story_5029_50290003_10_dialog_content = "Terima kasih Tuhan, Anda akhirnya bangun!",
  ui_story_5029_50290003_11_option_content = "Aku sangat takut!",
  ui_story_5029_50290003_12_dialog_content = "Jangan khawatir, Nama Pemain. Aku disini bersama mu.",
  ui_story_5029_50290003_13_dialog_content = "Kota ini aman. Anda baru saja jatuh secara tidak sengaja.",
  ui_story_5029_50290003_14_dialog_content = "Jangan takut. Aku akan melindungimu.",
  ui_story_5029_50290003_15_dialog_content = "Hah? Apa yang saya katakan?",
  ui_story_5029_50290003_16_option_content = "Syukurlah aku memilikimu.",
  ui_story_5029_50290003_17_dialog_content = "Hah?",
  ui_story_5029_50290003_18_dialog_content = "Mengapa berkata seperti itu?",
  ui_story_5029_50290003_19_dialog_content = "Itu membuatku merona.",
  ui_story_5029_50290003_20_dialog_content = "Hmm... aku...",
  ui_story_5029_50290003_21_option_content = "Aku baik-baik saja.",
  ui_story_5029_50290003_22_dialog_content = "Sungguh?",
  ui_story_5029_50290003_23_dialog_content = "Apakah Anda sakit kepala? Atau sakit di tempat lain?",
  ui_story_5029_50290003_24_dialog_content = "Tidak ada apa-apa. Aku baik-baik saja, hanya itu...",
  ui_story_5029_50290003_25_option_content = "Saya tidak perlu Anda khawatir tentang saya.",
  ui_story_5029_50290003_26_dialog_content = "Kamu...",
  ui_story_5029_50290003_27_dialog_content = "Apakah musim gugur itu mengubah kepribadianmu!?",
  ui_story_5029_50290003_28_dialog_content = "Apakah saya harus membuat Anda jatuh lagi untuk mendapatkan PlayerName yang normal kembali?",
  ui_story_5029_50290003_29_dialog_content = "Hai, Vice! Apa yang sedang kamu lakukan!?",
  ui_story_5029_50290003_30_dialog_content = "Biar kujelaskan...",
  ui_story_5029_50290003_31_dialog_content = "Aku bermimpi aneh.",
  ui_story_5029_50290003_32_dialog_content = "Jadi, tolong jangan pedulikan apa yang baru saja saya katakan ...",
  ui_story_5029_50290003_33_dialog_content = "Baik. Selama kamu baik-baik saja.",
  ui_story_5029_50290003_34_dialog_content = "Ini dingin di lantai. Anda lebih baik bangun.",
  ui_story_5029_50290003_35_dialog_content = "Di Sini. Biarkan aku membantumu berdiri.",
  ui_story_5029_50290003_36_dialog_content = "Terima kasih…",
  ui_story_5029_50290003_37_dialog_content = "Vice, mengapa kamu di sini? Saya pikir Anda akan pergi ke museum untuk menumbuhkan keanggunan?",
  ui_story_5029_50290003_38_dialog_content = "Heh... Aku mengalami sedikit masalah di jalan.",
  ui_story_5029_50290003_39_dialog_content = "Hm? Nama Pemain ada di sini ...?",
  ui_story_5029_50290003_40_dialog_content = "Anda tidak terlihat begitu baik. Apa yang terjadi?",
  ui_story_5029_50290003_41_option_content = "Tidak ada yang utama.",
  ui_story_5029_50290003_42_dialog_content = "Saya merasa lebih baik sekarang Carleen ada di sini juga.",
  ui_story_5029_50290003_43_dialog_content = "Jangan khawatir. Harbour City cukup aman.",
  ui_story_5029_50290003_44_option_content = "Ini semua karena tempat kumuh ini.",
  ui_story_5029_50290003_45_dialog_content = "Pemeliharaan jalan di Harbour City sangat buruk... Aku terjatuh.",
  ui_story_5029_50290003_45X1_dialog_content = "Jalannya bagus sekali. Apakah Anda yakin itu kesalahan jalan?",
  ui_story_5029_50290003_45X2_dialog_content = "(Adalah Carleen marah? Argh! Saya hampir lupa ini adalah wilayah Lumopolis... Lebih baik saya mengubah topik sekarang.)",
  ui_story_5029_50290003_46_dialog_content = "Aku ingat... Aku bermimpi aneh saat itu.",
  ui_story_5029_50290003_47_dialog_content = "Tapi saya tidak ingat persis mimpinya...",
  ui_story_5029_50290003_48_dialog_content = "Hah? Apakah kamu lupa?",
  ui_story_5029_50290003_49_dialog_content = "Anda melihat <color=#793f76>pemberitahuan hadiah</color> di dinding, dan Anda hanya perlu mengambilnya untuk mendapatkan biaya perjalanan...",
  ui_story_5029_50290003_50_dialog_content = "Dan kau terpeleset saat mencoba merobeknya dari dinding.",
  ui_story_5029_50290003_51_dialog_content = "Karunia?",
  ui_story_5029_50290003_52_dialog_content = "Ya. PlayerName memegangnya.",
  ui_story_5029_50290003_53_dialog_content = "Tanganku... Kau tidak bercanda!",
  ui_story_5029_50290003_54_dialog_content = "<color=#828282>Detektif ingin membantu mengambil pusaka keluarga yang hilang. PEMBAYARAN TINGGI.</color>",
  ui_story_5029_50290003_55_dialog_content = "<color=#828282>Catat pemberitahuan ini untuk dihubungi.</color>",
  ui_story_5029_50290003_56_dialog_content = "Apakah saya benar-benar menurunkannya sendiri? Kenapa aku tidak mengingatnya sama sekali?",
  ui_story_5029_50290003_57_dialog_content = "Aku melihatmu bertingkah ceria saat aku lewat sini.",
  ui_story_5029_50290003_58_dialog_content = "Anda bahkan menangkap saya dan mencoba mencari tahu berapa \"gaji tinggi\" ...",
  ui_story_5029_50290003_59_dialog_content = "Saya hanya membaca beberapa novel detektif... Saya belum pernah melakukannya sebelumnya!",
  ui_story_5029_50290003_60_dialog_content = "Karena kita punya waktu, mari kita cari tahu seperti apa menjadi detektif dan dapatkan uang!",
  ui_story_5029_50290003_61_dialog_content = "Saya pikir Harbour City aman dan makmur. Aku tidak percaya ada pencurian yang begitu serius di sini!",
  ui_story_5029_50290003_62_dialog_content = "Dan mengapa korban tidak mendekati sarangnya sejak awal?",
  ui_story_5029_50290003_63_dialog_content = "Saya tidak berpikir laird bisa membantu dengan ini ...",
  ui_story_5029_50290003_64_dialog_content = "Ini terjadi di dalam yurisdiksi Lumopolis, saya tidak bisa menutup mata begitu saja.",
  ui_story_5029_50290003_65_dialog_content = "Saya ingin berurusan dengan kriminal secara sah sebagai Penjaga Lumo.",
  ui_story_5029_50290003_66_dialog_content = "Apakah itu berarti ... kita tidak akan bisa mendapatkan hadiahnya?",
  ui_story_5029_50290003_67_dialog_content = "...",
  ui_story_5029_50290003_68_dialog_content = "Kyllo. Pergi untuk rencana C, sekarang!",
  ui_story_5029_50290003_69_dialog_content = "Lihat!",
  ui_story_5029_50290003_70_dialog_content = "Seseorang mengalahkan kami dengan pemberitahuan hadiah...!",
  ui_story_5029_50290003_71_dialog_content = "Ha ha! Kerja bagus, Kylo.",
  ui_story_5029_50290003_72_dialog_content = "Fi? Dari mana asalmu kali ini?",
  ui_story_5029_50290003_73_option_content = "Saya pikir Anda adalah seorang bandit ...",
  ui_story_5029_50290003_74_dialog_content = "PlayerName, aku akan marah jika kamu mengatakan itu!",
  ui_story_5029_50290003_74X1_dialog_content = "Ayo. Aku bukan bandit!",
  ui_story_5029_50290003_75_dialog_content = "Saya hanya ingin tahu apa yang dilihat oleh binatang ajaib saya, PlayerName.",
  ui_story_5029_50290003_76_option_content = "Mengesankan untuk seorang extrozoologist...",
  ui_story_5029_50290003_77_dialog_content = "Anda menyembunyikan aroma Anda dengan baik.",
  ui_story_5029_50290003_78_dialog_content = "Hehe. Tentu saja.",
  ui_story_5029_50290003_79_dialog_content = "Bagaimana lagi saya bisa menangkap Anda di tempat pertama?",
  ui_story_5029_50290003_80_dialog_content = "Ayo, mari kita lihat apa yang kamu lihat.",
  ui_story_5029_50290003_81_dialog_content = "Hanya, jangan beri aku ketakutan melompat lain kali.",
  ui_story_5029_50290003_82_dialog_content = "Wow! Ini adalah hadiah!",
  ui_story_5029_50290003_83_dialog_content = "Kyllo, ini hari keberuntungan kita! Kami dapat membayar akomodasi kami!",
  ui_story_5029_50290003_84_dialog_content = "Lo, lo, lo!",
  ui_story_5029_50290003_85_dialog_content = "Tuanku yang bodoh hanya memberiku sedikit biaya perjalanan untuk perjalanan yang begitu jauh.",
  ui_story_5029_50290003_86_dialog_content = "Hampir tidak cukup bagi saya untuk menikmati makanan enak dan melakukan hal-hal menyenangkan! Huh! Aku akan menunjukkan kepada tuanku bahwa...",
  ui_story_5029_50290003_87_dialog_content = "Saya bisa menyelesaikan tugas yang diberikan dan mendapatkan uang di sepanjang jalan!",
  ui_story_5029_50290003_88_dialog_content = "Lo, lo, lo!",
  ui_story_5029_50290003_89_dialog_content = "Fia, kamu tidak berpikir untuk mengambil hadiah ini juga, kan?",
  ui_story_5029_50290003_90_dialog_content = "Ini bukan permainan.",
  ui_story_5029_50290003_91_dialog_content = "Karunia ini berarti kita akan berurusan dengan penjahat yang sebenarnya.",
  ui_story_5029_50290003_92_dialog_content = "Aku, aku...",
  ui_story_5029_50290003_93_dialog_content = "Jangan meremehkan saya!",
  ui_story_5029_50290003_94_dialog_content = "Aku bahkan bisa menjinakkan binatang buas yang paling ganas! Aku takut tidak ada penjahat!",
  ui_story_5029_50290003_95_dialog_content = "Fia, penjahat sangat berbeda dari binatang ajaib.",
  ui_story_5029_50290003_96_dialog_content = "Bahkan PlayerName tidak akan memihakku!?",
  ui_story_5029_50290003_97_dialog_content = "Saya tahu! Itu karena Anda menginginkan hadiah ini untuk diri Anda sendiri!",
  ui_story_5029_50290003_98_dialog_content = "Kalau begitu, kira kita akan memiliki <color=#793f76>kompetisi</color>.",
  ui_story_5029_50290003_99_dialog_content = "Siapa yang menangkap penjahat mendapat hadiah? Itu sebenarnya ide yang bagus.",
  ui_story_5029_50290003_100_dialog_content = "Jika itu masalahnya, Anda lebih baik bersiap-siap.",
  ui_story_5029_50290003_101_dialog_content = "Saya memiliki banyak pengalaman di sisi saya melayani sebagai Penjaga Lumo.",
  ui_story_5029_50290003_102_dialog_content = "Uhm... Tapi aku...",
  ui_story_5029_50290003_103_dialog_content = "Maaf membuatmu menunggu lama.",
  ui_story_5029_50290003_104_dialog_content = "Saya kontak Anda untuk karunia ini. Saya Zane.",
  ui_story_5029_50290003_105_dialog_content = "Ikuti saya jika Anda telah memutuskan untuk mengambil tugas ini.",
  ui_story_5029_50290004_1_dialog_content = "PlayerName!",
  ui_story_5029_50290004_2_dialog_content = "...",
  ui_story_5029_50290004_3_dialog_content = "Ugh... PlayerName terlempar ke tanah?",
  ui_story_5029_50290004_4_dialog_content = "Kyl, apa yang harus kita lakukan?",
  ui_story_5029_50290004_5_dialog_content = "Lihat! Lihat!",
  ui_story_5029_50290004_6_dialog_content = "Benar. Saya seorang ahli ekstrozoologi.",
  ui_story_5029_50290004_7_dialog_content = "Saya harus tetap tenang dan membiarkan pelatihan ahli saya membimbing saya.",
  ui_story_5029_50290004_8_dialog_content = "Saya ingat ada penyebutan metode yang digunakan untuk membangkitkan binatang buas yang luar biasa dalam buklet yang diberikan master kepada saya...",
  ui_story_5029_50290004_8X1_dialog_content = "Ini harus bekerja pada Caelestit, kan?",
  ui_story_5029_50290004_9_dialog_content = "Ini dia! Dia membutuhkan Kyllo untuk memberinya mulut ke mulut?",
  ui_story_5029_50290004_10_dialog_content = "lihat?",
  ui_story_5029_50290004_11_dialog_content = "*Batuk-batuk*",
  ui_story_5029_50290004_12_dialog_content = "Di sana, Anda akhirnya bangun!",
  ui_story_5029_50290004_13_option_content = "Terima kasih, Fia.",
  ui_story_5029_50290004_14_dialog_content = "Bukan masalah.",
  ui_story_5029_50290004_15_dialog_content = "Aku pergi keluar dari cara saya untuk menangkap Anda. Ini tanggung jawab saya untuk merawat Anda.",
  ui_story_5029_50290004_16_dialog_content = "Oh, Kyllo juga membantu!",
  ui_story_5029_50290004_17_dialog_content = "Lihat!",
  ui_story_5029_50290004_18_option_content = "Aku merasa lebih baik sekarang.",
  ui_story_5029_50290004_19_dialog_content = "Tentu saja.",
  ui_story_5029_50290004_20_dialog_content = "Anda aman dengan Kyllo dan saya di sekitar!",
  ui_story_5029_50290004_21_dialog_content = "Lihat!",
  ui_story_5029_50290004_22_option_content = "Apa kau mencoba membunuhku!?",
  ui_story_5029_50290004_23_dialog_content = "PlayerName… Kau…",
  ui_story_5029_50290004_24_dialog_content = "Tegakkan kepalamu! Kyllo dan aku mencoba menyelamatkanmu!",
  ui_story_5029_50290004_25_dialog_content = "Hmph! Sepertinya memiliki Caelestite tidak lebih baik dari Eclipsite!",
  ui_story_5029_50290004_26_dialog_content = "Lihat!",
  ui_story_5029_50290004_27_option_content = "Jauhi aku, Kyllo!",
  ui_story_5029_50290004_28_dialog_content = "Anda tidak perlu berteriak!",
  ui_story_5029_50290004_29_dialog_content = "Tapi, ya, kira Anda tidak perlu Kyllo untuk menyelamatkan Anda sekarang setelah Anda bangun dan sekitar.",
  ui_story_5029_50290004_30_dialog_content = "Lo, lo, lo!",
  ui_story_5029_50290004_31_dialog_content = "Apakah itu... semua mimpi?",
  ui_story_5029_50290004_32_dialog_content = "Anda bermimpi selama waktu singkat bahwa Anda pingsan?",
  ui_story_5029_50290004_33_dialog_content = "Caelestite suka melamun... Lebih baik aku mengingat ini. Ini penting.",
  ui_story_5029_50290004_34_dialog_content = "Hei, Anda tidak perlu menuliskannya ...",
  ui_story_5029_50290004_35_dialog_content = "Hm? PlayerName?",
  ui_story_5029_50290004_36_dialog_content = "Mengapa Anda berbaring di tanah? Anda akan masuk angin!",
  ui_story_5029_50290004_37_dialog_content = "Sini, biarkan aku membantumu berdiri.",
  ui_story_5029_50290004_38_option_content = "T-Terima kasih!",
  ui_story_5029_50290004_39_dialog_content = "Tidak ada masalah besar. Sama-sama.",
  ui_story_5029_50290004_40_option_content = "Tidak masalah. Saya bisa melakukannya sendiri.",
  ui_story_5029_50290004_41_dialog_content = "Eh... Baiklah.",
  ui_story_5029_50290004_41X1_dialog_content = "Ugh...! aku kram...!",
  ui_story_5029_50290004_42_dialog_content = "Makanya saya bilang jangan memaksakan diri...",
  ui_story_5029_50290004_43_dialog_content = "\"Caelestite gugup di sekitar gadis-gadis ...\"",
  ui_story_5029_50290004_44_dialog_content = "Hah? Fia mencatat perilaku PlayerName?",
  ui_story_5029_50290004_45_dialog_content = "Ya. Mempelajari kebiasaan dan kepribadian binatang yang menakjubkan membuat komunikasi dengan mereka lebih mudah.",
  ui_story_5029_50290004_46_dialog_content = "Tapi aku tidak gugup!",
  ui_story_5029_50290004_47_dialog_content = "Apakah begitu? Omong-omong... Apa itu di tanganmu?",
  ui_story_5029_50290004_48_dialog_content = "Hah? Aku bahkan tidak sadar aku memegang ini... Apa ini?",
  ui_story_5029_50290004_49_dialog_content = "Ha! Anda akan merobek benda ini dari dinding tadi.",
  ui_story_5029_50290004_49X1_dialog_content = "Dia berusaha terlalu keras dan jatuh.",
  ui_story_5029_50290004_50_dialog_content = "Jadi apa yang membuat seorang Caelestit begitu tertarik?",
  ui_story_5029_50290004_51_dialog_content = "Biarkan aku melihat, biarkan aku melihat!",
  ui_story_5029_50290004_52_dialog_content = "Awas! Anda akan merobeknya ...",
  ui_story_5029_50290004_53_dialog_content = "<color=#828282>Wuush…</color>",
  ui_story_5029_50290004_54_dialog_content = "Ahhhh! Angin meniupnya!",
  ui_story_5029_50290004_55_dialog_content = "Kyllo. Pergi untuk Rencana A, sekarang!",
  ui_story_5029_50290004_56_dialog_content = "Lihat!",
  ui_story_5029_50290004_57_dialog_content = "Tunggu! Tidak dibutuhkan! Seseorang mengambilnya untuk kita!",
  ui_story_5029_50290004_58_dialog_content = "Oh, kalian di sini.",
  ui_story_5029_50290004_59_dialog_content = "Apakah Anda kehilangan selembar kertas ini?",
  ui_story_5029_50290004_60_dialog_content = "Ya. Ini memegang rahasia PlayerName!",
  ui_story_5029_50290004_61_dialog_content = "Carleen, secarik kertas itu...",
  ui_story_5029_50290004_62_option_content = "Terima kasih telah mengambilkannya untukku.",
  ui_story_5029_50290004_63_dialog_content = "Sama-sama.",
  ui_story_5029_50290004_64_dialog_content = "Padahal, saya sebenarnya tidak tahu apa yang ada di sana.",
  ui_story_5029_50290004_65_option_content = "Berikan kepadaku!",
  ui_story_5029_50290004_65X1_dialog_content = "Apakah Anda sudah bergabung dengan Rediesel Wrench?",
  ui_story_5029_50290004_65X2_dialog_content = "Kenapa kau terdengar tidak sopan seperti mereka...?",
  ui_story_5029_50290004_66_dialog_content = "B-Karena aku sebenarnya tidak tahu apa yang ada di sana...",
  ui_story_5029_50290004_67_dialog_content = "Itu mungkin fitnah yang tidak berdasar.",
  ui_story_5029_50290004_68_dialog_content = "Di Sini. Periksa sendiri.",
  ui_story_5029_50290004_69_dialog_content = "<color=#828282>Detektif ingin membantu mengambil pusaka keluarga yang hilang. PEMBAYARAN TINGGI.</color>",
  ui_story_5029_50290004_70_dialog_content = "<color=#828282>Catat pemberitahuan ini untuk dihubungi.</color>",
  ui_story_5029_50290004_71_dialog_content = "Wow! Ini adalah <color=#793f76>karunia</color>!",
  ui_story_5029_50290004_72_dialog_content = "Saya pikir Harbour City aman dan makmur. Saya tidak percaya ada pencurian yang begitu serius di sini!",
  ui_story_5029_50290004_73_dialog_content = "Apakah saya benar-benar menurunkannya sendiri? Kenapa aku tidak mengingatnya sama sekali?",
  ui_story_5029_50290004_74_dialog_content = "Saya mengerti, PlayerName.",
  ui_story_5029_50290004_74X1_dialog_content = "Prospek gaji tinggi menghampiri Anda, mungkin.",
  ui_story_5029_50290004_75_dialog_content = "Saya hanya membaca beberapa novel detektif... Saya belum pernah melakukannya sebelumnya!",
  ui_story_5029_50290004_76_dialog_content = "Saya tidak tahu apa yang saya pikirkan!",
  ui_story_5029_50290004_77_dialog_content = "PlayerName, apakah kamu takut?",
  ui_story_5029_50290004_78_dialog_content = "Lalu aku akan mengambilnya! Kyllo dan saya hanya khawatir tentang uang!",
  ui_story_5029_50290004_79_dialog_content = "Lo, lo, lo!",
  ui_story_5029_50290004_80_dialog_content = "Tuanmu tidak memberimu biaya perjalanan?",
  ui_story_5029_50290004_81_dialog_content = "Tuanku yang bodoh hanya memberiku sedikit biaya perjalanan untuk perjalanan yang begitu jauh.",
  ui_story_5029_50290004_82_dialog_content = "Hampir tidak cukup bagi saya untuk menikmati makanan enak dan melakukan hal-hal menyenangkan! Huh! Aku akan menunjukkan kepada tuanku bahwa...",
  ui_story_5029_50290004_83_dialog_content = "Saya bisa menyelesaikan tugas yang diberikan dan mendapatkan uang di sepanjang jalan!",
  ui_story_5029_50290004_84_dialog_content = "Aneh...",
  ui_story_5029_50290004_85_dialog_content = "Mengapa korban tidak mendekati sarangnya sejak awal?",
  ui_story_5029_50290004_86_dialog_content = "Saya tidak berpikir laird bisa membantu dengan ini ...",
  ui_story_5029_50290004_87_dialog_content = "Ha ha! Lalu aku harus menunjukkan pada laird betapa luar biasanya aku!",
  ui_story_5029_50290004_88_dialog_content = "Ini bukan permainan.",
  ui_story_5029_50290004_89_dialog_content = "Karunia ini berarti kita akan berurusan dengan penjahat yang sebenarnya.",
  ui_story_5029_50290004_90_dialog_content = "Aku, aku...",
  ui_story_5029_50290004_91_dialog_content = "Jangan meremehkan saya!",
  ui_story_5029_50290004_92_dialog_content = "Aku bahkan bisa menjinakkan binatang buas yang paling ganas! Aku takut tidak ada penjahat!",
  ui_story_5029_50290004_93_dialog_content = "Fia, penjahat sangat berbeda dari binatang ajaib.",
  ui_story_5029_50290004_94_dialog_content = "Bahkan PlayerName tidak akan memihakku!?",
  ui_story_5029_50290004_95_dialog_content = "Apa pun yang terjadi. Ini terjadi di dalam yurisdiksi Lumopolis, saya tidak bisa menutup mata begitu saja.",
  ui_story_5029_50290004_96_dialog_content = "Saya ingin berurusan dengan kriminal secara sah sebagai Penjaga Lumo.",
  ui_story_5029_50290004_97_dialog_content = "Apakah itu berarti ... kita tidak akan bisa mendapatkan hadiahnya?",
  ui_story_5029_50290004_98_dialog_content = "Saya tahu! Kalian semua ingin aku menjauhinya...",
  ui_story_5029_50290004_99_dialog_content = "Itu karena Anda menginginkan hadiah ini untuk diri Anda sendiri!",
  ui_story_5029_50290004_100_dialog_content = "Kalau begitu, kira kita akan memiliki <color=#793f76>kompetisi</color>.",
  ui_story_5029_50290004_101_dialog_content = "Siapa yang menangkap penjahat mendapat hadiah? Itu sebenarnya ide yang bagus.",
  ui_story_5029_50290004_102_dialog_content = "Jika itu masalahnya, Anda lebih baik bersiap-siap.",
  ui_story_5029_50290004_103_dialog_content = "Saya memiliki banyak pengalaman di sisi saya melayani sebagai Penjaga Lumo.",
  ui_story_5029_50290004_104_dialog_content = "Uhm... Tapi aku...",
  ui_story_5029_50290004_105_dialog_content = "Maaf membuatmu menunggu lama.",
  ui_story_5029_50290004_106_dialog_content = "Saya kontak Anda untuk karunia ini. Saya Zane.",
  ui_story_5029_50290004_107_dialog_content = "Ikuti saya jika Anda telah memutuskan untuk mengambil tugas ini.",
  ui_story_5029_50290005_1_dialog_content = "Tunggu, bukankah tempat ini...",
  ui_story_5029_50290005_2_dialog_content = "Aku tak percaya apa yang kulihat!",
  ui_story_5029_50290005_3_dialog_content = "Jadi, <color=#793f76>dia</color> adalah klien?",
  ui_story_5029_50290005_4_dialog_content = "Apa yang kau bicarakan? Bisakah Anda berbicara dengan jelas?",
  ui_story_5029_50290005_5_dialog_content = "Kenapa kalian semua tidak masuk?",
  ui_story_5029_50290005_6_dialog_content = "Tuanku menunggumu di dalam, detektif.",
  ui_story_5029_50290005_7_dialog_content = "Anda mendengar itu? Dia baru saja memanggil kita \"detektif\"!",
  ui_story_5029_50290005_8_dialog_content = "Diam. Seorang detektif akan menjaga profil rendah.",
  ui_story_5029_50290005_9_dialog_content = "Pfff... Kamu menjadi semakin seperti tuanku, PlayerName.",
  ui_story_5029_50290005_10_dialog_content = "Selamat datang, detektif...",
  ui_story_5029_50290005_11_dialog_content = "Kita bertemu lagi, Guru <color=#793f76>Elvis</color>.",
  ui_story_5029_50290005_12_dialog_content = "Putri Carleen?",
  ui_story_5029_50290005_13_dialog_content = "Saya tidak berpikir... Mengapa Anda dan semua teman Anda ada di sini?",
  ui_story_5029_50290005_14_dialog_content = "Zan, apa yang terjadi di sini? Saya meminta Anda untuk menemukan detektif.",
  ui_story_5029_50290005_15_dialog_content = "Aku…",
  ui_story_5029_50290005_16_dialog_content = "Kami di sini untuk pekerjaan itu, tentu saja.",
  ui_story_5029_50290005_17_dialog_content = "Anda semua adalah tamu di sini. Tidak tepat jika ada tamu yang bekerja untuk saya.",
  ui_story_5029_50290005_18_dialog_content = "Jadi tamu tidak bisa menerima hadiah?",
  ui_story_5029_50290005_19_dialog_content = "Heheh... Kalau begitu kurasa hanya aku yang bukan salah satu tamumu!",
  ui_story_5029_50290005_20_dialog_content = "Maka saya akan mengambil pekerjaan ini sendiri!",
  ui_story_5029_50290005_21_dialog_content = "Saya minta maaf. Itu bukanlah apa yang saya maksud.",
  ui_story_5029_50290005_22_dialog_content = "Semua pengunjung Harbour City adalah tamu saya.",
  ui_story_5029_50290005_23_dialog_content = "Bukankah tur keliling kota lebih cocok?",
  ui_story_5029_50290005_24_dialog_content = "Nah, memecahkan kasus adalah pengalaman tersendiri.",
  ui_story_5029_50290005_25_dialog_content = "Ini mungkin akan menunjukkan kepada kita lebih banyak tentang kota dan orang-orangnya.",
  ui_story_5029_50290005_26_dialog_content = "Hahaha, saya tidak pernah meragukan bahwa Anda semua adalah orang-orang yang luar biasa dengan keterampilan ...",
  ui_story_5029_50290005_27_dialog_content = "Dengan bantuan Anda, saya yakin saya dapat menemukan kembali barang saya dalam waktu singkat.",
  ui_story_5029_50290005_28_dialog_content = "Jadi, apa yang Anda kehilangan?",
  ui_story_5029_50290005_29_dialog_content = "Ini adalah <color=#793f76>kotak perak</color>.",
  ui_story_5029_50290005_30_dialog_content = "Kotak itu dirancang dan dipoles oleh tangan seniman paling terkenal di Lumopolis, Leonardo. Ini benar-benar sebuah karya seni.",
  ui_story_5029_50290005_31_dialog_content = "Leonardo... Aku mendengar nama itu di suatu tempat.",
  ui_story_5029_50290005_32_dialog_content = "Leonardo menempati cukup banyak halaman dalam sejarah seni Lumopolis. Dia adalah seorang seniman berbakat.",
  ui_story_5029_50290005_33_dialog_content = "Karya-karyanya masih sangat banyak dicari oleh banyak kolektor.",
  ui_story_5029_50290005_34_dialog_content = "Saya tidak tahu Anda mendapatkan salah satu dari mereka.",
  ui_story_5029_50290005_35_dialog_content = "Saya berharap kita bertemu lebih awal, Yang Mulia.",
  ui_story_5029_50290005_36_dialog_content = "Namun, kotak itu...",
  ui_story_5029_50290005_37_dialog_content = "Oh, jangan pikirkan hal-hal yang tidak berguna itu. Seperti apa sebenarnya?",
  ui_story_5029_50290005_38_dialog_content = "Cukup benar. Kami membutuhkan deskripsi yang lebih rinci, seperti berat dan ukurannya.",
  ui_story_5029_50290005_39_dialog_content = "Akan lebih baik lagi jika Anda memiliki gambarnya.",
  ui_story_5029_50290005_40_dialog_content = "Ini.",
  ui_story_5029_50290005_41_dialog_content = "Ini draft dari saya. Saya harap ini berguna untuk Anda.",
  ui_story_5029_50290005_42_dialog_content = "Ini luar biasa... seperti gambar desain dengan kualitas unggul.",
  ui_story_5029_50290005_43_dialog_content = "Apa cuma aku di Astra yang gak bisa menggambar?",
  ui_story_5029_50290005_44_dialog_content = "Kyl, coba lihat. Kita akan diberi makan jika kita menemukan benda ini!",
  ui_story_5029_50290005_45_dialog_content = "Lihat!",
  ui_story_5029_50290005_46_dialog_content = "Di mana kotak perak ini disimpan? Dan kapan hilang?",
  ui_story_5029_50290005_47_dialog_content = "Saya selalu menyimpannya di <color=#793f76>lemari kecil</color> dalam studi saya.",
  ui_story_5029_50290005_48_dialog_content = "Aku bahkan mengeluarkannya sebelum makan siang kemarin, tapi itu hilang saat makan malam.",
  ui_story_5029_50290005_49_dialog_content = "Yang berarti itu dicuri antara <color=#793f76>kemarin siang dan sore hari</color>.",
  ui_story_5029_50290005_50_dialog_content = "Apakah ada orang yang masuk atau keluar rumah selama waktu ini?",
  ui_story_5029_50290005_51_dialog_content = "Hanya tiga.",
  ui_story_5029_50290005_52_dialog_content = "Yang pertama adalah <color=#793f76>pembantu</color> yang datang untuk membersihkan rumah sekitar tengah hari.",
  ui_story_5029_50290005_53_dialog_content = "Yang kedua adalah <color=#793f76>duchess dari Lumopolis</color> yang datang berkunjung pada sore hari.",
  ui_story_5029_50290005_54_dialog_content = "Yang terakhir adalah <color=#793f76>pedagang</color> yang datang untuk membahas beberapa investasi bisnis di sore hari.",
  ui_story_5029_50290005_55_dialog_content = "Hanya tiga... Seberapa yakin kamu?",
  ui_story_5029_50290005_56_dialog_content = "Saya dapat mengkonfirmasi itu.",
  ui_story_5029_50290005_56X1_dialog_content = "Saya berada di pintu dari siang hingga larut malam. Hanya mereka bertiga yang masuk dan keluar ruangan.",
  ui_story_5029_50290005_57_dialog_content = "Laird sedang sibuk kemarin, dan ketiga tamu itu tinggal di kamar sendiri untuk sementara waktu di rumah.",
  ui_story_5029_50290005_58_dialog_content = "Setelah tamu terakhir pergi, saya mengunci pintu dan pergi makan malam.",
  ui_story_5029_50290005_59_dialog_content = "Ketika Anda kembali, apakah Anda menemukan kuncinya rusak?",
  ui_story_5029_50290005_60_dialog_content = "Tidak. Semua jendela itu <color=#793f76>terkunci dari dalam</color> demikian juga.",
  ui_story_5029_50290005_61_dialog_content = "Itu sebabnya saya menganggap itu harus menjadi salah satu dari tiga.",
  ui_story_5029_50290005_62_dialog_content = "Hanya tiga tersangka? Kedengarannya seperti kasus yang mudah!",
  ui_story_5029_50290005_63_dialog_content = "Bawa saja mereka untuk diinterogasi!",
  ui_story_5029_50290005_64_dialog_content = "Pasti ada alasan mengapa itu tidak layak.",
  ui_story_5029_50290005_65_dialog_content = "Ahem... Anda benar lagi, Yang Mulia.",
  ui_story_5029_50290005_66_dialog_content = "Salah satunya adalah Lumo Noble yang terhormat dan pelayannya sangat direkomendasikan oleh Umbraton Guild.",
  ui_story_5029_50290005_67_dialog_content = "Pedagang itu juga memiliki keinginan kuat untuk berinvestasi di kota... Aku tidak bisa merusak hubungan di antara mereka.",
  ui_story_5029_50290005_68_dialog_content = "Di sisi lain, seperti yang kalian semua mungkin tahu, ada perayaan yang berlangsung di kota yang akan berlangsung selama beberapa hari.",
  ui_story_5029_50290005_69_dialog_content = "Sebagai laird, saya tidak bisa membuat marah atau membebani siapa pun dengan urusan pribadi saya.",
  ui_story_5029_50290005_70_dialog_content = "Itu sebabnya Zane adalah satu-satunya yang tahu tentang ini.",
  ui_story_5029_50290005_71_dialog_content = "Yang berarti Anda ingin kami <color=#793f76>selidiki ini dengan tenang</color>?",
  ui_story_5029_50290005_72_dialog_content = "Investigasi rahasia, kedengarannya seperti sebuah tantangan.",
  ui_story_5029_50290005_73_dialog_content = "Saya tahu ini sulit, jadi yang saya minta hanyalah <color=#793f76>dapatkan kembali kotak perak itu</color> untuk saya.",
  ui_story_5029_50290005_74_dialog_content = "Jika itu benar-benar salah satu dari tiga ...",
  ui_story_5029_50290005_75_dialog_content = "Aku akan menemukan cara untuk membuat mereka pergi.",
  ui_story_5029_50290006_1_dialog_content = "Laird saat ini sibuk dengan masalah terkait perayaan.",
  ui_story_5029_50290006_2_dialog_content = "Anda dapat dengan bebas menyelidiki rumah untuk mencari petunjuk.",
  ui_story_5029_50290006_3_dialog_content = "Saya akan berada di sini di lobi jika Anda memiliki pertanyaan.",
  ui_story_5029_50290006_4_dialog_content = "Dan saya bisa menyampaikan pertanyaan Anda ke laird, jika Anda membutuhkan saya.",
  ui_story_5029_50290006_5_option_content = "Bicaralah dengan Zane",
  ui_story_5029_50290006_6_dialog_content = "Ya?",
  ui_story_5029_50290006_7_option_content = "Penggunaan rumah",
  ui_story_5029_50290006_8_dialog_content = "Rumah ini berfungsi sebagai laird's <color=#793f76>Perpustakaan</color> dan kantornya.",
  ui_story_5029_50290006_9_dialog_content = "Laird menghabiskan sebagian besar waktunya di rumah ini sendirian.",
  ui_story_5029_50290006_10_dialog_content = "Dia juga kadang-kadang bertemu dengan beberapa teman dekat di sini.",
  ui_story_5029_50290006_11_dialog_content = "Dan laird menyimpan kunci rumah ini padanya.",
  ui_story_5029_50290006_12_dialog_content = "Ada lagi?",
  ui_story_5029_50290006_13_option_content = "Tata letak rumah",
  ui_story_5029_50290006_14_dialog_content = "Ini adalah rumah dua lantai.",
  ui_story_5029_50290006_15_dialog_content = "Lobi dan lounge kafe kecil berada di lantai pertama.",
  ui_story_5029_50290006_16_dialog_content = "Ruang kerja laird ada di lantai dua.",
  ui_story_5029_50290006_17_dialog_content = "Ada lagi?",
  ui_story_5029_50290006_18_option_content = "Kamu siapa",
  ui_story_5029_50290006_19_dialog_content = "Saya Zane, pengawal laird.",
  ui_story_5029_50290006_20_dialog_content = "Saya dulu hanya pekerja dermaga biasa.",
  ui_story_5029_50290006_21_dialog_content = "Saya hanya di sini hari ini karena laird mempercayai saya.",
  ui_story_5029_50290006_22_dialog_content = "Ada lagi?",
  ui_story_5029_50290006_23_option_content = "Tidak ada lagi",
  ui_story_5029_50290006_24_dialog_content = "Jangan ragu jika Anda memiliki pertanyaan lain.",
  ui_story_5029_50290006_25_dialog_content = "Terima kasih.",
  ui_story_5029_50290006_26_option_content = "Lihat sekeliling",
  ui_story_5029_50290006_27_dialog_content = "Apakah semua orang memulai penyelidikan mereka sendiri?",
  ui_story_5029_50290006_28_dialog_content = "Hmph.",
  ui_story_5029_50290006_29_dialog_content = "...",
  ui_story_5029_50290006_30_dialog_content = "...",
  ui_story_5029_50290006_31_dialog_content = "(Sekarang ini canggung...)",
  ui_story_5029_50290006_32_dialog_content = "(Apakah mereka benar-benar melihat satu sama lain sebagai lawan?)",
  ui_story_5029_50290006_33_dialog_content = "(Tunggu... Apa aku juga bersaing dengan mereka?)",
  ui_story_5029_50290006_34_dialog_content = "Apa yang harus kulakukan...?",
  ui_story_5029_50290006_35_option_content = "Berbicara kepada Carleen",
  ui_story_5029_50290006_36_dialog_content = "Carleen…",
  ui_story_5029_50290006_37_dialog_content = "Ada apa?",
  ui_story_5029_50290006_38_option_content = "Saya ingin bekerja sama dengan Anda.",
  ui_story_5029_50290006_39_dialog_content = "Bersatu denganku...? Tentu.",
  ui_story_5029_50290006_40_dialog_content = "Namun, Anda harus lulus tes.",
  ui_story_5029_50290006_41_option_content = "Semoga berhasil!",
  ui_story_5029_50290006_42_dialog_content = "Terima kasih.",
  ui_story_5029_50290006_43_dialog_content = "Saya tidak akan merusak reputasi Pengawal Lumo.",
  ui_story_5029_50290006_44_dialog_content = "(Dan dia baru saja pergi?)",
  ui_story_5029_50290006_45_dialog_content = "(Apakah saya mengatakan sesuatu yang salah...?)",
  ui_story_5029_50290006_46_option_content = "Oh, anu, tak apa.",
  ui_story_5029_50290006_47_dialog_content = "Saya akan melanjutkan penyelidikan saya, kalau begitu.",
  ui_story_5029_50290006_48_dialog_content = "(Mengapa raut wajahnya itu? Sangat dingin.)",
  ui_story_5029_50290006_49_dialog_content = "(Saya lebih baik kembali bekerja.)",
  ui_story_5029_50290006_50_dialog_content = "(Di mana saya harus memeriksa selanjutnya?)",
  ui_story_5029_50290006_51_option_content = "Berbicara kepada Vice",
  ui_story_5029_50290006_52_dialog_content = "Vice…",
  ui_story_5029_50290006_53_dialog_content = "Kenapa, PlayerName?",
  ui_story_5029_50290006_54_option_content = "Saya ingin bekerja sama dengan Anda.",
  ui_story_5029_50290006_55_dialog_content = "Kupikir kau tidak akan pernah bertanya!",
  ui_story_5029_50290006_56_dialog_content = "Tapi ada sesuatu...",
  ui_story_5029_50290006_57_option_content = "Semoga berhasil!",
  ui_story_5029_50290006_58_dialog_content = "Aku akan melakukan yang terbaik.",
  ui_story_5029_50290006_59_dialog_content = "Dan rebut hadiahnya!",
  ui_story_5029_50290006_60_dialog_content = "(Dan dia pergi, begitu saja!)",
  ui_story_5029_50290006_61_option_content = "Oh, anu, tak apa.",
  ui_story_5029_50290006_62_dialog_content = "Baiklah.",
  ui_story_5029_50290006_63_dialog_content = "(Vice bertingkah aneh hari ini...)",
  ui_story_5029_50290006_64_dialog_content = "(Saya lebih baik kembali bekerja.)",
  ui_story_5029_50290006_65_dialog_content = "(Di mana saya harus memeriksa selanjutnya?)",
  ui_story_5029_50290006_66_option_content = "Bicaralah dengan Fia",
  ui_story_5029_50290006_67_dialog_content = "fi...",
  ui_story_5029_50290006_68_dialog_content = "Apa?",
  ui_story_5029_50290006_69_option_content = "Saya ingin bekerja sama dengan Anda.",
  ui_story_5029_50290006_70_dialog_content = "Sungguh?",
  ui_story_5029_50290006_71_dialog_content = "Yah, saya sudah mendapatkan Kyllo, tetapi semakin banyak semakin meriah.",
  ui_story_5029_50290006_72_option_content = "Semoga berhasil!",
  ui_story_5029_50290006_73_dialog_content = "Saya tidak perlu Anda mengatakan itu kepada saya.",
  ui_story_5029_50290006_74_dialog_content = "Kyllo dan aku tidak butuh keberuntungan!",
  ui_story_5029_50290006_75_dialog_content = "(Apakah dia memperlakukan saya sebagai saingan juga?)",
  ui_story_5029_50290006_76_option_content = "Oh, anu, tak apa.",
  ui_story_5029_50290006_77_dialog_content = "Kalau begitu berhenti menggangguku!",
  ui_story_5029_50290006_78_dialog_content = "(Fia sangat tidak ramah hari ini...)",
  ui_story_5029_50290006_79_dialog_content = "(Saya lebih baik kembali bekerja.)",
  ui_story_5029_50290006_80_dialog_content = "(Di mana saya harus memeriksa selanjutnya?)",
  ui_story_5029_50290006_81_option_content = "Selidiki sendiri",
  ui_story_5029_50290006_82_dialog_content = "(Mereka semua terlihat sibuk.)",
  ui_story_5029_50290006_83_dialog_content = "(Saya lebih baik melakukan penyelidikan sendiri ...)",
  ui_story_5029_50290007_1_dialog_content = "Ini rumah besar... Di mana kita harus mulai?",
  ui_story_5029_50290007_2_dialog_content = "Coba kuingat...",
  ui_story_5029_50290007_3_option_content = "Ruang belajar",
  ui_story_5029_50290007_4_dialog_content = "Begitu banyak rak buku... Ini benar-benar perpustakaan di sini.",
  ui_story_5029_50290007_5_dialog_content = "Saya mendengar bahwa Elvis adalah siswa top di Dawn Akademi. Dia suka membaca.",
  ui_story_5029_50290007_6_dialog_content = "Saya tidak berpikir ada orang yang lebih baik dari Anda.",
  ui_story_5029_50290007_7_dialog_content = "...",
  ui_story_5029_50290007_8_dialog_content = "Sejujurnya, dia senior saya, dan saya menghormatinya.",
  ui_story_5029_50290007_9_dialog_content = "Padahal ini bukan waktunya untuk itu. Mari kita cari tempat.",
  ui_story_5029_50290007_10_dialog_content = "Apakah ada yang menonjol bagi Anda?",
  ui_story_5029_50290007_11_dialog_content = "Coba kuingat...",
  ui_story_5029_50290007_12_option_content = "Rak buku pertama",
  ui_story_5029_50290007_13_dialog_content = "Ada sebuah buku di rak yang sepertinya pernah kulihat di tempat lain.",
  ui_story_5029_50290007_14_dialog_content = "Shinnosuke Sinsa Jilid 1?",
  ui_story_5029_50290007_15_dialog_content = "Saya ingat novel ini cukup menggantung...",
  ui_story_5029_50290007_16_dialog_content = "Saya tidak berpikir laird akan membaca fiksi pop...",
  ui_story_5029_50290007_17_dialog_content = "Oh? Saya hanya berpikir buku yang bagus layak mendapatkan popularitas.",
  ui_story_5029_50290007_18_dialog_content = "Saya kira Anda benar. Logika pemikiran saya terlalu kaku...",
  ui_story_5029_50290007_19_dialog_content = "Tapi mengapa hanya ada Volume 1 dan bukan seluruh koleksinya? Laird bisa berhenti di satu buku saja?",
  ui_story_5029_50290007_20_dialog_content = "Itu pasti sesuatu yang akan kutanyakan pada Zane nanti.",
  ui_story_5029_50290007_21_dialog_content = "Ada yang lain?",
  ui_story_5029_50290007_22_option_content = "Desk",
  ui_story_5029_50290007_23_dialog_content = "Buku di atas meja... terlihat berbeda dari buku lainnya.",
  ui_story_5029_50290007_24_dialog_content = "Apakah begitu? Mari lihat.",
  ui_story_5029_50290007_25_dialog_content = "<color=#828282>Membanting!</color>",
  ui_story_5029_50290007_26_dialog_content = "Gawat...",
  ui_story_5029_50290007_27_dialog_content = "Apa yang terjadi? Astaga... Kamu menghancurkan buku kuno paling berharga milik laird!?",
  ui_story_5029_50290007_28_dialog_content = "Aku harus melaporkan ini ke laird!",
  ui_story_5029_50290007_29_dialog_content = "Aku tidak bermaksud melakukan itu!",
  ui_story_5029_50290007_30_dialog_content = "Laird adalah orang yang sangat pengertian. Aku akan menjelaskan padanya.",
  ui_story_5029_50290007_31_dialog_content = "Apakah ada hal lain selain itu?",
  ui_story_5029_50290007_32_option_content = "Kabinet kecil",
  ui_story_5029_50290007_33_dialog_content = "Laird berkata dia menyimpan kotak perak di lemari kecil ini.",
  ui_story_5029_50290007_34_dialog_content = "Hmm... Tidak ada tanda aneh. Jendela tidak dibuka paksa, seperti yang dikatakan laird.",
  ui_story_5029_50290007_35_dialog_content = "Tapi itu masih ceroboh. Dia seharusnya memasang kunci di lemari yang menyimpan benda tak ternilai itu.",
  ui_story_5029_50290007_36_dialog_content = "Tapi draft laird menunjukkan bahwa ada kunci di kotak itu sendiri.",
  ui_story_5029_50290007_37_dialog_content = "Itu aneh...",
  ui_story_5029_50290007_38_dialog_content = "Mungkin ada sesuatu yang lebih berharga di dalam kotak itu.",
  ui_story_5029_50290007_39_dialog_content = "Sekarang aku penasaran.",
  ui_story_5029_50290007_40_dialog_content = "Apakah ada hal lain selain itu?",
  ui_story_5029_50290007_41_option_content = "Itu saja",
  ui_story_5029_50290007_42_dialog_content = "Sepertinya tidak ada yang lain.",
  ui_story_5029_50290007_43_dialog_content = "Mari kita periksa kamar lain?",
  ui_story_5029_50290007_44_option_content = "Lobi",
  ui_story_5029_50290007_45_dialog_content = "Lobi mengarah ke kamar lain. Mungkin kita akan menemukan sesuatu di sana.",
  ui_story_5029_50290007_46_dialog_content = "Apakah ada yang menonjol bagi Anda?",
  ui_story_5029_50290007_47_dialog_content = "Coba kuingat...",
  ui_story_5029_50290007_48_option_content = "Pot bunga",
  ui_story_5029_50290007_49_dialog_content = "Kau sedang apa?",
  ui_story_5029_50290007_50_dialog_content = "Mencari petunjuk di pot bunga dekat jendela...",
  ui_story_5029_50290007_51_dialog_content = "Anda cukup teliti, bukan?",
  ui_story_5029_50290007_52_dialog_content = "Hmm? Elvis memelihara xerofit?",
  ui_story_5029_50290007_53_dialog_content = "Ini berduri. Hati-hati.",
  ui_story_5029_50290007_54_dialog_content = "Lihat. Tanaman pot ini sepertinya telah bersentuhan dengan sesuatu.",
  ui_story_5029_50290007_55_dialog_content = "Banyak duri yang hilang. Siapapun yang menyentuhnya pasti sakit...",
  ui_story_5029_50290007_56_dialog_content = "Ada yang lain?",
  ui_story_5029_50290007_57_option_content = "Meja kopi",
  ui_story_5029_50290007_58_dialog_content = "Ada sebuah buku di atas meja kopi yang sepertinya pernah kulihat di tempat lain.",
  ui_story_5029_50290007_59_dialog_content = "Shinnosuke Sinsa Jilid 1?",
  ui_story_5029_50290007_60_dialog_content = "Saya ingat novel ini cukup menggantung...",
  ui_story_5029_50290007_61_dialog_content = "Saya tidak berpikir laird akan membaca fiksi pop...",
  ui_story_5029_50290007_62_dialog_content = "Oh? Saya hanya berpikir buku yang bagus layak mendapatkan popularitas.",
  ui_story_5029_50290007_63_dialog_content = "Saya kira Anda benar. Logika pemikiran saya terlalu kaku...",
  ui_story_5029_50290007_64_dialog_content = "Tapi mengapa hanya ada Volume 1 dan bukan seluruh koleksinya? Laird bisa berhenti di satu buku saja?",
  ui_story_5029_50290007_65_dialog_content = "Itu pasti sesuatu yang akan kutanyakan pada Zane nanti.",
  ui_story_5029_50290007_66_dialog_content = "Ada yang lain?",
  ui_story_5029_50290007_67_option_content = "Dekorasi",
  ui_story_5029_50290007_68_dialog_content = "Keong yang indah...",
  ui_story_5029_50290007_69_dialog_content = "Saya mendengar bahwa jika Anda membisikkan keinginan Anda ke keong—",
  ui_story_5029_50290007_70_dialog_content = "Apakah keinginan Anda akan menjadi kenyataan?",
  ui_story_5029_50290007_71_dialog_content = "Jadi, Anda juga mendengar tentang kisah ini!",
  ui_story_5029_50290007_72_dialog_content = "Haruskah kita membuat permintaan ke keong?",
  ui_story_5029_50290007_73_dialog_content = "Anda cukup anak di hati, bukan? Masih percaya pada dongeng seperti itu.",
  ui_story_5029_50290007_74_dialog_content = "Tidak persis... Saya hanya berpikir bahwa saya akan memiliki kesempatan yang lebih baik jika saya mengatakannya.",
  ui_story_5029_50290007_75_dialog_content = "Sebut saja petunjuk, secara psikologis.",
  ui_story_5029_50290007_76_dialog_content = "Petunjuk...",
  ui_story_5029_50290007_77_dialog_content = "Nah, jika Anda merasa konyol mengatakan keinginan Anda kepada keong, Anda selalu bisa memberi tahu saya!",
  ui_story_5029_50290007_78_dialog_content = "Mungkin aku bisa mewujudkan keinginanmu.",
  ui_story_5029_50290007_79_dialog_content = "Apakah begitu? Maka saya berharap kita dapat segera menemukan beberapa petunjuk yang berguna.",
  ui_story_5029_50290007_80_dialog_content = "Aku akan segera melakukannya!",
  ui_story_5029_50290007_81_option_content = "Itu saja",
  ui_story_5029_50290007_82_dialog_content = "Sepertinya tidak ada yang lain.",
  ui_story_5029_50290007_83_dialog_content = "Mari kita periksa kamar lain?",
  ui_story_5029_50290007_84_option_content = "Kafe",
  ui_story_5029_50290007_85_dialog_content = "Kafe? Silakan lewat sini.",
  ui_story_5029_50290007_86_dialog_content = "Terkadang sang sarang tidak ingin diganggu, maka dibangunlah sebuah kafe di dalam rumah.",
  ui_story_5029_50290007_87_dialog_content = "Dia bahkan terkadang menyeduh kopi untuk tamunya secara pribadi.",
  ui_story_5029_50290007_88_dialog_content = "Jadi, Nama Pemain? Apakah ada yang menonjol bagi Anda?",
  ui_story_5029_50290007_89_dialog_content = "Coba kuingat...",
  ui_story_5029_50290007_90_option_content = "Kursi",
  ui_story_5029_50290007_91_dialog_content = "Anda ingin beristirahat sebentar?",
  ui_story_5029_50290007_92_dialog_content = "Aku baik-baik saja.",
  ui_story_5029_50290007_93_dialog_content = "Baiklah... Aku bisa terus berjalan juga!",
  ui_story_5029_50290007_94_dialog_content = "Hmm? Sebuah koran di kursi.",
  ui_story_5029_50290007_95_dialog_content = "Ini koran Umbraton dari kemarin.",
  ui_story_5029_50290007_96_dialog_content = "Itu dikirim ke Elvis begitu cepat?",
  ui_story_5029_50290007_97_dialog_content = "\"Caelestite tidak terlihat selama berhari-hari di Umbraton. Lovegator membeli jadwal Caelestite dengan harga tinggi...\"",
  ui_story_5029_50290007_98_dialog_content = "Berita macam apa ini!?",
  ui_story_5029_50290007_99_dialog_content = "Ahem... Jenis yang tidak ada hubungannya dengan kasus ini.",
  ui_story_5029_50290007_100_dialog_content = "Baik. Ada yang lain?",
  ui_story_5029_50290007_101_option_content = "Penghitung bar",
  ui_story_5029_50290007_102_dialog_content = "Ada sebuah buku di bar yang sepertinya pernah kulihat di tempat lain.",
  ui_story_5029_50290007_103_dialog_content = "Shinnosuke Sinsa Jilid 1?",
  ui_story_5029_50290007_104_dialog_content = "Saya ingat novel ini cukup menggantung...",
  ui_story_5029_50290007_105_dialog_content = "Saya tidak berpikir laird akan membaca fiksi pop...",
  ui_story_5029_50290007_106_dialog_content = "Oh? Saya hanya berpikir buku yang bagus layak mendapatkan popularitas.",
  ui_story_5029_50290007_107_dialog_content = "Saya kira Anda benar. Logika pemikiran saya terlalu kaku...",
  ui_story_5029_50290007_108_dialog_content = "Tapi mengapa hanya ada Volume 1 dan bukan seluruh koleksinya? Laird bisa berhenti di satu buku saja?",
  ui_story_5029_50290007_109_dialog_content = "Itu pasti sesuatu yang akan kutanyakan pada Zane nanti.",
  ui_story_5029_50290007_110_dialog_content = "Ada yang lain?",
  ui_story_5029_50290007_111_option_content = "Wall",
  ui_story_5029_50290007_112_dialog_content = "Ada begitu banyak lukisan minyak yang indah di dinding!",
  ui_story_5029_50290007_113_dialog_content = "Sapuan kuasnya sangat berani, tetapi karyanya memberikan dampak yang cukup besar dan kehadiran yang mencekik.",
  ui_story_5029_50290007_114_dialog_content = "Pikiran Elvis jelas tidak serapuh kelihatannya.",
  ui_story_5029_50290007_115_dialog_content = "Hah? Lukisan ini terlihat familiar...",
  ui_story_5029_50290007_116_dialog_content = "Bukankah itu...",
  ui_story_5029_50290007_117_dialog_content = "Aku ingat.",
  ui_story_5029_50290007_118_dialog_content = "Ini adalah potret ayahmu ketika dia masih muda, bukan?",
  ui_story_5029_50290007_119_dialog_content = "Mengapa Elvis menyimpan replikanya di sini?",
  ui_story_5029_50290007_120_dialog_content = "Untuk menunjukkan kesetiaannya yang abadi kepada Lumopolis, mungkin. Hahaha!",
  ui_story_5029_50290007_121_dialog_content = "Mungkin dia juga menyembunyikan potret Anda di suatu tempat.",
  ui_story_5029_50290007_122_dialog_content = "Saya lebih baik tidak menemukan satu ... demi dia.",
  ui_story_5029_50290007_123_dialog_content = "Selain itu... Ada lagi?",
  ui_story_5029_50290007_124_option_content = "Itu saja",
  ui_story_5029_50290007_125_dialog_content = "Sepertinya tidak ada yang lain.",
  ui_story_5029_50290007_126_dialog_content = "Mari kita periksa kamar lain?",
  ui_story_5029_50290007_127_option_content = "Tidak ada lagi yang bisa dilihat",
  ui_story_5029_50290007_128_dialog_content = "Saya pikir kami telah melalui semuanya.",
  ui_story_5029_50290007_129_dialog_content = "Sungguh?",
  ui_story_5029_50290007_130_dialog_content = "Ada tempat yang menurutku aneh... Aku akan melihat lagi.",
  ui_story_5029_50290007_131_dialog_content = "Saya akan berada di sofa jika Anda membutuhkan saya.",
  ui_story_5029_50290008_1_dialog_content = "Jadi kemana selanjutnya?",
  ui_story_5029_50290008_2_dialog_content = "Coba kuingat...",
  ui_story_5029_50290008_3_option_content = "Ruang belajar",
  ui_story_5029_50290008_4_dialog_content = "Begitu banyak rak buku... Ini benar-benar perpustakaan di sini.",
  ui_story_5029_50290008_5_dialog_content = "Jika mau, Anda dapat memiliki ruang baca sendiri di Colossus.",
  ui_story_5029_50290008_6_dialog_content = "Saya tahu! Jika kita mendapatkan uang hadiah, kita bisa menggunakannya untuk membangun ruang baca!",
  ui_story_5029_50290008_7_dialog_content = "Sekarang itu memotivasi! Mari kita lanjutkan penyelidikannya!",
  ui_story_5029_50290008_8_dialog_content = "Kemana selanjutnya...?",
  ui_story_5029_50290008_9_option_content = "Rak buku pertama",
  ui_story_5029_50290008_10_dialog_content = "Laird benar-benar membaca segala macam hal...",
  ui_story_5029_50290008_11_dialog_content = "Ada buku dengan nama yang bahkan aku tidak mengerti...",
  ui_story_5029_50290008_12_dialog_content = "Ada juga perpustakaan besar di Illumina. Anda dapat kembali ke Illumina dengan saya jika Anda ingin membaca ...",
  ui_story_5029_50290008_13_dialog_content = "Eh? Menjelajahi Pembagian Sosial Tenaga Kerja Di Antara Demi-Manusia: Menggunakan Wilayah Rahasia yang Hilang Sebagai Contoh...",
  ui_story_5029_50290008_14_dialog_content = "Bukankah ini makalah penelitian terbaru tentang masyarakat Demi-Human!?",
  ui_story_5029_50290008_15_dialog_content = "Aku bahkan belum sempat membacanya!",
  ui_story_5029_50290008_16_dialog_content = "Aku... Aku akan membaca fiksi pop di sampingnya.",
  ui_story_5029_50290008_17_dialog_content = "Tunggu! Tidak! Saya perlu menemukan lebih banyak petunjuk!",
  ui_story_5029_50290008_18_option_content = "Rak buku kedua",
  ui_story_5029_50290008_19_dialog_content = "Vice! Ada batu permata yang tertanam di dalam buku!",
  ui_story_5029_50290008_20_dialog_content = "Sepertinya pohon keluarga laird...",
  ui_story_5029_50290008_21_dialog_content = "Ini benar-benar buku yang dihias dengan mewah. Ini mungkin cukup berharga.",
  ui_story_5029_50290008_22_dialog_content = "Jika saya tahu semua nama klan saya, saya mungkin menginginkan buku seperti ini.",
  ui_story_5029_50290008_23_dialog_content = "PlayerName…",
  ui_story_5029_50290008_24_dialog_content = "Nah, Anda sebaiknya mulai menghasilkan sekarang.",
  ui_story_5029_50290008_25_dialog_content = "Hahahaha.",
  ui_story_5029_50290008_26_dialog_content = "Sebaiknya aku kembali mencari petunjuk.",
  ui_story_5029_50290008_27_option_content = "Kabinet kecil",
  ui_story_5029_50290008_28_dialog_content = "Laird berkata dia menyimpan kotak perak di lemari kecil ini.",
  ui_story_5029_50290008_29_dialog_content = "Tidak ada kunci di lemari ini.",
  ui_story_5029_50290008_30_dialog_content = "Dan tidak ada apa-apa di dalam sama sekali.",
  ui_story_5029_50290008_31_dialog_content = "Saya akan mendapatkan beberapa kunci untuk semua lemari saya.",
  ui_story_5029_50290008_32_dialog_content = "Dan aku akan tidur di kunci.",
  ui_story_5029_50290008_33_dialog_content = "Benar! Sekarang saya tahu.",
  ui_story_5029_50290008_34_dialog_content = "Saya pasti akan mencari di bawah bantal Anda untuk melihat apakah Anda menyembunyikan kunci apa pun.",
  ui_story_5029_50290008_35_dialog_content = "Aku…",
  ui_story_5029_50290008_36_dialog_content = "Sebaiknya aku kembali mencari petunjuk.",
  ui_story_5029_50290008_37_option_content = "Jangan berpikir kita melewatkan apa pun.",
  ui_story_5029_50290008_38_dialog_content = "Mari kita menuju kamar sebelah.",
  ui_story_5029_50290008_39_dialog_content = "Baik. Kemana?",
  ui_story_5029_50290008_40_option_content = "Lobi",
  ui_story_5029_50290008_41_dialog_content = "Ini adalah rumah yang besar. Laird hanya menggunakannya untuk bekerja?",
  ui_story_5029_50290008_42_dialog_content = "Saya merasa saya hanya bisa tinggal di sini ...",
  ui_story_5029_50290008_43_dialog_content = "Mengapa begitu iri? Anda sudah memiliki Colossus.",
  ui_story_5029_50290008_44_dialog_content = "Hehe, aku hanya penasaran.",
  ui_story_5029_50290008_45_dialog_content = "Hanya bercanda. Mari kembali bekerja.",
  ui_story_5029_50290008_46_dialog_content = "Kemana selanjutnya...?",
  ui_story_5029_50290008_47_option_content = "Pot bunga",
  ui_story_5029_50290008_48_dialog_content = "Mungkinkah ada beberapa alat di dalam pot?",
  ui_story_5029_50290008_49_dialog_content = "Anda benar-benar memiliki imajinasi yang kaya.",
  ui_story_5029_50290008_50_dialog_content = "Hm... Tidak ada. Betapa mengecewakan.",
  ui_story_5029_50290008_51_dialog_content = "Padahal bunganya cantik. Saya suka betapa menyegarkan baunya.",
  ui_story_5029_50290008_52_dialog_content = "Uhm... Kenapa aku merasa sedikit pusing?",
  ui_story_5029_50290008_53_dialog_content = "Mungkinkah itu bunga...?",
  ui_story_5029_50290008_54_dialog_content = "Zan, datang ke sini. Apakah bunga ini beracun?",
  ui_story_5029_50290008_55_dialog_content = "Sama sekali tidak. Ini oleander. Ini agak beracun secara alami.",
  ui_story_5029_50290008_56_dialog_content = "Selama Anda tidak menelannya, Anda seharusnya baik-baik saja.",
  ui_story_5029_50290008_57_dialog_content = "Tapi mengapa menanam bunga beracun di rumah...? Saya benar-benar tidak mendapatkan bangsawan ini.",
  ui_story_5029_50290008_58_dialog_content = "Ayo, Nama Pemain. Aku akan membawamu ke sofa.",
  ui_story_5029_50290008_59_dialog_content = "Tidak masalah. Aku baik-baik saja.",
  ui_story_5029_50290008_60_option_content = "Sofa",
  ui_story_5029_50290008_61_dialog_content = "Sofa ini nyaman...",
  ui_story_5029_50290008_62_dialog_content = "Kalau saja saya punya sofa seperti ini di Colossus.",
  ui_story_5029_50290008_63_dialog_content = "Ahem... Anda mungkin tidak tahu label harga untuk benda ini.",
  ui_story_5029_50290008_64_dialog_content = "...",
  ui_story_5029_50290008_65_dialog_content = "Lebih baik aku menjauhinya, kalau begitu.",
  ui_story_5029_50290008_66_dialog_content = "Kenapa?",
  ui_story_5029_50290008_67_dialog_content = "Setelah dipikir-pikir... Rumputnya cukup nyaman untukku.",
  ui_story_5029_50290008_68_dialog_content = "Fiuh, kami baru saja menghemat uang hari ini.",
  ui_story_5029_50290008_69_dialog_content = "Mari kita lanjutkan pencarian.",
  ui_story_5029_50290008_70_option_content = "Dekorasi",
  ui_story_5029_50290008_71_dialog_content = "Lihat, PlayerName, seekor keong!",
  ui_story_5029_50290008_72_dialog_content = "Itu cantik. Jarang sekali melihat keong sebesar itu!",
  ui_story_5029_50290008_73_dialog_content = "Saya mendengar bahwa kerang dan keong digunakan sebagai mata uang di beberapa pulau terpencil.",
  ui_story_5029_50290008_74_dialog_content = "Maka keong ini mungkin akan sangat berharga.",
  ui_story_5029_50290008_75_dialog_content = "Sayangnya, kami hanya membawa Nightium di sini.",
  ui_story_5029_50290008_76_dialog_content = "Tapi kalau kamu suka, kita bisa jalan-jalan di sepanjang pantai...",
  ui_story_5029_50290008_77_dialog_content = "Mungkin kita akan menemukan keong yang lebih besar dan lebih baik.",
  ui_story_5029_50290008_78_dialog_content = "Aku akan menahanmu untuk itu!",
  ui_story_5029_50290008_79_dialog_content = "Tidak masalah. Mari terus mencari.",
  ui_story_5029_50290008_80_option_content = "Jangan berpikir kita melewatkan apa pun.",
  ui_story_5029_50290008_81_dialog_content = "Mari kita menuju kamar sebelah.",
  ui_story_5029_50290008_82_dialog_content = "Baik. Kemana?",
  ui_story_5029_50290008_83_option_content = "Kafe",
  ui_story_5029_50290008_84_dialog_content = "Kafe? Silakan lewat sini.",
  ui_story_5029_50290008_85_dialog_content = "Terkadang sang sarang tidak ingin diganggu, maka dibangunlah sebuah kafe di dalam rumah.",
  ui_story_5029_50290008_86_dialog_content = "Dia bahkan terkadang menyeduh kopi untuk tamunya secara pribadi.",
  ui_story_5029_50290008_87_dialog_content = "Saya tidak tahu ada begitu banyak hal menakjubkan di sini.",
  ui_story_5029_50290008_88_dialog_content = "Begitu banyak hal... Di mana kita harus mulai?",
  ui_story_5029_50290008_89_option_content = "cangkir kopi",
  ui_story_5029_50290008_90_dialog_content = "Pola dan gaya cangkir ini semuanya berbeda!",
  ui_story_5029_50290008_91_dialog_content = "Anda dapat mengadakan pameran di cangkir ini sendirian!",
  ui_story_5029_50290008_92_dialog_content = "Hm? Aneh. Mengapa masih ada kopi di cangkir ini?",
  ui_story_5029_50290008_93_dialog_content = "Tamu itu mungkin tidak menyelesaikannya kemarin.",
  ui_story_5029_50290008_94_dialog_content = "<color=#828282>Ring-ring...</color>",
  ui_story_5029_50290008_95_dialog_content = "Sepertinya ada sesuatu di dalam.",
  ui_story_5029_50290008_96_dialog_content = "Mari kita keluarkan...",
  ui_story_5029_50290008_97_dialog_content = "Sebuah lencana. Saya pikir saya melihatnya di suatu tempat sebelumnya.",
  ui_story_5029_50290008_98_dialog_content = "Ini adalah lencana Ksatria Lumo!",
  ui_story_5029_50290008_99_dialog_content = "Mengapa di sini? Mungkinkah bangsawan dari kemarin sebenarnya ...",
  ui_story_5029_50290008_100_dialog_content = "Saya perlu bertanya kepada Zane tentang ini.",
  ui_story_5029_50290008_101_dialog_content = "Benar. Mari terus mencari.",
  ui_story_5029_50290008_102_option_content = "Kursi",
  ui_story_5029_50290008_103_dialog_content = "PlayerName, bisakah kamu menarik kursi itu?",
  ui_story_5029_50290008_104_dialog_content = "Tentu. Anda lelah?",
  ui_story_5029_50290008_105_dialog_content = "Tidak. Aku baru saja melihat sesuatu di kursi.",
  ui_story_5029_50290008_106_dialog_content = "Koran! Anda memiliki mata yang bagus.",
  ui_story_5029_50290008_107_dialog_content = "\"Andersen sepenuhnya mendukung Nina dalam menjalankan acara komersial besar...\"",
  ui_story_5029_50290008_108_dialog_content = "\"Berita orang dalam mengatakan dia pernah kabur dari rumah demi Caelestite.\"",
  ui_story_5029_50290008_109_dialog_content = "I-Itu sangat menyesatkan!",
  ui_story_5029_50290008_110_dialog_content = "Yah, itu tidak sepenuhnya salah.",
  ui_story_5029_50290008_111_dialog_content = "*Batuk-batuk*",
  ui_story_5029_50290008_112_dialog_content = "Mari terus mencari.",
  ui_story_5029_50290008_113_option_content = "Wall",
  ui_story_5029_50290008_114_dialog_content = "Lukisan-lukisan di dinding tampaknya cukup mahal juga.",
  ui_story_5029_50290008_115_dialog_content = "Mengapa pencuri itu tidak mengambilnya juga?",
  ui_story_5029_50290008_116_dialog_content = "Mungkin mereka tidak oleh beberapa seniman master.",
  ui_story_5029_50290008_117_dialog_content = "Ada lukisan aneh di sudut...",
  ui_story_5029_50290008_118_dialog_content = "Hah!? Bukankah ini lukisan yang kau berikan padaku? Mengapa di sini?",
  ui_story_5029_50290008_119_dialog_content = "Apakah ada nama distributor pada lukisan itu...?",
  ui_story_5029_50290008_120_dialog_content = "Hachi, Gin!?",
  ui_story_5029_50290008_121_dialog_content = "Mereka menjual replika lukisanku di sini!?",
  ui_story_5029_50290008_122_dialog_content = "Itu sebenarnya cukup prestasi di pihak mereka ...",
  ui_story_5029_50290008_123_dialog_content = "Tapi kita harus terus mencari.",
  ui_story_5029_50290008_124_option_content = "Jangan berpikir kita melewatkan apa pun.",
  ui_story_5029_50290008_125_dialog_content = "Mari kita menuju kamar sebelah.",
  ui_story_5029_50290008_126_dialog_content = "Baik. Kemana?",
  ui_story_5029_50290008_127_option_content = "Tidak ada lagi yang bisa dilihat",
  ui_story_5029_50290008_128_dialog_content = "Saya pikir kami telah melalui semuanya.",
  ui_story_5029_50290008_129_dialog_content = "Ada tempat yang menurutku aneh...",
  ui_story_5029_50290008_130_dialog_content = "Aku akan melihat lagi.",
  ui_story_5029_50290008_131_dialog_content = "Aku akan berada di sini di sofa.",
  ui_story_5029_50290009_1_dialog_content = "Jadi... Apa yang harus kita lakukan selanjutnya?",
  ui_story_5029_50290009_2_dialog_content = "Coba kuingat...",
  ui_story_5029_50290009_3_option_content = "Ruang belajar",
  ui_story_5029_50290009_4_dialog_content = "Kyllo, tetap dalam formasi! Tetap waspada!",
  ui_story_5029_50290009_5_dialog_content = "Lihat!",
  ui_story_5029_50290009_6_dialog_content = "Ada... formasi?",
  ui_story_5029_50290009_7_dialog_content = "Anda di depan, Kyllo di belakang. Saya di tengah.",
  ui_story_5029_50290009_7X1_dialog_content = "Ini adalah formasi naga!",
  ui_story_5029_50290009_8_dialog_content = "Apapun yang kamu katakan... Hmm. Ini adalah ruangan yang besar.",
  ui_story_5029_50290009_9_dialog_content = "Di mana kita harus mulai?",
  ui_story_5029_50290009_10_option_content = "Rak buku pertama",
  ui_story_5029_50290009_11_dialog_content = "Buku itu memakan banyak tempat.",
  ui_story_5029_50290009_12_dialog_content = "Sungguh penutup yang luar biasa...",
  ui_story_5029_50290009_13_dialog_content = "Mungkinkah ini buku legendaris yang mendorong orang untuk menjadi pemburu binatang buas yang menakjubkan!?",
  ui_story_5029_50290009_14_dialog_content = "Uhm... Ini sebenarnya adalah 1.001 Makhluk Fantastis milik tuanku...",
  ui_story_5029_50290009_15_dialog_content = "Sepertinya laird membuat sampul baru untuk buku itu.",
  ui_story_5029_50290009_16_dialog_content = "Aku tidak tahu laird membaca buku tuanku...",
  ui_story_5029_50290009_17_dialog_content = "Maka dia pasti menyukai buku saya juga!",
  ui_story_5029_50290009_18_dialog_content = "Jadi sudah keluar?",
  ui_story_5029_50290009_19_dialog_content = "Belum…",
  ui_story_5029_50290009_20_dialog_content = "Tapi aku pasti akan menjadi penulis yang lebih populer daripada tuanku!",
  ui_story_5029_50290009_21_dialog_content = "Baiklah, baiklah... Mari kita terus mencari.",
  ui_story_5029_50290009_22_option_content = "Wall",
  ui_story_5029_50290009_23_dialog_content = "lihat...",
  ui_story_5029_50290009_24_dialog_content = "Jangan takut, Kyl.",
  ui_story_5029_50290009_25_dialog_content = "Itu hanya tengkorak rusa.",
  ui_story_5029_50290009_26_dialog_content = "Lo-woo!",
  ui_story_5029_50290009_27_dialog_content = "Saya pikir penjelasan Anda hanya membuat Kyllo semakin takut.",
  ui_story_5029_50290009_28_dialog_content = "Mungkin mengingatkan Kyllo saat dia dikirim terbang oleh seekor rusa...",
  ui_story_5029_50290009_29_dialog_content = "Lihat!!!",
  ui_story_5029_50290009_30_dialog_content = "Kyllo, jangan menyimpang terlalu jauh. Ini adalah investigasi!",
  ui_story_5029_50290009_31_option_content = "Kabinet kecil",
  ui_story_5029_50290009_32_dialog_content = "Laird berkata dia menyimpan kotak perak di lemari kecil ini.",
  ui_story_5029_50290009_33_dialog_content = "Tapi sekarang semuanya kosong...",
  ui_story_5029_50290009_34_dialog_content = "Aneh. Kabinet ini tidak terkunci.",
  ui_story_5029_50290009_35_dialog_content = "Laird mungkin merasa itu berlebihan karena pintunya terkunci.",
  ui_story_5029_50290009_36_dialog_content = "Tetapi kotak perak itu sendiri memiliki kunci.",
  ui_story_5029_50290009_37_dialog_content = "Oh, mungkin ada sesuatu yang lebih berharga di dalamnya!",
  ui_story_5029_50290009_38_dialog_content = "Itu sebenarnya masuk akal.",
  ui_story_5029_50290009_39_dialog_content = "Panggil aku Ekstrozoologis dan Detektif Hebat!",
  ui_story_5029_50290009_40_dialog_content = "Baiklah, Ahli Ekstrozoologi dan Detektif Hebat, mari kita lanjutkan penyelidikannya.",
  ui_story_5029_50290009_41_option_content = "Jangan berpikir kita melewatkan apa pun.",
  ui_story_5029_50290009_42_dialog_content = "Sekarang kita harus bagaimana?",
  ui_story_5029_50290009_43_dialog_content = "Periksa kamar sebelah?",
  ui_story_5029_50290009_44_dialog_content = "Jadi kemana selanjutnya...?",
  ui_story_5029_50290009_45_option_content = "Lobi",
  ui_story_5029_50290009_46_dialog_content = "Lobi terhubung ke semua kamar lainnya. Kita harus memeriksanya secara menyeluruh.",
  ui_story_5029_50290009_47_dialog_content = "Itu akal sehat.",
  ui_story_5029_50290009_48_dialog_content = "Pertanyaannya adalah...",
  ui_story_5029_50290009_49_dialog_content = "Di mana kita harus mulai?",
  ui_story_5029_50290009_50_option_content = "Pot bunga",
  ui_story_5029_50290009_51_dialog_content = "Mungkinkah ada beberapa alat di dalam pot?",
  ui_story_5029_50290009_52_dialog_content = "Tunggu!",
  ui_story_5029_50290009_53_dialog_content = "K-Kenapa kamu tiba-tiba berteriak seperti itu?",
  ui_story_5029_50290009_54_dialog_content = "Saya pikir saya membaca tentang bunga ini di catatan tuanku... Ini beracun!",
  ui_story_5029_50290009_55_dialog_content = "Benar! Terima kasih untuk itu... Untung aku tidak menyentuhnya.",
  ui_story_5029_50290009_56_dialog_content = "Hm? Kyllo, berhenti mencium bunga!",
  ui_story_5029_50290009_57_dialog_content = "Kyllo, kembali ke sini. Kita perlu terus menyelidiki.",
  ui_story_5029_50290009_58_option_content = "Sofa",
  ui_story_5029_50290009_59_dialog_content = "Apa yang Anda temukan?",
  ui_story_5029_50290009_60_dialog_content = "Jika ini adalah cerita lain, kita mungkin akan menemukan rahasia tersembunyi di bawah sofa.",
  ui_story_5029_50290009_61_dialog_content = "Tapi lihatlah! Kyllo bahkan tidak bisa memasukkan kepalanya ke sana. Tidak mungkin kotak perak itu ada di bawah sana.",
  ui_story_5029_50290009_62_dialog_content = "Mungkin bukan kotak perak... tapi mungkin sesuatu yang lain.",
  ui_story_5029_50290009_63_dialog_content = "Misalnya...",
  ui_story_5029_50290009_64_dialog_content = "Apa... Kau benar-benar mengeluarkan sesuatu dari bawah sofa?",
  ui_story_5029_50290009_65_dialog_content = "Tapi aku tidak tahu apa ini!",
  ui_story_5029_50290009_66_dialog_content = "Mungkin sepotong sesuatu.",
  ui_story_5029_50290009_67_dialog_content = "Astaga! Ini harus menjadi petunjuk kunci!",
  ui_story_5029_50290009_68_dialog_content = "Laird mengatakan seorang pelayan datang untuk membersihkan sekitar tengah hari.",
  ui_story_5029_50290009_69_dialog_content = "Jadi dia melewatkan satu tempat.",
  ui_story_5029_50290009_70_dialog_content = "Tidak! Naluri saya sebagai Ekstrozoologis dan Detektif Hebat memberi tahu saya bahwa ada lebih dari itu!",
  ui_story_5029_50290009_71_dialog_content = "Aku harus bertanya pada Zane tentang pelayan ini nanti!",
  ui_story_5029_50290009_72_dialog_content = "Baik. Mari kita lanjutkan pencarian.",
  ui_story_5029_50290009_73_option_content = "Dekorasi",
  ui_story_5029_50290009_74_dialog_content = "Hai! Ayo periksa, PlayerName! Binatang yang menakjubkan!",
  ui_story_5029_50290009_75_dialog_content = "Uhm... Anda belum pernah melihat keong sebelumnya?",
  ui_story_5029_50290009_76_dialog_content = "Hei, saya seorang ahli ekstrozoologi. Aku sudah melihat semuanya!",
  ui_story_5029_50290009_77_dialog_content = "T-Tapi aku belum pernah melihat keong warna ini...",
  ui_story_5029_50290009_78_dialog_content = "Saya mendengar bahwa jika Anda membisikkan keinginan Anda ke keong, itu akan menjadi kenyataan.",
  ui_story_5029_50290009_79_dialog_content = "Hai! Itu dongeng anak-anak, bukan?",
  ui_story_5029_50290009_80_dialog_content = "Aku bukan anak kecil lagi. Tidak mungkin aku membelinya!",
  ui_story_5029_50290009_81_dialog_content = "Keong, oh, keong... Biarkan aku menemukan barang laird yang hilang.",
  ui_story_5029_50290009_82_dialog_content = "Anda membuat keinginan sendiri? Baik. Lalu aku akan...",
  ui_story_5029_50290009_83_dialog_content = "Keong, oh, keong, jadikan Fia yang menemukan barang laird yang hilang!",
  ui_story_5029_50290009_84_dialog_content = "A-Ahem! Mari kita lanjutkan pencarian.",
  ui_story_5029_50290009_85_option_content = "Jangan berpikir kita melewatkan apa pun.",
  ui_story_5029_50290009_86_dialog_content = "Sekarang kita harus bagaimana?",
  ui_story_5029_50290009_87_dialog_content = "Periksa kamar sebelah?",
  ui_story_5029_50290009_88_dialog_content = "Jadi kemana selanjutnya...?",
  ui_story_5029_50290009_89_option_content = "Kafe",
  ui_story_5029_50290009_90_dialog_content = "Kafe? Silakan lewat sini.",
  ui_story_5029_50290009_91_dialog_content = "Terkadang sang sarang tidak ingin diganggu, maka dibangunlah sebuah kafe di dalam rumah.",
  ui_story_5029_50290009_92_dialog_content = "Dia bahkan terkadang menyeduh kopi untuk tamunya secara pribadi.",
  ui_story_5029_50290009_93_dialog_content = "Hei, aku mencium sesuatu yang enak dan lezat!",
  ui_story_5029_50290009_94_dialog_content = "Lihat!",
  ui_story_5029_50290009_95_dialog_content = "Dimana lagi?",
  ui_story_5029_50290009_96_option_content = "Ruang utilitas",
  ui_story_5029_50290009_97_dialog_content = "Ada...",
  ui_story_5029_50290009_98_dialog_content = "Kue madu!?",
  ui_story_5029_50290009_99_dialog_content = "Saya tidak berpikir saya akan mencicipi makanan khas Northland di sini.",
  ui_story_5029_50290009_100_dialog_content = "Saya tidak pernah memilikinya di Umbraton.",
  ui_story_5029_50290009_101_dialog_content = "Apakah itu baik?",
  ui_story_5029_50290009_102_dialog_content = "Dia. Tapi lebih baik kita tidak menyentuh apa pun di sini.",
  ui_story_5029_50290009_103_dialog_content = "Hmm! Aku tahu itu!",
  ui_story_5029_50290009_104_dialog_content = "Saya mendengar ada banyak makanan enak di sini di Harbour City.",
  ui_story_5029_50290009_105_dialog_content = "Segera setelah aku menemukan kotaknya dan mendapatkan hadiahnya... Aku akan mendapatkan semuanya!",
  ui_story_5029_50290009_106_dialog_content = "Lihat!",
  ui_story_5029_50290009_107_dialog_content = "A-Ahem! Mari kita lanjutkan pencarian.",
  ui_story_5029_50290009_108_option_content = "Lantai",
  ui_story_5029_50290009_109_dialog_content = "Kyllo, kenapa kamu bersembunyi di belakangku dan gemetaran seperti itu?",
  ui_story_5029_50290009_110_dialog_content = "Apakah ada sesuatu di sana?",
  ui_story_5029_50290009_111_dialog_content = "Ahhh! Nama pemain! Ada pisau berdarah!",
  ui_story_5029_50290009_112_dialog_content = "Apakah ini secara resmi kasus pembunuhan sekarang?",
  ui_story_5029_50290009_113_dialog_content = "Um…",
  ui_story_5029_50290009_114_dialog_content = "Ahem... Aku akan memeriksanya.",
  ui_story_5029_50290009_115_dialog_content = "Hahaha! Tidak apa. Ini selai stroberi.",
  ui_story_5029_50290009_116_dialog_content = "Aku tidak takut sama sekali.",
  ui_story_5029_50290009_117_dialog_content = "Aduh!",
  ui_story_5029_50290009_118_dialog_content = "Anda memiliki banyak kemacetan di jari Anda, PlayerName.",
  ui_story_5029_50290009_119_dialog_content = "Oh, itu bukan selai. Aku hanya tidak sengaja memotong diriku sendiri. Ini benar-benar darah kali ini.",
  ui_story_5029_50290009_120_dialog_content = "AHHHH! APA YANG HARUS DILAKUKAN!?",
  ui_story_5029_50290009_121_dialog_content = "Air liur Kyllo membunuh kuman! Kyllo, jilat jari PlayerName!",
  ui_story_5029_50290009_122_dialog_content = "Lihat!",
  ui_story_5029_50290009_123_dialog_content = "Aku baik-baik saja! Jangan khawatir... Mari kita terus mencari.",
  ui_story_5029_50290009_124_option_content = "Penghitung bar",
  ui_story_5029_50290009_125_dialog_content = "Apakah Anda memeriksa buku itu di konter bar?",
  ui_story_5029_50290009_126_dialog_content = "Mari kita lihat... Shinnosuke Sinsa Jilid 1?",
  ui_story_5029_50290009_127_dialog_content = "Hmph... Hanya cerita yang dibuat-buat.",
  ui_story_5029_50290009_128_dialog_content = "Saya masih lebih suka 1.001 Makhluk Fantastis Guru saya!",
  ui_story_5029_50290009_129_dialog_content = "Sungguh?",
  ui_story_5029_50290009_130_dialog_content = "A-Bagaimana dengan itu?",
  ui_story_5029_50290009_131_dialog_content = "Maksudku, kamu benar-benar mengagumi tuanmu, meskipun selalu mengeluh tentang dia, bukan?",
  ui_story_5029_50290009_132_dialog_content = "Kalau tidak, Anda tidak akan selalu mengatakan tuanmu ini, tuanmu itu.",
  ui_story_5029_50290009_133_dialog_content = "I-Ini hanya kebetulan!",
  ui_story_5029_50290009_134_dialog_content = "Baik. Mari kita lanjutkan pencarian.",
  ui_story_5029_50290009_135_option_content = "Jangan berpikir kita melewatkan apa pun.",
  ui_story_5029_50290009_136_dialog_content = "Sekarang kita harus bagaimana?",
  ui_story_5029_50290009_137_dialog_content = "Periksa kamar sebelah?",
  ui_story_5029_50290009_138_dialog_content = "Jadi kemana selanjutnya...?",
  ui_story_5029_50290009_139_option_content = "Tidak ada lagi yang bisa dilihat",
  ui_story_5029_50290009_140_dialog_content = "Saya pikir kami telah melalui semuanya.",
  ui_story_5029_50290009_141_dialog_content = "Ah... Akhirnya, istirahat!",
  ui_story_5029_50290009_142_dialog_content = "Hah? Tunggu, dimana Kyllo lagi?",
  ui_story_5029_50290009_143_dialog_content = "PlayerName, aku harus menemukan Kyllo!",
  ui_story_5029_50290009_144_dialog_content = "Baik. Hati-hati.",
  ui_story_5029_50290010_1_dialog_content = "(Ini benar-benar rumah yang besar...)",
  ui_story_5029_50290010_2_dialog_content = "(Di mana saya harus memeriksa selanjutnya?)",
  ui_story_5029_50290010_3_option_content = "Ruang belajar",
  ui_story_5029_50290010_4_dialog_content = "Aku hanya akan melihat-lihat...",
  ui_story_5029_50290010_5_option_content = "Rak buku pertama",
  ui_story_5029_50290010_6_dialog_content = "Buku itu sepertinya familiar.",
  ui_story_5029_50290010_7_dialog_content = "Shinnosuke Sinsa Jilid 1?",
  ui_story_5029_50290010_8_dialog_content = "Hanya Volume 1? Mengapa?",
  ui_story_5029_50290010_9_option_content = "Desk",
  ui_story_5029_50290010_10_dialog_content = "Juga, sebuah buku di atas meja... Ini compang-camping.",
  ui_story_5029_50290010_11_dialog_content = "<color=#828282>Membanting!</color>",
  ui_story_5029_50290010_12_dialog_content = "Ah, itu robek! Salahku...",
  ui_story_5029_50290010_13_dialog_content = "Ini buruk... Aku harus minta maaf pada laird tentang ini.",
  ui_story_5029_50290010_14_dialog_content = "Ini benar-benar bukan hariku.",
  ui_story_5029_50290010_15_option_content = "Kabinet kecil",
  ui_story_5029_50290010_16_dialog_content = "Laird berkata dia menyimpan kotak perak di lemari kecil ini.",
  ui_story_5029_50290010_17_dialog_content = "Ini adalah kabinet yang terlihat bagus. Sayang sekali sekarang kosong.",
  ui_story_5029_50290010_18_option_content = "Kira hanya itu yang bisa dilihat di sini.",
  ui_story_5029_50290010_19_dialog_content = "Kamar sebelah, kalau begitu.",
  ui_story_5029_50290010_20_option_content = "Lobi",
  ui_story_5029_50290010_21_dialog_content = "Lobi kosong...",
  ui_story_5029_50290010_22_dialog_content = "Aku hanya akan melihat-lihat...",
  ui_story_5029_50290010_23_option_content = "Pot bunga",
  ui_story_5029_50290010_24_dialog_content = "Mungkinkah ada beberapa alat di dalam pot?",
  ui_story_5029_50290010_25_dialog_content = "*Endus*",
  ui_story_5029_50290010_26_dialog_content = "Hai! Hati-hati! Bunga itu beracun. Jangan sampai terkena kulitmu!",
  ui_story_5029_50290010_27_dialog_content = "Apa yang bisa kulakukan... Aku merasa sedikit pusing sekarang.",
  ui_story_5029_50290010_28_dialog_content = "Anda tampaknya tidak diracuni. Istirahat saja, dan Anda akan baik-baik saja dalam waktu singkat.",
  ui_story_5029_50290010_29_dialog_content = "Terima kasih, saya bisa melanjutkannya sekarang ...",
  ui_story_5029_50290010_30_option_content = "Sofa",
  ui_story_5029_50290010_31_dialog_content = "Rasanya tidak benar hanya duduk di sini dan melihat mereka sibuk...",
  ui_story_5029_50290010_32_dialog_content = "Hmm? Apakah saya menginjak sesuatu?",
  ui_story_5029_50290010_33_dialog_content = "Bagian yang rusak dari sesuatu...?",
  ui_story_5029_50290010_34_dialog_content = "Saya pikir pelayan akan menjaga kamar ini tetap rapi dan bersih.",
  ui_story_5029_50290010_35_option_content = "Dekorasi",
  ui_story_5029_50290010_36_dialog_content = "Keong yang indah.",
  ui_story_5029_50290010_37_dialog_content = "Tapi tidak ada hubungannya dengan kasus ini.",
  ui_story_5029_50290010_38_option_content = "Kira hanya itu yang bisa dilihat di sini.",
  ui_story_5029_50290010_39_dialog_content = "Kamar sebelah, kalau begitu.",
  ui_story_5029_50290010_40_option_content = "Kafe",
  ui_story_5029_50290010_41_dialog_content = "Anda menuju ke kafe? Silahkan lewat sini.",
  ui_story_5029_50290010_42_dialog_content = "Terkadang sang sarang tidak ingin diganggu, maka dibangunlah sebuah kafe di dalam rumah.",
  ui_story_5029_50290010_43_dialog_content = "Dia bahkan terkadang menyeduh kopi untuk tamunya secara pribadi.",
  ui_story_5029_50290010_44_dialog_content = "Aku hanya akan melihat-lihat...",
  ui_story_5029_50290010_45_option_content = "cangkir kopi",
  ui_story_5029_50290010_46_dialog_content = "Laird pasti memiliki rasa yang enak. Bahkan cangkirnya terlihat sangat bagus.",
  ui_story_5029_50290010_47_dialog_content = "Masih kopi di cangkir?",
  ui_story_5029_50290010_48_dialog_content = "<color=#828282>Ding!</color>",
  ui_story_5029_50290010_49_dialog_content = "Hmm? Ada sesuatu di kopi?",
  ui_story_5029_50290010_50_dialog_content = "Sebuah lencana...?",
  ui_story_5029_50290010_51_dialog_content = "Untung aku tidak meminumnya, atau aku akan tersedak sekarang...",
  ui_story_5029_50290010_52_option_content = "Lantai",
  ui_story_5029_50290010_53_dialog_content = "Apakah ada sesuatu di sana? aku tidak bisa melihat dengan benar...",
  ui_story_5029_50290010_54_dialog_content = "Pisau berdarah?!",
  ui_story_5029_50290010_55_dialog_content = "Tolong!",
  ui_story_5029_50290010_56_dialog_content = "Saya minta maaf. Aku lupa memberitahumu...",
  ui_story_5029_50290010_57_dialog_content = "Itu pisau dengan selai di atasnya.",
  ui_story_5029_50290010_58_dialog_content = "Apakah kamu baik-baik saja? Apakah Anda perlu istirahat?",
  ui_story_5029_50290010_59_dialog_content = "Jangan khawatir tentang itu... Aku hanya perlu tenang.",
  ui_story_5029_50290010_60_option_content = "Wall",
  ui_story_5029_50290010_61_dialog_content = "Ada begitu banyak lukisan minyak yang indah di dinding!",
  ui_story_5029_50290010_62_dialog_content = "Aku sedang tidak mood untuk menikmatinya.",
  ui_story_5029_50290010_63_option_content = "Kira hanya itu yang bisa dilihat di sini.",
  ui_story_5029_50290010_64_dialog_content = "Kamar sebelah, kalau begitu.",
  ui_story_5029_50290010_65_option_content = "Aku sudah selesai di sini.",
  ui_story_5029_50290010_66_dialog_content = "Tidak menemukan apa-apa setelah sekian lama...",
  ui_story_5029_50290010_67_dialog_content = "Hmm... Mereka masih sibuk melihat-lihat.",
  ui_story_5029_50290010_68_dialog_content = "Aku akan istirahat.",
  ui_story_5029_50290011_1_dialog_content = "Sofa ini terasa sangat enak.",
  ui_story_5029_50290011_2_dialog_content = "Aku mengangguk... Aku tidak tidur terlalu lama, kan?",
  ui_story_5029_50290011_3_dialog_content = "Apa yang harus saya lakukan sekarang...?",
  ui_story_5029_50290011_4_dialog_content = "Detektif lainnya siap untuk pergi mencari tersangka. Apakah Anda pergi dengan mereka?",
  ui_story_5029_50290011_5_dialog_content = "Hm... Itu saja?",
  ui_story_5029_50290011_6_dialog_content = "Ah! Tunggu aku!",
  ui_story_5029_50290011_7_option_content = "Bertanya Carleen",
  ui_story_5029_50290011_8_dialog_content = "Carleen, kemana kamu pergi?",
  ui_story_5029_50290011_9_dialog_content = "Apakah Anda melihat buku aneh di rumah ini?",
  ui_story_5029_50290011_10_dialog_content = "Buku yang aneh? Sebagian besar buku di sini baru bagi saya...",
  ui_story_5029_50290011_11_dialog_content = "Saya hanya membaca sedikit <color=#793f76>Shinnosuke Sinsa</color> sebelum.",
  ui_story_5029_50290011_12_dialog_content = "Itulah yang saya bicarakan.",
  ui_story_5029_50290011_13_dialog_content = "Pada awalnya, saya hanya berpikir aneh bahwa Elvis akan membaca fiksi pop seperti itu.",
  ui_story_5029_50290011_14_dialog_content = "Kemudian saya menemukan bahwa buku-buku yang sama ada di seluruh rumah.",
  ui_story_5029_50290011_15_dialog_content = "Jadi laird mencintai Shinnosuke Sinsa sebanyak yang saya lakukan?!",
  ui_story_5029_50290011_16_dialog_content = "Tunggu... Jika dia benar-benar menyukainya, dia akan memiliki seluruh koleksinya.",
  ui_story_5029_50290011_17_dialog_content = "Tapi yang bisa saya temukan hanyalah Volume 1.",
  ui_story_5029_50290011_18_dialog_content = "Saya bertanya kepada Zane tentang hal itu, dan dia mengatakan bahwa laird tidak pernah membaca hal-hal seperti itu.",
  ui_story_5029_50290011_19_dialog_content = "Namun, pedagang dari kemarin hanya di sini untuk meluncurkan bisnis penerbitan fiksi pop ke laird.",
  ui_story_5029_50290011_20_dialog_content = "Tapi apa hubungannya dengan pencurian?",
  ui_story_5029_50290011_21_dialog_content = "Mungkin Anda akan mendapatkannya setelah Anda tahu siapa pedagang ini.",
  ui_story_5029_50290011_22_dialog_content = "A-Apakah dia seseorang yang kukenal?",
  ui_story_5029_50290011_23_dialog_content = "Zane mengatakan namanya adalah <color=#793f76>Jomu Ichigo</color>.",
  ui_story_5029_50290011_24_dialog_content = "Tidak pernah mendengar hal tersebut. Kedengarannya seperti nama seseorang dari Pulau Awan...",
  ui_story_5029_50290011_25_dialog_content = "Tunggu. Jomu Ichigo... JOMU?!",
  ui_story_5029_50290011_26_dialog_content = "Dia sembrono... Apakah dia benar-benar berpikir dia bisa membodohi siapa pun dengan nama palsu yang bodoh?",
  ui_story_5029_50290011_27_dialog_content = "Bahkan jika itu benar-benar Jomu, bukan berarti dia pencurinya.",
  ui_story_5029_50290011_28_dialog_content = "Jangan lupa, Rediesel Wrench hanyalah sekelompok bandit pelanggar hukum.",
  ui_story_5029_50290011_28X1_dialog_content = "Mencuri adalah apa yang mereka lakukan.",
  ui_story_5029_50290011_29_dialog_content = "Beraninya mereka melakukan operasi mereka di Lumopolis!",
  ui_story_5029_50290011_30_dialog_content = "Aku pasti akan mengasingkannya dengan tombakku!",
  ui_story_5029_50290011_31_dialog_content = "Bagaimana kalau... kita tanya saja langsung padanya?",
  ui_story_5029_50290011_32_dialog_content = "Anda membaca pikiran saya.",
  ui_story_5029_50290011_33_dialog_content = "Aku akan menemukannya di tempatnya.",
  ui_story_5029_50290011_34_option_content = "Aku ikut denganmu.",
  ui_story_5029_50290011_35_dialog_content = "Baiklah, ayo pergi.",
  ui_story_5029_50290011_36_option_content = "Semoga berhasil, ya.",
  ui_story_5029_50290011_37_dialog_content = "Terima kasih.",
  ui_story_5029_50290011_38_option_content = "Tanyai Vice",
  ui_story_5029_50290011_39_dialog_content = "Vice, kemana kamu pergi?",
  ui_story_5029_50290011_40_dialog_content = "Pernahkah Anda memperhatikan sesuatu di kafe yang tidak seharusnya ada di sana?",
  ui_story_5029_50290011_41_dialog_content = "Bukan milik di sana?",
  ui_story_5029_50290011_42_dialog_content = "maksudmu adalah <color=#793f76>Lencana Ksatria Lumo</color> di cangkir kopi?",
  ui_story_5029_50290011_43_dialog_content = "Benar.",
  ui_story_5029_50290011_44_dialog_content = "Pada awalnya, saya pikir itu adalah salah satu koleksi laird.",
  ui_story_5029_50290011_45_dialog_content = "Itu masuk akal. Wajar jika laird memiliki lencana Ksatria karena kota ini adalah bagian dari yurisdiksi Lumopolis.",
  ui_story_5029_50290011_46_dialog_content = "Tapi itu akan tetap aman jika itu masalahnya.",
  ui_story_5029_50290011_47_dialog_content = "Maksudku, tempat terakhir yang bisa muncul adalah di kopi untuk tamu...",
  ui_story_5029_50290011_48_dialog_content = "Tepat. Jadi hanya ada satu kemungkinan yang tersisa.",
  ui_story_5029_50290011_49_dialog_content = "Lencana itu milik salah satu tamu.",
  ui_story_5029_50290011_50_dialog_content = "Dan salah satu tamu seperti itu ada di sini kemarin, dari Lumopolis.",
  ui_story_5029_50290011_51_dialog_content = "Maksudmu bangsawan dari Lumopolis?",
  ui_story_5029_50290011_52_dialog_content = "Sepertinya aku mendengar laird memanggilnya... Duchess Iskar atau semacamnya.",
  ui_story_5029_50290011_53_dialog_content = "Tahukah Anda nama lengkap Duchess Iskar?",
  ui_story_5029_50290011_54_dialog_content = "<color=#793f76>Beverly Iskar</color>!",
  ui_story_5029_50290011_55_dialog_content = "Maksudmu... ITU Beverly?",
  ui_story_5029_50290011_56_dialog_content = "Bahkan jika itu adalah lencananya, itu tidak berarti dia terhubung dengan pencurian itu.",
  ui_story_5029_50290011_57_dialog_content = "Saya bertanya kepada Zane tentang hal itu, dan dia berkata Beverly dan laird bertengkar kemarin.",
  ui_story_5029_50290011_58_dialog_content = "Apakah kamu mengatakan Beverly mencuri kotak laird karena kebencian?",
  ui_story_5029_50290011_59_dialog_content = "Itu tidak benar-benar terdengar seperti sesuatu yang akan dia lakukan ...",
  ui_story_5029_50290011_60_dialog_content = "Saya telah belajar ini dari pengalaman ketika saya masih mahasiswa di Lumopolis.",
  ui_story_5029_50290011_61_dialog_content = "Para bangsawan yang paling arogan melakukan hal-hal konyol di belakang layar.",
  ui_story_5029_50290011_62_dialog_content = "Dan Beverly kebetulan seseorang yang tidak bisa berhenti mengingatkan orang tentang dia menjadi seorang bangsawan ...",
  ui_story_5029_50290011_63_dialog_content = "Saya tidak suka mencurigainya sedikit pun... Itu sebabnya saya akan mengkonfrontasinya tentang hal ini.",
  ui_story_5029_50290011_64_option_content = "Aku ikut denganmu.",
  ui_story_5029_50290011_65_dialog_content = "Aku tahu kau akan mengatakan itu. Ayo pergi!",
  ui_story_5029_50290011_66_option_content = "Semoga berhasil, ya.",
  ui_story_5029_50290011_67_dialog_content = "Simpan untuk orang lain.",
  ui_story_5029_50290011_68_option_content = "Tanya Fia",
  ui_story_5029_50290011_69_dialog_content = "Fi, mau kemana?",
  ui_story_5029_50290011_70_dialog_content = "Sst... Tenang, Nama Pemain.",
  ui_story_5029_50290011_71_dialog_content = "Saya menemukan sesuatu yang penting! Jangan kau beri tahu siapa pun!",
  ui_story_5029_50290011_72_dialog_content = "Maksudmu itu <color=#793f76>pecahan</color> sesuatu dari bawah sofa?",
  ui_story_5029_50290011_73_dialog_content = "Jangan meremehkan mereka! Aku sudah bertanya pada Zane.",
  ui_story_5029_50290011_74_dialog_content = "Pelayan seharusnya membersihkannya. Itu bagian dari pekerjaannya.",
  ui_story_5029_50290011_75_dialog_content = "Jadi... dia tidak melakukan pekerjaan yang cukup baik?",
  ui_story_5029_50290011_76_dialog_content = "Hanya jika itu masalahnya!",
  ui_story_5029_50290011_77_dialog_content = "Intinya adalah... ada sesuatu yang mencurigakan tentang latar belakangnya.",
  ui_story_5029_50290011_78_dialog_content = "Latar belakangnya? Saya ingat laird mengatakan bahwa pelayan itu direkomendasikan oleh Persekutuan Umbraton.",
  ui_story_5029_50290011_79_dialog_content = "Itu guild yang bisa diandalkan bagiku.",
  ui_story_5029_50290011_80_dialog_content = "Mendesah, PlayerName, kamu bukan lagi anak-anak! Kenapa kau masih begitu naif?",
  ui_story_5029_50290011_81_dialog_content = "Izinkan saya, Ahli Ekstrozoologi Hebat, Penduduk Umbraton, Penguasa Caelestit, dan Detektif yang Meningkat, memberi tahu Anda.",
  ui_story_5029_50290011_82_dialog_content = "Baik Harbour City dan Umbraton dimulai sebagai pusat perdagangan.",
  ui_story_5029_50290011_83_dialog_content = "Dan Umbraton dikatakan sebagai pusat perdagangan bebas terbesar dan tersibuk.",
  ui_story_5029_50290011_84_dialog_content = "Namun dalam praktiknya, saya mengamati, Harbour City akan segera melampaui Umbraton.",
  ui_story_5029_50290011_85_dialog_content = "Menurutmu mengapa Persekutuan Umbraton mengirim pelayan di saat seperti ini?",
  ui_story_5029_50290011_86_dialog_content = "Kenapa?",
  ui_story_5029_50290011_87_dialog_content = "Hanya ada satu alasan: Untuk mencuri rahasia dagang!",
  ui_story_5029_50290011_88_dialog_content = "Itu pasti yang ada di dalam kotak perak itu!",
  ui_story_5029_50290011_89_dialog_content = "Kedengarannya tidak mungkin, tapi saya tidak bisa menyangkalnya...",
  ui_story_5029_50290011_90_dialog_content = "Manae, sang maid, sedang bekerja di tempat lain sekarang. Aku akan menangkapnya!",
  ui_story_5029_50290011_91_dialog_content = "Tunggu sebentar... Tadi kau bilang siapa namanya?",
  ui_story_5029_50290011_92_dialog_content = "<color=#793f76>Manae?</color>. Mengapa?",
  ui_story_5029_50290011_93_dialog_content = "Hm... Kedengarannya agak familiar.",
  ui_story_5029_50290011_94_option_content = "Aku ikut denganmu.",
  ui_story_5029_50290011_95_dialog_content = "Sst, ayo pergi diam-diam dan jangan beri tahu mereka berdua!",
  ui_story_5029_50290011_96_option_content = "Bagaimanapun, semoga berhasil.",
  ui_story_5029_50290011_97_dialog_content = "Anda sebaiknya tidak memberi tahu orang lain apa yang saya temukan!",
  ui_story_5029_50290011_98_dialog_content = "Atau aku akan melepaskan Kyllo darimu!",
  ui_story_5029_50290011_99_dialog_content = "Lihat!",
  ui_story_5029_50290011_100_option_content = "Tetap sendiri",
  ui_story_5029_50290011_101_dialog_content = "Ada apa?",
  ui_story_5029_50290011_102_dialog_content = "Kenapa hanya aku yang tersisa...?",
  ui_story_5029_50290012_1_dialog_content = "Jomu... Apakah dia punya uang untuk menginap di hotel mewah seperti itu?",
  ui_story_5029_50290012_2_dialog_content = "Sekarang bahkan aku agak skeptis padanya... Aku harus memintanya untuk menjelaskan!",
  ui_story_5029_50290012_3_dialog_content = "Namun, ada masalah lain.",
  ui_story_5029_50290012_4_dialog_content = "Elvis meminta kami untuk menyelidiki secara diam-diam, jadi kami tidak bisa hanya pergi ke resepsionis dan menanyakan nomor kamar Jomu.",
  ui_story_5029_50290012_5_dialog_content = "Tapi kita bisa... berpura-pura menjadi tamu.",
  ui_story_5029_50290012_6_dialog_content = "Masuk saja seperti kita sedang memeriksa tempat itu.",
  ui_story_5029_50290012_7_dialog_content = "Kemudian kita bisa mencoba mencari Jomu.",
  ui_story_5029_50290012_8_dialog_content = "Ini strategi yang bagus... Tapi aku tidak suka berbohong pada orang baik.",
  ui_story_5029_50290012_9_dialog_content = "Kami di sana hanya untuk menyelidiki sebuah kasus. Kami tidak akan menyakiti siapa pun.",
  ui_story_5029_50290012_10_dialog_content = "Apakah itu semacam kebohongan putih dalam kasus itu?",
  ui_story_5029_50290012_11_dialog_content = "Bagaimana kalau membiarkan saya yang berbicara? Anda hanya bisa berdiri di sisi saya.",
  ui_story_5029_50290012_12_dialog_content = "Tidak. Saya tidak ingin menjadi pengendara bebas. Saya akan mencoba melakukan bagian saya.",
  ui_story_5029_50290012_13_dialog_content = "Selamat datang. Apakah Anda memiliki reservasi?",
  ui_story_5029_50290012_14_dialog_content = "A-Ahem... Tidak. T-Belum!",
  ui_story_5029_50290012_15_dialog_content = "(Carleen benar-benar buruk dalam hal ini ...)",
  ui_story_5029_50290012_16_dialog_content = "Betul sekali. Karena...",
  ui_story_5029_50290012_17_option_content = "Aku pilih-pilih tentang di mana aku tinggal di.",
  ui_story_5029_50290012_18_dialog_content = "Hah?",
  ui_story_5029_50290012_19_option_content = "Dia pilih-pilih tentang di mana dia tinggal.",
  ui_story_5029_50290012_20_dialog_content = "Hah?",
  ui_story_5029_50290012_21_dialog_content = "Jadi kami pikir kami lebih baik memeriksa tempat ini terlebih dahulu.",
  ui_story_5029_50290012_22_dialog_content = "Saya mengerti. aku harus memanggilmu apa?",
  ui_story_5029_50290012_23_dialog_content = "Saya Nama Pemain.",
  ui_story_5029_50290012_24_dialog_content = "Silakan lewat sini, Tuan dan Nyonya PlayerName.",
  ui_story_5029_50290012_25_dialog_content = "Saya akan menunjukkan Anda ke suite presiden kami. Ini pasti akan menjadikannya bulan madu impian bagi Anda.",
  ui_story_5029_50290012_26_dialog_content = "…?!",
  ui_story_5029_50290012_27_dialog_content = "Um... Tapi kami tidak...",
  ui_story_5029_50290012_28_dialog_content = "Anda bukan pengantin baru?",
  ui_story_5029_50290012_29_dialog_content = "Ya!",
  ui_story_5029_50290012_30_dialog_content = "Tidak!",
  ui_story_5029_50290012_31_dialog_content = "Hah? Apakah itu ya atau tidak...?",
  ui_story_5029_50290012_32_dialog_content = "(Sial... Dia mulai curiga Carleen dan saya! Apa yang harus saya lakukan?)",
  ui_story_5029_50290012_33_dialog_content = "(Tetapi Carleen hanya mengatakan ya tanpa ragu-ragu ...)",
  ui_story_5029_50290012_34_dialog_content = "(Ahhh! Ini bukan waktunya untuk itu! Apa yang harus aku lakukan sekarang?!)",
  ui_story_5029_50290012_35_dialog_content = "Apakah Anda benar-benar tamu?",
  ui_story_5029_50290012_36_dialog_content = "Tentu saja…",
  ui_story_5029_50290012_37_dialog_content = "Saya minta maaf. L-Biar saya jelaskan. Kami baru saja bertunangan.",
  ui_story_5029_50290012_38_dialog_content = "Bagiku... bertunangan berarti kami hampir seperti pengantin baru.",
  ui_story_5029_50290012_39_dialog_content = "Tapi baginya, dia membutuhkan pernikahan yang mewah dan semuanya... Sebuah upacara formal, kau tahu.",
  ui_story_5029_50290012_40_dialog_content = "Oh ya. Tentu! Saya sendiri ingin pernikahan yang unik! Siapa yang tidak mau?",
  ui_story_5029_50290012_41_dialog_content = "Apakah mataku menipuku?",
  ui_story_5029_50290012_42_dialog_content = "Jomu! Hahaha... A-Sungguh kebetulan!",
  ui_story_5029_50290012_43_dialog_content = "Apakah itu benar-benar Anda, bos? Kau dan dia... Whoo—Kenapa kau mencoba membungkamku?",
  ui_story_5029_50290012_44_dialog_content = "Uh, kami baru saja bertemu teman lama. Kami akan kembali sebentar lagi.",
  ui_story_5029_50290012_45_dialog_content = "Silakan luangkan waktu Anda.",
  ui_story_5029_50290012_46_dialog_content = "Anda menyamar untuk penyelidikan? Saya mengerti. Jadi itu sebabnya Anda mencoba untuk lulus sebagai pasangan.",
  ui_story_5029_50290012_47_dialog_content = "Haha... Jika Caelestite menikahi putri Lumopolis, aku bertanya-tanya apa Sinsa akan melakukan.",
  ui_story_5029_50290012_48_dialog_content = "Maksud saya, Sinsa telah sangat menantikan PlayerName bergabung dengan kami.",
  ui_story_5029_50290012_49_dialog_content = "Oh? Apa yang akan dia lakukan?",
  ui_story_5029_50290012_50_dialog_content = "Ahem... Jangan bahas ini. Jomu, kenapa kamu di Harbour City?",
  ui_story_5029_50290012_51_dialog_content = "Aku di sini untuk urusan bisnis, tentu saja.",
  ui_story_5029_50290012_52_dialog_content = "Jalankan scram Anda lagi, maksud Anda?",
  ui_story_5029_50290012_53_dialog_content = "Itu tidak benar! Ayo!",
  ui_story_5029_50290012_54_dialog_content = "Bahkan jika kamu adalah sang putri, kamu tidak bisa seenaknya menuduh orang seperti itu.",
  ui_story_5029_50290012_55_dialog_content = "Saya di sini untuk urusan yang sah. Aku bahkan mengadakan pertemuan resmi dengan laird Harbour City kemarin.",
  ui_story_5029_50290012_56_dialog_content = "Itu saja? Kenapa intel saya mengatakan bahwa pedagang yang ditemui laird kemarin berasal dari Pulau Cloud?",
  ui_story_5029_50290012_57_dialog_content = "Jomu Ichiro, pakar penerbitan dari Cloud Island. Mencari mitra bisnis di Astra.",
  ui_story_5029_50290012_58_dialog_content = "Terlibat dalam promosi novel biografi Timur Jauh...",
  ui_story_5029_50290012_59_dialog_content = "Kamu benar-benar itu Jomu Ichigo?",
  ui_story_5029_50290012_60_dialog_content = "Itu semacam personal branding, bos. Laird tidak akan ingin bertemu denganku jika aku hanya aku, kau tahu?",
  ui_story_5029_50290012_61_dialog_content = "Belum lagi dia telah berjanji untuk memberikan kemudahan lebih lanjut untuk pencetakan saya. Uang, rumah, tenaga...",
  ui_story_5029_50290012_62_dialog_content = "Dari apa yang saya dengar, laird mundur karena tuntutan Anda menggelikan.",
  ui_story_5029_50290012_63_dialog_content = "Itu adalah kemunduran sementara. Aku yakin dia akan datang...",
  ui_story_5029_50290012_64_dialog_content = "Tunggu, rasanya aneh... Kenapa kalian berdua menginterogasiku?",
  ui_story_5029_50290012_65_dialog_content = "Apakah Anda di sini untuk menyelidiki saya?",
  ui_story_5029_50290012_66_option_content = "Tidak.",
  ui_story_5029_50290012_67_dialog_content = "Hanya mengejar teman lama.",
  ui_story_5029_50290012_68_dialog_content = "Saya masih memegang tempat di hati Anda ... Saya sangat tersentuh, bos!",
  ui_story_5029_50290012_69_dialog_content = "Setelah saya menyegel kesepakatan, saya akan mentraktir kalian berdua makan besar!",
  ui_story_5029_50290012_70_dialog_content = "Terimakasih tapi...",
  ui_story_5029_50290012_71_option_content = "Benar.",
  ui_story_5029_50290012_72_dialog_content = "Sst... Ingat? Kita harus menjaga rahasia ini.",
  ui_story_5029_50290012_73_dialog_content = "Ehem... Benar.",
  ui_story_5029_50290012_74_dialog_content = "Kami di sini hanya untuk mencari tahu siapa sebenarnya saudagar ini bagi laird.",
  ui_story_5029_50290012_75_dialog_content = "Sekarang setelah saya mendengar apa yang Anda katakan, saya pikir saya punya ide.",
  ui_story_5029_50290012_76_dialog_content = "Laird seharusnya tidak menyetujui kesepakatan ini.",
  ui_story_5029_50290012_77_dialog_content = "Ya... aku memang memalsukan identitasku...",
  ui_story_5029_50290012_78_dialog_content = "Tapi saya tulus tentang segala sesuatu tentang kemitraan ini.",
  ui_story_5029_50290012_79_dialog_content = "Shinnosuke Sinsa layak mendapat audiens yang lebih luas.",
  ui_story_5029_50290012_80_dialog_content = "Keyakinan inilah yang memberi arti hidup saya!",
  ui_story_5029_50290012_81_dialog_content = "Saya melewati semua kesulitan ini untuk datang ke tempat budaya ini ...",
  ui_story_5029_50290012_81X1_dialog_content = "Hanya untuk menemukan penerbit besar untuk bermitra.",
  ui_story_5029_50290012_82_dialog_content = "Sudah lama saya tidak melakukan bisnis teduh itu. Aku sah sekarang.",
  ui_story_5029_50290012_83_dialog_content = "Anda sebaiknya melepas kacamata berwarna Anda, tolong?",
  ui_story_5029_50290012_84_dialog_content = "PlayerName, bagaimana menurutmu?",
  ui_story_5029_50290012_85_dialog_content = "Jomu tidak terdengar berbohong.",
  ui_story_5029_50290012_86_dialog_content = "Jika dia benar-benar di sini mencari mitra bisnis, dia tidak akan mencuri dari sarangnya.",
  ui_story_5029_50290012_87_dialog_content = "Apa Jomu berkata... membuatku malu.",
  ui_story_5029_50290012_88_dialog_content = "Aku seharusnya tidak mempertanyakan motifnya tanpa alasan, tapi...",
  ui_story_5029_50290012_89_dialog_content = "Tapi masih ada hal yang belum kami tanyakan padanya.",
  ui_story_5029_50290012_90_dialog_content = "Misalnya, mengapa ada begitu banyak salinan Shinnosuke Sinsa di dalam rumah?",
  ui_story_5029_50290012_91_dialog_content = "Jomu mungkin baru saja meninggalkan mereka di sana kemarin...?",
  ui_story_5029_50290012_92_dialog_content = "Apakah kalian berdua dengan laird? Salam pembuka.",
  ui_story_5029_50290012_93_dialog_content = "Dan kamu adalah...?",
  ui_story_5029_50290012_94_dialog_content = "Saya Shani, seorang tukang kebun. Saya bekerja di tempat yang saya butuhkan, seperti di sini. Saya juga memotong rumput untuk sarang kemarin.",
  ui_story_5029_50290012_95_dialog_content = "Kenapa kau bilang kita bersama laird?",
  ui_story_5029_50290012_96_dialog_content = "Oh, apakah saya salah? Saya minta maaf!",
  ui_story_5029_50290012_97_dialog_content = "Pria berambut hijau itu bekerja untuk laird, jadi kupikir kalian berdua...",
  ui_story_5029_50290012_98_dialog_content = "Apakah Anda melihatnya di tempat laird?",
  ui_story_5029_50290012_99_dialog_content = "Ya! Aku melihatnya tadi malam di sana. Aku yakin itu.",
  ui_story_5029_50290012_100_dialog_content = "Kemarin, setelah saya selesai dengan halaman, saya melihatnya berjalan keluar rumah dengan sarangnya.",
  ui_story_5029_50290012_101_dialog_content = "Tapi kemudian dia kembali, membuka kunci pintu, dan masuk seolah-olah dia telah melupakan sesuatu. Dia baru keluar beberapa saat kemudian.",
  ui_story_5029_50290012_102_dialog_content = "...",
  ui_story_5029_50290012_103_dialog_content = "PlayerName, apakah Anda masih percaya? Jomu sekarang?",
  ui_story_5029_50290012_104_dialog_content = "Itu benar-benar dia...?",
  ui_story_5029_50290012_105_dialog_content = "D-Apakah saya mengatakan sesuatu yang salah?",
  ui_story_5029_50290012_106_dialog_content = "Shani, kamu sangat membantu.",
  ui_story_5029_50290012_107_dialog_content = "Dan Anda adalah seorang tukang kebun yang hebat.",
  ui_story_5029_50290012_108_dialog_content = "Anda semua diperiksa, Pak. Saya mengharapkan kehormatan kunjungan Anda lagi!",
  ui_story_5029_50290012_109_dialog_content = "Jika Anda ingin saya berkunjung lagi... Mengapa tidak membeli beberapa salinan Shinnosuke Sinsa?",
  ui_story_5029_50290012_110_dialog_content = "Aku…",
  ui_story_5029_50290012_111_dialog_content = "Jomu.",
  ui_story_5029_50290012_112_dialog_content = "Hah...? Bos, saya sedang ada urusan. Apakah Anda sudah meninggalkan saya sendiri?",
  ui_story_5029_50290012_113_dialog_content = "Saya hanya punya beberapa pertanyaan lagi untuk Anda.",
  ui_story_5029_50290012_114_dialog_content = "Setelah kamu bertemu dengan laird, apakah kamu menyelinap kembali ke ruang kerja laird?",
  ui_story_5029_50290012_115_dialog_content = "Oh? Apakah laird memintamu untuk datang menjemputku secara rahasia?",
  ui_story_5029_50290012_116_dialog_content = "Jadi, sang laird jatuh cinta pada Shinnosuke Sinsa setelah membaca volume pertama, bukan?",
  ui_story_5029_50290012_117_dialog_content = "Anda di sini karena dia sangat menginginkan volume kedua?",
  ui_story_5029_50290012_118_dialog_content = "Saya tahu dia akan datang dan menerima kesepakatan itu!",
  ui_story_5029_50290012_119_dialog_content = "Jadi Anda mengakui bahwa Anda menyelinap ke ruang kerja laird?",
  ui_story_5029_50290012_120_dialog_content = "Sekarang laird tahu seberapa bagus Shinnosuke Sinsa koleksi adalah, saya tidak punya alasan untuk menyimpan sesuatu dari Anda.",
  ui_story_5029_50290012_121_dialog_content = "Laird tidak menyetujui kemitraan kemarin.",
  ui_story_5029_50290012_122_dialog_content = "Saya pikir itu pasti karena dia tidak tahu seberapa bagus buku-buku itu.",
  ui_story_5029_50290012_123_dialog_content = "Jika dia membaca volume pertama, dia akan tahu bahwa ini sepadan dengan investasinya!",
  ui_story_5029_50290012_124_dialog_content = "Jadi saya menyelinap kembali dan meletakkan Volume 1 di semua tempat yang bisa dilihat matanya.",
  ui_story_5029_50290012_125_dialog_content = "Ada lima dari mereka dari saku saya sendiri! Tetapi untuk memenangkan beberapa, Anda harus kehilangan beberapa.",
  ui_story_5029_50290012_126_dialog_content = "Dan lihat? Sekarang laird telah berubah pikiran! Ha ha ha!",
  ui_story_5029_50290012_127_dialog_content = "Sepertinya saya tidak cukup teliti untuk menemukan kelimanya.",
  ui_story_5029_50290012_128_dialog_content = "Apakah itu satu-satunya alasan mengapa Anda menyelinap ke ruang kerjanya?",
  ui_story_5029_50290012_129_dialog_content = "Kenapa lagi? Di mana laird sekarang? Aku akan mengirimkan volume kedua padanya.",
  ui_story_5029_50290012_130_dialog_content = "Dia sedang sibuk dengan pekerjaannya saat ini. Jika Anda tinggal beberapa hari, saya akan mengatur pertemuan untuk Anda.",
  ui_story_5029_50290012_131_dialog_content = "Eh... Saya agak menggunakan semua uang di sini. Saya kira saya harus mencari tempat yang lebih murah untuk tinggal hari ini.",
  ui_story_5029_50290012_132_dialog_content = "Menjadi legit itu menyakitkan...",
  ui_story_5029_50290013_1_dialog_content = "Kita terlambat... Permainan telah dimulai.",
  ui_story_5029_50290013_2_dialog_content = "Kamu yakin Beverly ada di teater ini?",
  ui_story_5029_50290013_3_dialog_content = "Tentu saja.",
  ui_story_5029_50290013_4_dialog_content = "Melihat permainan ini adalah alasannya Beverly datang ke Kota Pelabuhan.",
  ui_story_5029_50290013_5_dialog_content = "Ada begitu banyak drama, jadi bagaimana Anda bisa yakin ini adalah salah satunya?",
  ui_story_5029_50290013_6_dialog_content = "Bahkan Zane tidak tahu permainan yang mana Beverly ingin melihat.",
  ui_story_5029_50290013_7_dialog_content = "Tapi dia bilang Beverly di sini untuk melihat pertunjukan pertama dari sebuah drama!",
  ui_story_5029_50290013_8_dialog_content = "Saya memeriksa jadwal pertunjukan hari ini.",
  ui_story_5029_50290013_9_dialog_content = "Hanya tiga yang pertama kali ditampilkan hari ini.",
  ui_story_5029_50290013_10_dialog_content = "Salah satunya adalah drama modern yang bukan jenisnya Beverly menikmati.",
  ui_story_5029_50290013_11_dialog_content = "Yang lain sering ditampilkan di Lumopolis, jadi tidak ada alasan untuk Beverly untuk datang jauh-jauh ke sini.",
  ui_story_5029_50290013_12_dialog_content = "Dan yang terakhir adalah Romi dan Julie ini.",
  ui_story_5029_50290013_13_dialog_content = "Vice…",
  ui_story_5029_50290013_14_option_content = "Anda benar-benar seorang detektif.",
  ui_story_5029_50290013_15_dialog_content = "Anda harus membuka agen detektif!",
  ui_story_5029_50290013_16_dialog_content = "Heheh...",
  ui_story_5029_50290013_17_option_content = "Sekarang aku agak takut.",
  ui_story_5029_50290013_18_dialog_content = "Terasa seperti tidak ada yang bisa melarikan diri dari Anda ...",
  ui_story_5029_50290013_19_dialog_content = "Ehem...",
  ui_story_5029_50290013_20_dialog_content = "Itu terlalu jauh, bukan?",
  ui_story_5029_50290013_21_dialog_content = "Kami sudah saling kenal begitu lama. Anda kenal saya.",
  ui_story_5029_50290013_22_dialog_content = "Lagipula aku lebih baik dalam eksekusi.",
  ui_story_5029_50290013_23_dialog_content = "Tapi kita tidak bisa begitu saja masuk ke teater sekarang. Kita harus menunggu sampai drama berakhir.",
  ui_story_5029_50290013_24_dialog_content = "Pertunjukan akan segera dimulai. Apakah kalian berdua tidak masuk?",
  ui_story_5029_50290013_25_dialog_content = "Terima kasih telah mengingatkan kami, tetapi kami sebenarnya tidak memiliki tiket...",
  ui_story_5029_50290013_26_dialog_content = "Hah? Anda tidak tahu tentang penawaran khusus kami hari ini?",
  ui_story_5029_50290013_27_dialog_content = "Dua untuk satu untuk pertunjukan pertama Romi dan Julie!",
  ui_story_5029_50290013_28_dialog_content = "Ini kesempatan langka.",
  ui_story_5029_50290013_29_dialog_content = "Dua untuk satu... Benarkah?",
  ui_story_5029_50290013_30_dialog_content = "Tapi saya pikir tidak ada tiket yang tersisa.",
  ui_story_5029_50290013_31_dialog_content = "Itu benar, tetapi pasangan baru saja mengajukan pengembalian dana karena putus baru-baru ini, jadi dua tiket terakhir tersedia sekarang.",
  ui_story_5029_50290013_32_dialog_content = "Putus?",
  ui_story_5029_50290013_33_dialog_content = "Mengambil tiket mereka mungkin bukan keberuntungan...",
  ui_story_5029_50290013_34_dialog_content = "Tapi saya dapat memberitahu Anda adalah pasangan yang manis. Tidak perlu khawatir tentang itu!",
  ui_story_5029_50290013_35_dialog_content = "Tapi kami tidak...",
  ui_story_5029_50290013_36_dialog_content = "Jika Anda tertarik, saya tidak keberatan menawarkan diskon 90% untuk tiket.",
  ui_story_5029_50290013_37_dialog_content = "Apa?!",
  ui_story_5029_50290013_38_dialog_content = "Vice, Anda sebenarnya tertarik dengan drama itu, bukan?",
  ui_story_5029_50290013_39_dialog_content = "Karena kita harus menunggu sampai pertunjukan selesai, sebaiknya kita menontonnya saja.",
  ui_story_5029_50290013_40_dialog_content = "Terima kasih, Nama Pemain. Saya takut Anda akan terlalu pelit untuk membeli tiket.",
  ui_story_5029_50290013_41_dialog_content = "Terima kasih atas bisnis Anda. Saya harap kalian berdua akan selalu mandi di sungai cinta!",
  ui_story_5029_50290013_42_dialog_content = "...",
  ui_story_5029_50290013_43_dialog_content = "Ahhhh... Hm!",
  ui_story_5029_50290013_44_dialog_content = "(Hubungan saya dengan Vice harus disalahpahami oleh konduktor ...)",
  ui_story_5029_50290013_45_dialog_content = "(Tapi saya benar-benar tidak ingin menuangkan air dingin padanya ...)",
  ui_story_5029_50290013_46_dialog_content = "(Vice juga berpikir begitu ... kan?)",
  ui_story_5029_50290013_47_dialog_content = "L-Ayo masuk ke dalam!",
  ui_story_5029_50290013_48_dialog_content = "Iya!",
  ui_story_5029_50290013_49_dialog_content = "<color=#828282>Suatu saat nanti</color>",
  ui_story_5029_50290013_50_dialog_content = "*Hiks*",
  ui_story_5029_50290013_51_dialog_content = "Saya tidak berharap itu akan sangat menyentuh!",
  ui_story_5029_50290013_52_dialog_content = "Oh! Bagaimana Romi dan Julie bertemu di lautan bunga sangat romantis!",
  ui_story_5029_50290013_53_dialog_content = "Ya.",
  ui_story_5029_50290013_54_dialog_content = "Beverly?!",
  ui_story_5029_50290013_55_dialog_content = "(Saya hampir lupa bahwa kami di sini untuk urusan bisnis!)",
  ui_story_5029_50290013_56_dialog_content = "Sayangnya, dari satu ekstrem ke ekstrem lainnya, hubungan indah mereka di awal berakhir dengan tragedi.",
  ui_story_5029_50290013_57_dialog_content = "Akhirnya, mereka berdua mati di ladang bunga tempat mereka pertama kali bertemu karena salah paham dan rintangan...",
  ui_story_5029_50290013_58_dialog_content = "Pikirkan tentang bagaimana hal itu kembali ke awal... Ini adalah tragedi yang indah.",
  ui_story_5029_50290013_59_dialog_content = "Aku tidak tahu tragedi bisa begitu baik, boo-hoo...",
  ui_story_5029_50290013_60_dialog_content = "Dan saya tidak mengharapkan PlayerName dan Vice juga akan berada di sini untuk pemutaran perdana.",
  ui_story_5029_50290013_61_dialog_content = "Ahem, ya... Kebetulan sekali!",
  ui_story_5029_50290013_62_dialog_content = "Dramanya mungkin tradisional, tetapi memiliki banyak gaya modern.",
  ui_story_5029_50290013_63_dialog_content = "Saya setuju. Ini benar-benar satu-satunya inovasi sejati dalam beberapa tahun terakhir.",
  ui_story_5029_50290013_64_dialog_content = "Tapi tragedi mereka disebabkan oleh perbedaan dramatis dalam status sosial mereka.",
  ui_story_5029_50290013_65_dialog_content = "Hanya jika mereka tahu tentang identitas dan batasan sosial satu sama lain ketika mereka bertemu...",
  ui_story_5029_50290013_65X1_dialog_content = "Mereka bisa saja berakhir dengan sangat berbeda.",
  ui_story_5029_50290013_66_dialog_content = "Aku... aku tidak percaya begitu.",
  ui_story_5029_50290013_67_dialog_content = "Kematian mereka pada akhirnya adalah peringatan bagi kita.",
  ui_story_5029_50290013_68_dialog_content = "Drama itu sebenarnya mendorong semua orang untuk merangkul siapa mereka sebenarnya dan mencintai dengan bebas tanpa ditahan oleh identitas mereka.",
  ui_story_5029_50290013_69_dialog_content = "Oh? Itu benar-benar makna yang lebih dalam ...",
  ui_story_5029_50290013_70_dialog_content = "Saya terkejut Elvis bisa mengakui permainan semacam ini di Harbour City.",
  ui_story_5029_50290013_71_dialog_content = "Anda tahu laird?",
  ui_story_5029_50290013_72_dialog_content = "Tentu. Aku bahkan mengunjunginya kemarin. Sayangnya, kami tidak berpisah dengan baik.",
  ui_story_5029_50290013_73_dialog_content = "Kenapa tidak? Saya pikir laird adalah orang yang baik.",
  ui_story_5029_50290013_74_dialog_content = "Sayangnya, dia hanya seorang bangsawan karena leluhurnya menyerah kepada Lumopolis.",
  ui_story_5029_50290013_75_dialog_content = "Dia mungkin menyandang gelar Lumo Noble, tetapi dia tidak memiliki darah bangsawan.",
  ui_story_5029_50290013_76_dialog_content = "Dia tidak menyembunyikan penghinaannya ketika aku mengungkapkan kebenaran.",
  ui_story_5029_50290013_77_dialog_content = "Dan dia kemudian menyiratkan bahwa keluarga saya sedang menurun dan bagaimana Kota Pelabuhan ini mengalahkan kami.",
  ui_story_5029_50290013_78_dialog_content = "Aku mendidih karena marah, dan aku pergi.",
  ui_story_5029_50290013_79_dialog_content = "Sekarang aku memikirkannya, aku tidak terlalu mulia seperti diriku kemarin...",
  ui_story_5029_50290013_80_dialog_content = "Ini benar-benar langkah besar bagi Anda untuk merenungkan kesalahan Anda sendiri.",
  ui_story_5029_50290013_81_dialog_content = "Hanya jika keluarga Romi dan Julie bisa merenungkan diri mereka sendiri dan berkompromi...",
  ui_story_5029_50290013_82_dialog_content = "Mereka tidak akan berakhir begitu tragis.",
  ui_story_5029_50290013_83_dialog_content = "Terima kasih, Vice.",
  ui_story_5029_50290013_84_dialog_content = "Saya mungkin perlu melihat drama itu lagi untuk mendapatkan hal-hal yang lebih dalam yang Anda bicarakan.",
  ui_story_5029_50290013_85_dialog_content = "Permisi. Saya akan membeli tiket untuk pertunjukan berikutnya sekarang.",
  ui_story_5029_50290013_86_dialog_content = "Beverly adalah orang yang jujur yang mengungkapkan pikirannya... Jelas tidak terlihat seperti pencuri.",
  ui_story_5029_50290013_87_dialog_content = "Ya, para bangsawan arogan itu tidak akan pernah merenungkan kesalahan mereka sendiri.",
  ui_story_5029_50290013_88_dialog_content = "Dia baru saja dicuci otak oleh pemikiran tradisional para bangsawan di Lumopolis.",
  ui_story_5029_50290013_89_dialog_content = "Itu sebabnya dia sangat peduli dengan \"darah bangsawan\".",
  ui_story_5029_50290013_90_dialog_content = "Saya yakin jika dia menonton drama ini beberapa kali lagi, dia akan mengerti apa yang ingin dia katakan.",
  ui_story_5029_50290013_90X1_dialog_content = "Dan mulai berpikir untuk dirinya sendiri!",
  ui_story_5029_50290013_91_dialog_content = "Tapi aku merasa kita lupa menanyakan sesuatu padanya...",
  ui_story_5029_50290013_92_dialog_content = "Permisi. Apakah kalian berdua tahu laird?",
  ui_story_5029_50290013_93_dialog_content = "Ada apa?",
  ui_story_5029_50290013_94_dialog_content = "Nama saya Wanda. Jika tidak terlalu merepotkan, bisakah Anda memberi laird terima kasih saya?",
  ui_story_5029_50290013_95_dialog_content = "Saya pergi ke laird untuk melamar pekerjaan sebagai koki tadi malam.",
  ui_story_5029_50290013_96_dialog_content = "Setelah beberapa sampel, laird memuji hidangan saya dengan sepenuh hati tetapi tidak mempekerjakan saya. . .",
  ui_story_5029_50290013_97_dialog_content = "Saya pikir saya kurang beruntung, tetapi kemudian saya menerima uang benih yang disumbangkan oleh laird pagi ini...",
  ui_story_5029_50290013_98_dialog_content = "Kemudian saya menyadari bahwa laird tidak mempekerjakan saya karena dia ingin saya membuka restoran di sini di Harbour City sehingga lebih banyak orang dapat menikmati hidangan saya...",
  ui_story_5029_50290013_99_dialog_content = "Itu adalah sesuatu yang bahkan tidak pernah berani saya impikan... Saya ingin mengucapkan terima kasih secara pribadi, tetapi saya dihentikan oleh para penjaga.",
  ui_story_5029_50290013_100_dialog_content = "Lalu saya melihat kalian berdua, jadi saya harus bertanya apakah Anda bisa mengucapkan terima kasih untuk saya.",
  ui_story_5029_50290013_101_dialog_content = "Laird benar-benar bertindak untuk kepentingan seluruh kota... Tidak masalah! Aku pasti akan memberitahunya!",
  ui_story_5029_50290013_102_dialog_content = "Tapi... Bagaimana kau tahu kami mengenal sarangnya?",
  ui_story_5029_50290013_103_dialog_content = "Tadi malam, aku melihat bangsawan yang kau ajak bicara di rumah laird.",
  ui_story_5029_50290013_104_dialog_content = "Dan aku mendengarmu berbicara tentang sarang barusan... Jadi aku mengambil kesempatanku.",
  ui_story_5029_50290013_105_dialog_content = "Anda bilang Anda melihat bangsawan itu tadi malam?",
  ui_story_5029_50290013_106_dialog_content = "Ya, saat aku menunggu keputusan laird di halaman belakang...",
  ui_story_5029_50290013_107_dialog_content = "Aku melihat wanita bangsawan cantik itu berjalan keluar rumah...",
  ui_story_5029_50290013_107X1_dialog_content = "Ada banyak rak buku di rumah, saya kira itu perpustakaan.",
  ui_story_5029_50290013_108_dialog_content = "Pokoknya... Terima kasih banyak! Pastikan untuk mampir ke restoran saya setelah buka!",
  ui_story_5029_50290013_109_dialog_content = "Aku…",
  ui_story_5029_50290013_110_dialog_content = "saya pikir Beverly bertemu dengan laird di sore hari... Kenapa dia ada di sana pada malam hari?",
  ui_story_5029_50290013_111_dialog_content = "Dia seharusnya masih berada di loket tiket. Mari kita bertanya padanya.",
  ui_story_5029_50290013_112_dialog_content = "Dimana aku tadi malam?",
  ui_story_5029_50290013_113_dialog_content = "Hmph! Langsung dengan saya. Apakah Elvis mengirim Anda untuk menyelidiki saya?",
  ui_story_5029_50290013_114_option_content = "Tidak.",
  ui_story_5029_50290013_115_dialog_content = "Sama sekali tidak. Kami ingin tahu tempat menarik apa yang pernah Anda kunjungi, hanya untuk referensi kami. Hehehe...",
  ui_story_5029_50290013_116_dialog_content = "Tidak?",
  ui_story_5029_50290013_117_dialog_content = "Saya pikir Anda di sini untuk bertanya mengapa saya berada di ruang kerjanya tadi malam.",
  ui_story_5029_50290013_118_option_content = "Ya.",
  ui_story_5029_50290013_119_dialog_content = "Sst, Nama Pemain! Kita harus merahasiakannya!",
  ui_story_5029_50290013_120_dialog_content = "Ah, berhenti berpura-pura. Aku punya mata dan telinga.",
  ui_story_5029_50290013_121_dialog_content = "Anda di sini untuk mencari tahu mengapa saya berada di ruang kerjanya tadi malam, kan?",
  ui_story_5029_50290013_122_dialog_content = "Apa?!",
  ui_story_5029_50290013_123_dialog_content = "Jadi kau ada di ruang kerja laird tadi malam?",
  ui_story_5029_50290013_124_dialog_content = "Ya. Tidak ada yang aku sembunyikan darimu.",
  ui_story_5029_50290013_125_dialog_content = "Setelah kita berpisah kemarin, aku kehilangan lencana Ksatriaku.",
  ui_story_5029_50290013_126_dialog_content = "Lencana itu memiliki arti khusus bagiku...",
  ui_story_5029_50290013_127_dialog_content = "Tapi kami baru saja bertengkar. Aku tidak bisa membungkuk untuk meminta dia untuk menemukannya untukku.",
  ui_story_5029_50290013_128_dialog_content = "Jadi saya harus mencari sendiri ruang kerjanya tetapi tidak berhasil.",
  ui_story_5029_50290013_129_dialog_content = "Anda melakukannya hanya untuk menemukan lencana?",
  ui_story_5029_50290013_130_dialog_content = "Dengar, aku tidak peduli jika Elvis mengirimmu.",
  ui_story_5029_50290013_130X1_dialog_content = "Atau jika dia menyadari aku menyelinap ke ruang kerjanya atau tidak...",
  ui_story_5029_50290013_131_dialog_content = "Katakan saja padanya, saya tidak tertarik padanya atau studinya.",
  ui_story_5029_50290013_132_dialog_content = "Saya hanya ingin lencana Knight saya kembali.",
  ui_story_5029_50290014_1_dialog_content = "PlayerName, kemana kamu akan pergi?",
  ui_story_5029_50290014_2_dialog_content = "Ruang pembantu ada di sana!",
  ui_story_5029_50290014_3_dialog_content = "Aku datang.",
  ui_story_5029_50290014_4_dialog_content = "Siapa yang berteriak di sini?",
  ui_story_5029_50290014_5_dialog_content = "Ini adalah ruang tunggu! Perhatikan sopan santun Anda!",
  ui_story_5029_50290014_6_dialog_content = "Hah? Siapa wanita tua itu?",
  ui_story_5029_50290014_7_dialog_content = "Wanita tua?",
  ui_story_5029_50290014_8_dialog_content = "Dari mana datangnya gadis kecil manja sepertimu?",
  ui_story_5029_50290014_9_dialog_content = "Anda harus memanggil saya sebagai Nyonya!",
  ui_story_5029_50290014_10_dialog_content = "Hmph! Kenapa harus saya?",
  ui_story_5029_50290014_11_dialog_content = "Kau…!",
  ui_story_5029_50290014_12_dialog_content = "Saya sangat menyesal, Bu!",
  ui_story_5029_50290014_13_option_content = "Dia hanya seorang anak kecil.",
  ui_story_5029_50290014_14_dialog_content = "Mengapa harus marah pada anak kecil yang naif?",
  ui_story_5029_50290014_15_dialog_content = "Apa?",
  ui_story_5029_50290014_16_option_content = "Dia anak yang baik.",
  ui_story_5029_50290014_17_dialog_content = "Dia hanya sedikit tumpul. Jangan pedulikan dia.",
  ui_story_5029_50290014_18_dialog_content = "Hmph.",
  ui_story_5029_50290014_19_dialog_content = "Jadi, kenapa kau di sini?",
  ui_story_5029_50290014_20_dialog_content = "Zane memberi tahu kami bahwa kami dapat menemukan...",
  ui_story_5029_50290014_21_dialog_content = "Oh, jadi Zane merujukmu.",
  ui_story_5029_50290014_22_dialog_content = "Zane sangat dipercaya oleh laird.",
  ui_story_5029_50290014_23_dialog_content = "Jika dia merujuk Anda kepada saya, saya harus memberi Anda kesempatan.",
  ui_story_5029_50290014_24_dialog_content = "R-Merekomendasikan?",
  ui_story_5029_50290014_25_dialog_content = "Apa-apaan...",
  ui_story_5029_50290014_26_dialog_content = "Jadi siapa namamu?",
  ui_story_5029_50290014_27_dialog_content = "Saya Nama Pemain. Kami di sini untuk...",
  ui_story_5029_50290014_28_dialog_content = "Saya tidak meminta Anda. Kakakmu tidak bisa bicara sendiri?",
  ui_story_5029_50290014_29_dialog_content = "PlayerName bukan saudaraku!",
  ui_story_5029_50290014_29X1_dialog_content = "Aku tidak punya saudara! Saya memiliki ayah, ibu, tuan, dan Shira!",
  ui_story_5029_50290014_30_dialog_content = "Terserah... Aku tidak peduli dengan semua itu.",
  ui_story_5029_50290014_31_dialog_content = "Katakan padaku apa yang kamu kuasai.",
  ui_story_5029_50290014_32_dialog_content = "M-Banyak hal!",
  ui_story_5029_50290014_33_dialog_content = "Saya seorang ahli ekstrozoologi. Saya membesarkan, berevolusi, dan membiakkan binatang buas yang menakjubkan!",
  ui_story_5029_50290014_34_dialog_content = "Memelihara hewan memang keterampilan yang bagus, tapi kami tidak menjalankan peternakan di sini.",
  ui_story_5029_50290014_35_dialog_content = "Namun, saya dapat menugaskan Anda ke dapur.",
  ui_story_5029_50290014_36_dialog_content = "Menugaskan saya ke dapur?",
  ui_story_5029_50290014_37_dialog_content = "Apa? Tidak senang?",
  ui_story_5029_50290014_38_dialog_content = "Dilihat dari penampilan Anda, Anda belum pernah bekerja sebagai pelayan sebelumnya, bukan?",
  ui_story_5029_50290014_39_dialog_content = "Bersyukurlah bahwa Anda dapat memulai karir Anda sebagai pelayan untuk laird.",
  ui_story_5029_50290014_40_dialog_content = "Bu, saya pikir Anda salah paham ...",
  ui_story_5029_50290014_41_dialog_content = "M-Bu.",
  ui_story_5029_50290014_42_dialog_content = "Pembantu yang ingin melamar pekerjaan sedang menunggu di luar.",
  ui_story_5029_50290014_43_dialog_content = "Di luar? Lalu siapa kalian berdua...?",
  ui_story_5029_50290014_44_dialog_content = "Tuan Navigator?",
  ui_story_5029_50290014_45_dialog_content = "Eh? K-Kenapa kamu di sini?",
  ui_story_5029_50290014_46_dialog_content = "Ini... cerita yang panjang. Mengapa Anda di Harbour City?",
  ui_story_5029_50290014_47_dialog_content = "PlayerName dan saya di sini mencari pembantu bernama Manae. Anda tahu dia?",
  ui_story_5029_50290014_48_dialog_content = "Aku… aku…",
  ui_story_5029_50290014_49_dialog_content = "Jadi Zane mengirim kalian berdua untuk mencari Manae?",
  ui_story_5029_50290014_50_dialog_content = "Saya pikir Anda di sini untuk pekerjaan itu. Saya sangat menyesal tentang sebelumnya!",
  ui_story_5029_50290014_51_dialog_content = "Mana.",
  ui_story_5029_50290014_52_dialog_content = "Y-Ya. Aku disini!",
  ui_story_5029_50290014_53_dialog_content = "Mereka di sini untuk Anda. Aku akan mewawancarai pelayan baru.",
  ui_story_5029_50290014_54_dialog_content = "Ya, Kapten!",
  ui_story_5029_50290014_55_dialog_content = "Anda Manae?",
  ui_story_5029_50290014_56_dialog_content = "Beritahu kami yang sebenarnya! Rahasia kotor apa yang kamu coba sembunyikan?!",
  ui_story_5029_50290014_57_dialog_content = "AKU AKU AKU AKU...",
  ui_story_5029_50290014_58_dialog_content = "Sanae... Saya pikir Manae adalah nama adikmu.",
  ui_story_5029_50290014_59_dialog_content = "Bahkan namanya palsu?",
  ui_story_5029_50290014_60_dialog_content = "Aku tahu aku benar mencurigaimu!",
  ui_story_5029_50290014_61_dialog_content = "Fi, aku tahu Sanae. Dia tidak curiga.",
  ui_story_5029_50290014_62_dialog_content = "Mari kita dengarkan apa yang dia katakan, oke?",
  ui_story_5029_50290014_63_dialog_content = "T-Terima kasih, Tuan Navigator...",
  ui_story_5029_50290014_64_dialog_content = "Mengapa kamu di sini dan tidak bersama Nina di Umbraton?",
  ui_story_5029_50290014_65_dialog_content = "Aku... Aku dipecat oleh Andersen.",
  ui_story_5029_50290014_66_dialog_content = "Saya harus meminta guild untuk mencarikan saya pekerjaan di sini di Harbour City.",
  ui_story_5029_50290014_67_dialog_content = "... Nina biarkan saja mereka memecatmu?",
  ui_story_5029_50290014_68_dialog_content = "Merindukan Nina dan aku... Kita berbeda...",
  ui_story_5029_50290014_69_dialog_content = "Aku hanya seorang pembantu. Aku bukan apa-apa baginya.",
  ui_story_5029_50290014_70_dialog_content = "Aku sudah meletakkan semuanya di belakangku, jadi...",
  ui_story_5029_50290014_71_dialog_content = "Tapi itu tidak menjelaskan mengapa Anda menggunakan nama palsu.",
  ui_story_5029_50290014_72_dialog_content = "Yah... Aku hanya tidak ingin ada yang tahu bahwa aku pernah dipecat.",
  ui_story_5029_50290014_73_dialog_content = "Ahhhh! Aku lupa aku harus membersihkan halaman!",
  ui_story_5029_50290014_74_dialog_content = "Jika saya tidak menyelesaikannya dengan cepat, saya akan dipecat lagi!",
  ui_story_5029_50290014_75_dialog_content = "Kyllo, jangan biarkan itu kabur!",
  ui_story_5029_50290014_76_dialog_content = "Lihat!",
  ui_story_5029_50290014_77_dialog_content = "Aaah! M-Manae!",
  ui_story_5029_50290014_78_dialog_content = "Dari mana anjing liar yang gila ini berasal? Kembali!",
  ui_story_5029_50290014_79_dialog_content = "lihat...",
  ui_story_5029_50290014_80_dialog_content = "Sanae perlu kembali bekerja, tidak bisakah kamu melihatnya?",
  ui_story_5029_50290014_81_dialog_content = "Atau apakah Anda akan bertanggung jawab jika dia kehilangan pekerjaannya?",
  ui_story_5029_50290014_82_dialog_content = "Ayo pergi, Sanae. Lupakan tentang mereka.",
  ui_story_5029_50290014_83_dialog_content = "lihat...",
  ui_story_5029_50290014_84_dialog_content = "Kylo, tidak apa-apa. Jangan takut. Mereka sudah pergi sekarang.",
  ui_story_5029_50290014_85_dialog_content = "Lihat!",
  ui_story_5029_50290014_86_dialog_content = "PlayerName, itu teman lama yang kamu kenal dan percaya?",
  ui_story_5029_50290014_87_dialog_content = "Dia berusaha menghindari pertanyaan itu!",
  ui_story_5029_50290014_88_dialog_content = "Saya harus mengatakan... Bagaimana dia bertindak cukup mencurigakan.",
  ui_story_5029_50290014_89_dialog_content = "Itu Sanae Aku tahu tidak akan menyembunyikan hal-hal seperti itu.",
  ui_story_5029_50290014_90_dialog_content = "Anda juga sedang menyelidiki pelayan itu, bukan? Aku selalu menganggapnya mencurigakan.",
  ui_story_5029_50290014_91_dialog_content = "Anda, pria paruh baya dengan tongkat. Kamu siapa?",
  ui_story_5029_50290014_92_dialog_content = "Maaf, saya lupa memperkenalkan diri.",
  ui_story_5029_50290014_93_dialog_content = "Saya Koki. Keluarga kami telah bekerja untuk laird sejak generasi kakekku.",
  ui_story_5029_50290014_94_dialog_content = "Kakiku terluka tahun lalu, jadi sekarang aku membantu mengatur pelayan. Saya tahu semua pelayan di sini.",
  ui_story_5029_50290014_95_dialog_content = "Tapi saya benar-benar menemukan Manae ini berbeda dari orang lain.",
  ui_story_5029_50290014_96_dialog_content = "Maksudmu?",
  ui_story_5029_50290014_97_dialog_content = "Saya mendengar bahwa laird membawanya hanya karena dia datang sangat direkomendasikan oleh Persekutuan Umbraton.",
  ui_story_5029_50290014_98_dialog_content = "Sejak dia datang, dia memecahkan piring, mengacaukan barang-barang, dan menyebabkan kekacauan di sekitar rumah. Dia mengambil cukup dipotong gajinya selama berbulan-bulan sekarang.",
  ui_story_5029_50290014_99_dialog_content = "Namun, dia sepertinya tidak mempermasalahkan itu semua. Dia hanya mencoba untuk berkeliaran di sarang setiap ada kesempatan.",
  ui_story_5029_50290014_100_dialog_content = "Instingku memberitahuku bahwa dia ada di sini untuk alasan lain.",
  ui_story_5029_50290014_101_dialog_content = "Terlebih lagi, aku melihatnya menyelinap ke ruang kerja laird tadi malam.",
  ui_story_5029_50290014_102_dialog_content = "Tadi malam?!",
  ui_story_5029_50290014_103_dialog_content = "Dia seharusnya melakukan pembersihan di sana pada siang hari, kan?",
  ui_story_5029_50290014_104_dialog_content = "Aku juga merasa aneh, tapi aku tidak berani mengatakan lebih banyak karena dia dikirim oleh Umbraton Guild.",
  ui_story_5029_50290014_105_dialog_content = "Tapi aku masih khawatir jika dia merencanakan sesuatu untuk melawan laird.",
  ui_story_5029_50290014_106_dialog_content = "Aku harus mempercayakan penyelidikan ini kepada kalian berdua...",
  ui_story_5029_50290014_107_dialog_content = "PlayerName, kamu tidak akan mencoba melindungi \"teman lama\" kamu kali ini, kan?",
  ui_story_5029_50290014_108_dialog_content = "Mari kita hadapi dia tentang ini.",
  ui_story_5029_50290014_109_dialog_content = "eh...? Apakah laird meminta Anda untuk menyelidiki saya?",
  ui_story_5029_50290014_110_option_content = "Tidak.",
  ui_story_5029_50290014_111_dialog_content = "Laird tidak tahu tentang ini.",
  ui_story_5029_50290014_112_dialog_content = "Tapi Kok bilang...",
  ui_story_5029_50290014_113_option_content = "Ya.",
  ui_story_5029_50290014_114_dialog_content = "(Sial! Aku lupa kita harus merahasiakan ini!)",
  ui_story_5029_50290014_115_dialog_content = "Ahem! Bagaimanapun, yang kami dengar dari Cook adalah...",
  ui_story_5029_50290014_116_dialog_content = "Anda pergi ke ruang kerja laird tanpa izin tadi malam.",
  ui_story_5029_50290014_117_dialog_content = "Tuan Cook... Dia memberitahumu?",
  ui_story_5029_50290014_118_dialog_content = "D-Dia berjanji tidak akan memberitahu...",
  ui_story_5029_50290014_119_dialog_content = "Anda bahkan mencoba menyuap Cook?",
  ui_story_5029_50290014_120_dialog_content = "T-Tidak... Aku tidak mencoba menyuap siapa pun!",
  ui_story_5029_50290014_121_dialog_content = "Lalu mengapa kamu masuk ke ruang kerja laird ketika tidak ada orang di sekitar?",
  ui_story_5029_50290014_122_dialog_content = "Aku... Aku memecahkan vas bunga di lobi saat aku sedang bersih-bersih di siang hari.",
  ui_story_5029_50290014_123_dialog_content = "Tapi kemudian Pak Zane menyuruh saya meninggalkan ruangan, mengatakan bahwa tamu akan datang.",
  ui_story_5029_50290014_124_dialog_content = "Saya takut seseorang akan mengetahui bahwa saya telah memecahkan vas itu... dan saya akan dipecat...",
  ui_story_5029_50290014_125_dialog_content = "Jadi aku menyembunyikan pecahan vas itu di bawah sofa... dan berencana untuk membersihkannya sendiri di malam hari.",
  ui_story_5029_50290014_126_dialog_content = "Ha! Dan siapa yang menemukan potongan-potongan itu? SAYA!",
  ui_story_5029_50290014_127_dialog_content = "Sepertinya saya tidak melakukan pekerjaan yang cukup baik, boo-hoo...",
  ui_story_5029_50290014_128_dialog_content = "Tapi masih ada vas bunga di atas meja di lobi.",
  ui_story_5029_50290014_129_dialog_content = "Itu karena... Aku membeli yang lain dari jenis yang sama.",
  ui_story_5029_50290014_130_dialog_content = "Kudengar gajimu dipotong selama berbulan-bulan. Bagaimana Anda bisa membeli vas yang berharga itu?",
  ui_story_5029_50290014_131_dialog_content = "Waaaaaaaah...!",
  ui_story_5029_50290014_132_dialog_content = "Jadi, dari mana Anda mendapatkan uang itu?",
  ui_story_5029_50290014_133_dialog_content = "Aku rindu Nina berikan padaku...",
  ui_story_5029_50290014_134_dialog_content = "Tn. Navigator... Saya tahu bahwa saya tidak cocok untuk pekerjaan ini.",
  ui_story_5029_50290014_135_dialog_content = "Tapi Nona Nina mengirimku ke sini... dan aku tidak ingin mengecewakannya.",
  ui_story_5029_50290014_136_dialog_content = "Jadi Nina tidak memecatmu, kan?",
  ui_story_5029_50290014_137_dialog_content = "Eh… Ya.",
  ui_story_5029_50290014_138_dialog_content = "Nina mengirimmu untuk mencuri sesuatu?",
  ui_story_5029_50290014_139_dialog_content = "Mencuri...? Apa?",
  ui_story_5029_50290014_140_dialog_content = "Saya di sini hanya untuk mencoba mencari tahu seperti apa laird itu sebenarnya dan hobinya.",
  ui_story_5029_50290014_141_dialog_content = "Merindukan Nina ingin tahu semua yang perlu diketahui sehingga dia bisa menegosiasikan kesepakatan dengan laird.",
  ui_story_5029_50290014_142_dialog_content = "Aku tahu aku tidak siap untuk tugas seperti itu... dan sekarang aku tertangkap oleh Tuan Navigator.",
  ui_story_5029_50290014_143_dialog_content = "Apa yang akan saya katakan? Nina... Huu huu...",
  ui_story_5029_50290015_1_dialog_content = "Semua orang terlihat sangat tidak ramah hari ini.",
  ui_story_5029_50290015_2_dialog_content = "Haruskah saya membiarkan mereka bertarung di antara mereka sendiri?",
  ui_story_5029_50290015_3_dialog_content = "Tunggu. Saya seorang detektif yang cakap juga. Saya bisa melakukan ini sendiri.",
  ui_story_5029_50290015_4_dialog_content = "Jika aku yang mencari tahu semuanya, mungkin mereka akan berhenti bertengkar satu sama lain.",
  ui_story_5029_50290015_5_dialog_content = "Benar! Lanjutkan!",
  ui_story_5029_50290015_6_dialog_content = "Aku hampir selesai mencari di sekitar rumah...",
  ui_story_5029_50290015_7_dialog_content = "Mungkinkah ada petunjuk di luar rumah?",
  ui_story_5029_50290015_8_dialog_content = "Laird pasti punya rumah yang bagus.",
  ui_story_5029_50290015_9_dialog_content = "Satu sisi menghadap laut, satu sisi menghadap hutan.",
  ui_story_5029_50290015_10_dialog_content = "Nah, menurut Zane, hutan itu hanya halaman belakang sarang...",
  ui_story_5029_50290015_11_dialog_content = "<color=#828282>Kresek...</color>",
  ui_story_5029_50290015_12_dialog_content = "Hah?",
  ui_story_5029_50290015_13_dialog_content = "Apakah seseorang baru saja lewat...?",
  ui_story_5029_50290015_14_dialog_content = "Ada seseorang di sini! Aku tidak sedang berhalusinasi.",
  ui_story_5029_50290015_15_dialog_content = "Hai! Apa yang kamu lakukan di sini?",
  ui_story_5029_50290015_16_dialog_content = "K-Kenapa kamu tidak mau bicara?",
  ui_story_5029_50290015_17_dialog_content = "Apa yang akan kamu lakukan?!",
  ui_story_5029_50290015_18_dialog_content = "Ayo! Mari kita bicarakan! Anda tidak perlu mengangkat sekop seperti itu ...",
  ui_story_5029_50290015_19_dialog_content = "<color=#828282>Bum!</color>",
  ui_story_5029_50290015_20_dialog_content = "Kamu...",
  ui_story_5029_50290015_21_dialog_content = "Kenapa kamu...",
  ui_story_5029_50290015_22_dialog_content = "<color=#828282>Ding...</color>",
  ui_story_5029_50290015_23_dialog_content = "Selamat datang kembali, tamu tersayang.",
  ui_story_5029_50290015_24_dialog_content = "Saya minta maaf bahwa ramalan itu dipotong pendek ...",
  ui_story_5029_50290015_25_dialog_content = "Pilihan yang buruk mengarah pada akhir yang canggung seperti itu.",
  ui_story_5029_50290015_26_dialog_content = "Bagaimana kalau kita mendekatinya lagi dari sudut lain?",
  ui_story_5029_50290015_27_dialog_content = "Itu hanya... mimpi yang tidak begitu menyenangkan.",
  ui_story_5029_50290015_28_dialog_content = "Anda tidak dalam bahaya fisik dengan cara apapun.",
  ui_story_5029_50290015_29_dialog_content = "Jadi bahkan itu tidak akan membuat pikiran Anda tenang?",
  ui_story_5029_50290015_30_dialog_content = "Kabar baiknya adalah... kita masih punya waktu.",
  ui_story_5029_50290015_31_dialog_content = "Mari kita mulai lagi.",
  ui_story_5029_50290015_32_dialog_content = "Itu hal terbaik tentang mimpi, bukan?",
  ui_story_5029_50290016_1_dialog_content = "Seperti Jomu benar-benar menjadi sah.",
  ui_story_5029_50290016_2_dialog_content = "Saya hanya tidak berpikir bahwa dia bahkan tidak punya cukup uang untuk akomodasi.",
  ui_story_5029_50290016_3_dialog_content = "Oh, dia tidak mampu membeli hotel mewah. Selalu ada penginapan yang lebih murah yang dia mampu.",
  ui_story_5029_50290016_4_dialog_content = "Jika itu masalahnya, mengapa Anda menemukan dia tempat tinggal gratis?",
  ui_story_5029_50290016_5_dialog_content = "Tempat yang kuceritakan padanya adalah milik pribadi yang dimiliki oleh laird dan diawasi oleh pengawalnya.",
  ui_story_5029_50290016_6_dialog_content = "Mereka akan memberi tahu kami saat ini Jomu melakukan sesuatu yang mencurigakan.",
  ui_story_5029_50290016_7_dialog_content = "Jadi kamu masih tidak percaya Jomu.",
  ui_story_5029_50290016_8_dialog_content = "Sepertinya dia benar-benar tidak tahu apa-apa tentang kotak perak itu.",
  ui_story_5029_50290016_9_dialog_content = "Itu juga yang saya pikirkan. Pilihannya untuk tetap tinggal membuktikan bahwa dia tidak memiliki hal lain untuk disembunyikan.",
  ui_story_5029_50290016_10_dialog_content = "Bagi saya, apa yang saya lakukan hanyalah tindakan pencegahan.",
  ui_story_5029_50290016_11_dialog_content = "Dan aku berjanji Jomu bahwa saya akan membuatnya bertemu lagi dengan laird.",
  ui_story_5029_50290016_12_dialog_content = "Saya pikir Anda hanya mengatakan itu untuk menjaga Jomu di sini.",
  ui_story_5029_50290016_13_dialog_content = "Ya. Tapi janji adalah janji. Saya akan berusaha sebaik mungkin untuk mewujudkannya.",
  ui_story_5029_50290016_14_dialog_content = "Kehormatan seorang ksatria dipertaruhkan di sini. Saya tidak akan mengkhianati rasa hormat dan kepercayaan orang lain terhadap saya.",
  ui_story_5029_50290016_15_dialog_content = "(Apakah itu berlaku untuk pertunangan yang kita bicarakan di hotel...?)",
  ui_story_5029_50290016_16_dialog_content = "Yo-ho! Saya mendengarnya!",
  ui_story_5029_50290016_17_dialog_content = "Apa? Apakah saya berpikir keras?",
  ui_story_5029_50290016_18_dialog_content = "Jadi, sudahkah Anda menghilangkan Jomu sebagai tersangka?",
  ui_story_5029_50290016_19_dialog_content = "(Jadi itu yang dia maksud...)",
  ui_story_5029_50290016_20_dialog_content = "Vice, Fia, kapan kamu...",
  ui_story_5029_50290016_21_dialog_content = "Astaga. Saya harus bergegas dengan penyelidikan.",
  ui_story_5029_50290016_22_dialog_content = "Apakah itu berarti tersangka saya mungkin berubah menjadi pencuri yang sebenarnya?",
  ui_story_5029_50290016_23_dialog_content = "Kyl, ayo pergi!",
  ui_story_5029_50290016_24_dialog_content = "Lihat!",
  ui_story_5029_50290016_25_dialog_content = "Kalian berdua, jangan biarkan aku menggantung...!",
  ui_story_5029_50290016_26_dialog_content = "Huff... Huff... Kemana mereka pergi sekarang?",
  ui_story_5029_50290016_27_dialog_content = "PlayerName, tidak perlu mengejar mereka.",
  ui_story_5029_50290016_28_dialog_content = "Mari kita kembali ke ruangan dan melihat apakah kita bisa menemukan yang lain.",
  ui_story_5029_50290016_29_dialog_content = "Baiklah…",
  ui_story_5029_50290016_30_dialog_content = "Aduh, betapa aku berharap pencuri itu jatuh ke pangkuanku sekarang.",
  ui_story_5029_50290016_31_dialog_content = "<color=#828282>Bum!</color>",
  ui_story_5029_50290016_32_dialog_content = "Hai! Awas!",
  ui_story_5029_50290016_33_dialog_content = "...",
  ui_story_5029_50290016_34_dialog_content = "Hai! Kamu pikir kamu bisa pergi tanpa permintaan maaf karena menjatuhkan barang-barangku?!",
  ui_story_5029_50290016_35_dialog_content = "Ck! Hanya keberuntunganku!",
  ui_story_5029_50290016_36_dialog_content = "Aku tidak mengerti pria itu, membungkus dirinya dengan jubah panjang di hari yang begitu panas...",
  ui_story_5029_50290016_37_dialog_content = "Orang yang menutupi wajahnya dan bertingkah mencurigakan biasanya menyembunyikan sesuatu.",
  ui_story_5029_50290016_38_dialog_content = "Sesuatu... untuk disembunyikan...?",
  ui_story_5029_50290016_39_dialog_content = "Kurasa aku melihatnya menyembunyikan sesuatu di balik jubahnya...",
  ui_story_5029_50290016_40_dialog_content = "...",
  ui_story_5029_50290016_41_dialog_content = "Kotak perak?!",
  ui_story_5029_50290016_42_dialog_content = "Hai! Berhenti di sana!",
  ui_story_5029_50290016_43_dialog_content = "Oh tidak! Dia mulai melarikan diri!",
  ui_story_5029_50290016_44_dialog_content = "Kecurigaan kami terbukti! Setelah dia!",
  ui_story_5029_50290017_1_dialog_content = "Jika kita tidak menghadapi Beverly, Aku ingin tahu berapa lama dia akan memikirkan bagaimana dia kehilangan lencana sendirian.",
  ui_story_5029_50290017_2_dialog_content = "Apa Beverly umumnya cocok dengan apa yang dikatakan laird kepada kami. Namun...",
  ui_story_5029_50290017_3_dialog_content = "Saya ingat laird memberi tahu kami bahwa dia hanya menyarankan agar dia bisa mencoba membantu mengembangkan tanah keluarganya.",
  ui_story_5029_50290017_4_dialog_content = "Beverly pasti salah paham apa yang dimaksud laird.",
  ui_story_5029_50290017_5_dialog_content = "Kadang-kadang saya pikir para bangsawan Lumopolis dan saya bahkan tidak berbicara bahasa yang sama...",
  ui_story_5029_50290017_6_dialog_content = "Mereka hanya harus memperumit segalanya dengan menjadikan setiap hal kecil menjadi masalah besar.",
  ui_story_5029_50290017_7_dialog_content = "Yang tidak aku mengerti adalah, karena kita tahu di mana lencana Beverly berada...",
  ui_story_5029_50290017_8_dialog_content = "Mengapa Anda tidak membiarkan saya memberitahunya?",
  ui_story_5029_50290017_9_dialog_content = "Pikirkan tentang itu. Jika kita mengatakan Beverly lencananya ada di kafe laird...",
  ui_story_5029_50290017_10_dialog_content = "Bukankah dia akan pergi begitu saja setelah mendapatkannya kembali?",
  ui_story_5029_50290017_11_dialog_content = "Sepertinya begitu…",
  ui_story_5029_50290017_12_dialog_content = "Jika itu masalahnya, maka mereka tidak akan pernah memiliki kesempatan untuk meluruskan semuanya.",
  ui_story_5029_50290017_13_dialog_content = "Maksudmu, kita harus membuat laird sadar bahwa Beverly kehilangan lencana di kafenya?",
  ui_story_5029_50290017_14_dialog_content = "Jadi laird akan mengembalikannya padanya?",
  ui_story_5029_50290017_15_dialog_content = "Ya. Kami sedang menyiapkan panggung di mana mereka bisa berakhir dengan berjabat tangan.",
  ui_story_5029_50290017_16_dialog_content = "Vice, Anda benar-benar memikirkan kepentingan terbaik semua orang...",
  ui_story_5029_50290017_17_dialog_content = "Aku tahu aku terlalu mengkhawatirkan diriku sendiri dengan ini...",
  ui_story_5029_50290017_18_dialog_content = "Beverly dan laird keduanya agak \"seperti bangsawan tua\" dalam cara mereka, tetapi mereka adalah orang baik.",
  ui_story_5029_50290017_19_dialog_content = "Aku hanya tidak bisa berdiri dan menonton, tidak ketika aku tahu ada kesalahpahaman besar di antara mereka.",
  ui_story_5029_50290017_20_dialog_content = "Saya tidak ingin melihat Romi dan Julie terjadi di kehidupan nyata di sekitar saya.",
  ui_story_5029_50290017_21_dialog_content = "Jadi Beverly keluar dari daftar tersangka Anda sekarang?",
  ui_story_5029_50290017_22_dialog_content = "Iya!",
  ui_story_5029_50290017_23_dialog_content = "Tapi... itu artinya kita harus memulai dari awal lagi.",
  ui_story_5029_50290017_24_dialog_content = "Ah! Apa yang saya dengar?",
  ui_story_5029_50290017_25_dialog_content = "Jadi Beverly bukan tersangka lagi?",
  ui_story_5029_50290017_26_dialog_content = "Carleen, Fia, kapan kamu...",
  ui_story_5029_50290017_27_dialog_content = "Maaf mengganggu. Saya akan kembali ke penyelidikan saya.",
  ui_story_5029_50290017_28_dialog_content = "Sepertinya tersangka saya mungkin berubah menjadi pencuri yang sebenarnya!",
  ui_story_5029_50290017_29_dialog_content = "Kyl, ayo pergi!",
  ui_story_5029_50290017_30_dialog_content = "Jadi, apakah kalian berdua membuat kemajuan⁠—Hei! Jangan lari dariku!",
  ui_story_5029_50290017_31_dialog_content = "Huff... Huff... Kemana mereka pergi sekarang?",
  ui_story_5029_50290017_32_dialog_content = "Tidak apa-apa, Nama Pemain.",
  ui_story_5029_50290017_33_dialog_content = "Mari kita kembali dan melanjutkan penyelidikan.",
  ui_story_5029_50290017_34_dialog_content = "Saya setuju, tapi...",
  ui_story_5029_50290017_35_dialog_content = "Apakah Anda tahu jalan kembali?",
  ui_story_5029_50290017_36_dialog_content = "Hah?",
  ui_story_5029_50290017_37_dialog_content = "Saya tidak memperhatikan ke mana kami pergi ketika saya mencoba mengejar mereka ...",
  ui_story_5029_50290017_38_dialog_content = "Lalu aku menemukan diri kami di gang ini...",
  ui_story_5029_50290017_39_dialog_content = "Tidak masalah. Kami hanya akan menanyakan arah kepada pejalan kaki itu.",
  ui_story_5029_50290017_40_dialog_content = "Permisi. Apakah kamu...",
  ui_story_5029_50290017_41_dialog_content = "...",
  ui_story_5029_50290017_42_dialog_content = "Tunggu! Kami tidak bermaksud menyakitimu! Kami hanya ingin tahu cara kembali ke rumah laird!",
  ui_story_5029_50290017_43_dialog_content = "…!",
  ui_story_5029_50290017_44_dialog_content = "Orang itu sangat aneh... Dia kabur begitu saja tanpa mendengarkan kita.",
  ui_story_5029_50290017_45_dialog_content = "Dan mengapa dia mengenakan jubah panjang dengan wajah tertutup di hari yang begitu panas...?",
  ui_story_5029_50290017_46_dialog_content = "Jika saya tidak salah ...",
  ui_story_5029_50290017_47_dialog_content = "Aku melihatnya memegang sesuatu yang berkilau di bawah jubahnya...",
  ui_story_5029_50290017_48_dialog_content = "...",
  ui_story_5029_50290017_49_dialog_content = "Kotak perak?!",
  ui_story_5029_50290017_50_dialog_content = "A-Setelah dia!",
  ui_story_5029_50290018_1_dialog_content = "PlayerName, apakah Anda yakin tidak akan memberi tahu laird tentang ini?",
  ui_story_5029_50290018_2_dialog_content = "Sanae telah berjanji kepada saya untuk berhenti dari pekerjaan dalam beberapa hari.",
  ui_story_5029_50290018_3_dialog_content = "Dan Nina akan meminta maaf kepada laird selama negosiasinya untuk menyelesaikan ini.",
  ui_story_5029_50290018_4_dialog_content = "Nina mungkin hanya bertanya Sanae melakukan ini karena dia terlalu menghargai negosiasi ini...",
  ui_story_5029_50290018_5_dialog_content = "Dia hanya ingin mempersiapkannya dengan mempelajari hobi dan minat laird.",
  ui_story_5029_50290018_6_dialog_content = "Nina Andersen sudah memiliki banyak toko di Umbraton. Bukankah dia cukup kenyang?",
  ui_story_5029_50290018_7_dialog_content = "Jadi, bukan begitu?",
  ui_story_5029_50290018_8_dialog_content = "Anda sudah menjadi ahli ekstrozoologi yang hebat, namun Anda masih berusaha untuk menjadi lebih baik.",
  ui_story_5029_50290018_9_dialog_content = "Hmph, tentu saja!",
  ui_story_5029_50290018_10_dialog_content = "Saya akan menjadi ahli ekstrozoologi yang lebih baik daripada tuan saya dan menulis buku terbaik tentang binatang yang menakjubkan!",
  ui_story_5029_50290018_11_dialog_content = "Hm... Kurasa sekarang aku mulai mengerti caranya Nina terasa.",
  ui_story_5029_50290018_12_dialog_content = "Ngomong-ngomong, apakah kamu yakin? Sanae tidak bersalah dalam hal ini?",
  ui_story_5029_50290018_13_dialog_content = "Bagaimana jika dia menjadi serakah dan menginginkan harta itu untuk dirinya sendiri?",
  ui_story_5029_50290018_14_dialog_content = "Dari apa yang saya ketahui Sanae, dia tidak memiliki ambisi seperti itu... atau nyali.",
  ui_story_5029_50290018_15_dialog_content = "Tapi kita belajar sesuatu yang penting, bukan?",
  ui_story_5029_50290018_16_dialog_content = "Ya, jika apa yang dia katakan itu benar...",
  ui_story_5029_50290018_17_dialog_content = "Pintunya sudah tidak terkunci sebelum dia masuk ke ruang kerja.",
  ui_story_5029_50290018_18_dialog_content = "Jadi pelayan yang dikirim oleh guild sebenarnya adalah pelayan Nina, Sanae?",
  ui_story_5029_50290018_19_dialog_content = "Apa itu berarti Sanae bukan tersangka lagi?",
  ui_story_5029_50290018_20_dialog_content = "Wahhhhh!",
  ui_story_5029_50290018_21_dialog_content = "Bagaimana Anda bisa menguping petunjuk kunci kami?!",
  ui_story_5029_50290018_22_dialog_content = "Saya minta maaf. Saya baru saja kembali untuk menemukan lebih banyak petunjuk dan kebetulan mendengar Anda.",
  ui_story_5029_50290018_23_dialog_content = "Sekarang, mohon permisi dari percakapan pribadi Anda.",
  ui_story_5029_50290018_24_dialog_content = "Astaga. Saya harus bergegas dengan penyelidikan.",
  ui_story_5029_50290018_25_dialog_content = "Jadi, apakah kalian berdua membuat kemajuan⁠—",
  ui_story_5029_50290018_26_dialog_content = "Hai! Jangan lari dariku!",
  ui_story_5029_50290018_27_dialog_content = "Ah! Seseorang akan mengalahkan saya untuk hadiah uang!",
  ui_story_5029_50290018_28_dialog_content = "Kyl, cepat!",
  ui_story_5029_50290018_29_dialog_content = "Lo, lo, lo...",
  ui_story_5029_50290018_30_dialog_content = "Hm? Kyllo? Apa yang kamu lihat dari jendela? Ayo!",
  ui_story_5029_50290018_31_dialog_content = "Hanya ada pohon di luar...",
  ui_story_5029_50290018_32_dialog_content = "Halaman belakang laird benar-benar tenang.",
  ui_story_5029_50290018_33_dialog_content = "Hah? Apakah itu seorang pria ... di hutan?",
  ui_story_5029_50290018_34_dialog_content = "Lihat, Nama Pemain. Orang itu bertingkah aneh!",
  ui_story_5029_50290018_35_dialog_content = "Menutupi dirinya dengan jubah panjang di hari yang begitu panas.",
  ui_story_5029_50290018_36_dialog_content = "Jika saya tidak memiliki mata yang bagus, saya akan menganggapnya sebagai Eclipsite atau binatang ajaib yang belum pernah saya lihat sebelumnya.",
  ui_story_5029_50290018_37_dialog_content = "Sedang apa dia?",
  ui_story_5029_50290018_38_dialog_content = "Meletakkan sesuatu di pangkuannya?",
  ui_story_5029_50290018_39_dialog_content = "Benda itu terlihat besar dan keperakan.",
  ui_story_5029_50290018_40_dialog_content = "...",
  ui_story_5029_50290018_41_dialog_content = "Kotak perak?!",
  ui_story_5029_50290018_42_dialog_content = "Tidak mungkin! Pencurinya ada di halaman belakang sarang?",
  ui_story_5029_50290018_43_dialog_content = "...",
  ui_story_5029_50290018_44_dialog_content = "Saya pikir dia baru saja melihat kita!",
  ui_story_5029_50290018_45_dialog_content = "Kyllo! Setelah dia!",
  ui_story_5029_50290018_46_dialog_content = "Lihat!",
  ui_story_5029_50290019_1_dialog_content = "Berhenti sekarang juga!",
  ui_story_5029_50290019_2_dialog_content = "...",
  ui_story_5029_50290019_3_dialog_content = "Dengar, aku memberimu kesempatan untuk menyerahkan diri.",
  ui_story_5029_50290019_4_dialog_content = "Jika aku menangkapmu, semuanya akan berbeda.",
  ui_story_5029_50290019_5_dialog_content = "Huff.. sip..",
  ui_story_5029_50290019_6_dialog_content = "Orang itu tidak berhenti. Dia naik gunung.",
  ui_story_5029_50290019_7_dialog_content = "Saya benar-benar tidak ingin mengarahkan tombak saya ke warga sipil ...",
  ui_story_5029_50290019_8_dialog_content = "Aku sudah memperingatkannya, tapi sekarang, dia memaksa tanganku...",
  ui_story_5029_50290019_9_dialog_content = "Carleen, kami tampaknya tidak mengambil senjata apa pun ketika kami keluar.",
  ui_story_5029_50290019_10_dialog_content = "Sst! Dia tidak tahu itu!",
  ui_story_5029_50290019_11_dialog_content = "(Eh? Dia pembohong yang buruk ketika kami kembali ke hotel...)",
  ui_story_5029_50290019_12_dialog_content = "(Dan sekarang, dalam pertarungan, dia sangat mahir menipu musuh?)",
  ui_story_5029_50290019_13_dialog_content = "(Sesuatu akan datang langsung pada Carleen?!)",
  ui_story_5029_50290019_14_dialog_content = "Carleen, awas!",
  ui_story_5029_50290019_15_dialog_content = "<color=#828282>Bum!</color>",
  ui_story_5029_50290019_16_dialog_content = "PlayerName, bisakah kamu mendengarku?",
  ui_story_5029_50290019_17_dialog_content = "Ya...",
  ui_story_5029_50290019_18_dialog_content = "A-Apakah kamu baik-baik saja?",
  ui_story_5029_50290019_19_dialog_content = "Apakah kamu bodoh, PlayerName?!",
  ui_story_5029_50290019_20_dialog_content = "Anda menerima pukulan untuk saya, namun sekarang Anda bertanya apakah saya baik-baik saja?",
  ui_story_5029_50290019_21_dialog_content = "Aku takut... itu akan mengacaukan rok barumu dan membuatnya tidak cantik lagi...",
  ui_story_5029_50290019_22_dialog_content = "Anda khawatir tentang rok pada saat itu?!",
  ui_story_5029_50290019_23_dialog_content = "Di mana itu memukul Anda? Tunjukkan kepadaku!",
  ui_story_5029_50290019_24_dialog_content = "Saya baik-baik saja. Aku hanya perlu istirahat sebentar.",
  ui_story_5029_50290019_25_dialog_content = "Anda hampir jatuh pingsan! Anda tidak BAIK!",
  ui_story_5029_50290019_26_dialog_content = "Semakin kau seperti ini, semakin aku menyalahkan diriku sendiri...",
  ui_story_5029_50290019_27_dialog_content = "Saya tidak ingin melihat rekan setim saya terluka karena saya ... Saya tidak pernah ingin melihat itu!",
  ui_story_5029_50290019_28_dialog_content = "Carleen, dulu saya adalah orang yang selalu membutuhkan tabungan.",
  ui_story_5029_50290019_29_dialog_content = "Itu adalah kesempatanku untuk menjadi seorang ksatria, dan aku harus menyelamatkan seorang putri sejati.",
  ui_story_5029_50290019_30_dialog_content = "Aku sebenarnya... senang tentang itu.",
  ui_story_5029_50290019_31_dialog_content = "Pukulan itu benar-benar membuatmu bodoh...",
  ui_story_5029_50290019_32_dialog_content = "Lihat. Apa itu?",
  ui_story_5029_50290019_33_dialog_content = "Sebuah kotak perak? Kotak perak laird?",
  ui_story_5029_50290019_34_dialog_content = "Pencuri itu pasti membuangnya untuk mengulur waktu untuk menjauh dari kita.",
  ui_story_5029_50290019_35_dialog_content = "Dia seharusnya masih ada. Ayo tangkap dia dan... Aduh, aduh, aduh!",
  ui_story_5029_50290019_36_dialog_content = "Dengan serius? Anda tidak dalam kondisi untuk mengejarnya.",
  ui_story_5029_50290019_37_dialog_content = "Anda mungkin tidak merasakannya sekarang, tetapi bagaimana jika Anda menderita luka dalam?",
  ui_story_5029_50290019_38_dialog_content = "Saya tidak ingin Caelestite terakhir mengalami kecelakaan karena saya.",
  ui_story_5029_50290019_39_dialog_content = "Saya tidak akan pernah dimaafkan oleh dunia untuk semua generasi yang akan datang jika itu terjadi.",
  ui_story_5029_50290019_40_dialog_content = "Itu tidak akan berhasil... Aku harus membawamu turun gunung untuk menemui dokter.",
  ui_story_5029_50290019_41_dialog_content = "Aku…",
  ui_story_5029_50290019_42_option_content = "Menarik",
  ui_story_5029_50290019_43_dialog_content = "Laird memang mengatakan dia hanya ingin kotak perak itu kembali.",
  ui_story_5029_50290019_44_dialog_content = "Kami tidak tahu siapa pencurinya. Yang bisa kita harapkan hanyalah bahwa itu hanya kejahatan nafsu, dan dia tidak akan pernah melakukannya lagi...",
  ui_story_5029_50290019_45_dialog_content = "Tetapi siapa pun yang mencuri sekali kemungkinan besar akan mencuri untuk kedua dan ketiga kalinya.",
  ui_story_5029_50290019_46_dialog_content = "Lalu mengapa Anda masih bersikeras bahwa saya pergi dengan Anda untuk menemui dokter?",
  ui_story_5029_50290019_47_dialog_content = "Jalan menuju keadilan seharusnya tidak diaspal dengan kehidupan rekan tim saya.",
  ui_story_5029_50290019_48_dialog_content = "Aku hanya tidak ingin terjadi sesuatu padamu. Polos dan sederhana.",
  ui_story_5029_50290019_49_dialog_content = "Jadi aku hanya rekan satu tim untukmu...?",
  ui_story_5029_50290019_50_dialog_content = "Apa katamu?",
  ui_story_5029_50290019_51_dialog_content = "B-bukan apa-apa!",
  ui_story_5029_50290019_52_dialog_content = "Terima kasih, Yang Mulia, dan Nama Pemain!",
  ui_story_5029_50290019_53_dialog_content = "Untuk mengembalikan apa yang hilang dalam waktu sesingkat itu.",
  ui_story_5029_50290019_54_dialog_content = "Anda membawa kehormatan bagi nama Anda sebagai Putri Lumopolis dan Kapten Penjaga Lumopolis, Yang Mulia!",
  ui_story_5029_50290019_55_dialog_content = "Lumopolis tidak diragukan lagi akan menjadi tempat yang makmur dan aman di bawah pemerintahan Anda!",
  ui_story_5029_50290019_56_dialog_content = "Jangan menyebutkannya. Itu hanya apa yang harus saya lakukan.",
  ui_story_5029_50290019_57_dialog_content = "Laird tampaknya pria yang baik. Aku hanya tidak menyangka dia bisa begitu pandai mengucapkan kata-kata pujian...",
  ui_story_5029_50290019_58_dialog_content = "Maksudku, PlayerName terluka...",
  ui_story_5029_50290019_59_dialog_content = "Dokter memberi saya tagihan kesehatan yang bersih. Saya baik-baik saja.",
  ui_story_5029_50290019_60_dialog_content = "Hei, apakah itu kotak perak yang hilang di sebelahnya?",
  ui_story_5029_50290019_61_dialog_content = "Ini terlihat agak biasa.",
  ui_story_5029_50290019_62_dialog_content = "Hanya jika saya beruntung bertemu pelakunya di jalanan.",
  ui_story_5029_50290019_63_dialog_content = "Saya juga berterima kasih atas kerja keras Anda, Detektif Vice dan Fia.",
  ui_story_5029_50290019_64_dialog_content = "Saya memberi semua orang bayaran serta pesta khusus Harbour City.",
  ui_story_5029_50290019_65_dialog_content = "Silakan, lewat sini.",
  ui_story_5029_50290019_66_option_content = "Mengejar",
  ui_story_5029_50290019_67_dialog_content = "Meskipun laird memang mengatakan, dia hanya ingin kotak perak itu kembali...",
  ui_story_5029_50290019_68_dialog_content = "Aku masih berharap kita bisa menangkap pencurinya.",
  ui_story_5029_50290019_69_dialog_content = "Carleen, Saya tahu Anda menyukai Lumopolis dan semua yang ada di yurisdiksi Lumopolis.",
  ui_story_5029_50290019_70_dialog_content = "Saya yakin Anda tidak ingin melepaskan penjahat di luar sana.",
  ui_story_5029_50290019_71_dialog_content = "Tapi, kamu...",
  ui_story_5029_50290019_72_dialog_content = "Saya seorang Caelestit, dan saya telah berhasil melewati perang dengan Eclipsites. Kenapa aku membiarkan luka kecil ini mengalahkanku?",
  ui_story_5029_50290019_73_dialog_content = "Jangan khawatir. aku tangguh.",
  ui_story_5029_50290019_74_dialog_content = "... Baiklah, Nama Pemain.",
  ui_story_5029_50290019_75_dialog_content = "Dapatkah Anda merasakan di mana dia?",
  ui_story_5029_50290019_76_dialog_content = "Iya!",
  ui_story_5029_50290020_1_dialog_content = "Puff, huff... Kita harus berada di hutan belantara di luar Harbour City sekarang.",
  ui_story_5029_50290020_2_dialog_content = "Kami sudah berlari begitu lama. Apa dia belum lelah?",
  ui_story_5029_50290020_3_dialog_content = "Dia tepat di depan! Aku hampir bisa membuatnya keluar!",
  ui_story_5029_50290020_4_dialog_content = "Tapi sepertinya masih ada jarak yang sangat jauh... antara dia dan kita.",
  ui_story_5029_50290020_5_dialog_content = "Hanya jika saya membawa busur saya...",
  ui_story_5029_50290020_6_dialog_content = "Saya tidak berpikir kami akan bertemu dengan pencuri di tengah penyelidikan ...",
  ui_story_5029_50290020_7_dialog_content = "Puff, huff... Orang itu pasti bisa lari... Bagaimanapun juga, kita mungkin tidak bisa menangkapnya.",
  ui_story_5029_50290020_8_dialog_content = "...",
  ui_story_5029_50290020_9_dialog_content = "Vice? K-Kenapa kamu berhenti?",
  ui_story_5029_50290020_10_dialog_content = "Ini satu-satunya yang tersisa untuk dicoba.",
  ui_story_5029_50290020_11_dialog_content = "Mengapa Anda mengangkat batu di atas kepala Anda dan memelototi saya?",
  ui_story_5029_50290020_12_dialog_content = "M-Mengancamku tidak akan membuatku berlari lebih cepat...",
  ui_story_5029_50290020_13_dialog_content = "Saya ingat bahwa ikat kepala Anda elastis. Bolehkah aku meminjamnya sebentar?",
  ui_story_5029_50290020_14_dialog_content = "Anda ingin membuat busur dari itu?",
  ui_story_5029_50290020_15_dialog_content = "Itu tidak mungkin... Tapi aku mungkin bisa mengayunkannya seperti gendongan.",
  ui_story_5029_50290020_16_dialog_content = "Aku mengerti... Ini dia!",
  ui_story_5029_50290020_17_dialog_content = "Terima kasih. Sekarang atau tidak pernah.",
  ui_story_5029_50290020_18_dialog_content = "Tracking Strike!",
  ui_story_5029_50290020_19_dialog_content = "Tepat sasaran... Dia jatuh!",
  ui_story_5029_50290020_20_dialog_content = "Tidak pernah berpikir trik yang saya pelajari di kelas saat itu akan berguna.",
  ui_story_5029_50290020_21_dialog_content = "Kamu luar biasa, Vice!",
  ui_story_5029_50290020_22_dialog_content = "Tapi itu belum berakhir. Kita harus mengejarnya selagi bisa!",
  ui_story_5029_50290020_23_dialog_content = "Ya!",
  ui_story_5029_50290020_24_dialog_content = "Kami hampir sampai!",
  ui_story_5029_50290020_25_dialog_content = "...",
  ui_story_5029_50290020_26_dialog_content = "Oh-oh, pencurinya sudah bangun!",
  ui_story_5029_50290020_27_dialog_content = "Apa dia baru saja membuang sesuatu?",
  ui_story_5029_50290020_28_dialog_content = "Apakah itu kotak perak?!",
  ui_story_5029_50290020_29_dialog_content = "Itu bergulir menuruni lereng ...",
  ui_story_5029_50290020_30_dialog_content = "Hampir tidak mungkin untuk menemukan jika itu mencapai bagian bawah ...",
  ui_story_5029_50290020_31_dialog_content = "Aku akan pergi mendapatkannya!",
  ui_story_5029_50290020_32_dialog_content = "Vice? Hati-Hati!",
  ui_story_5029_50290020_33_dialog_content = "*Batuk-batuk*",
  ui_story_5029_50290020_34_dialog_content = "Kau baik-baik saja, Vice?",
  ui_story_5029_50290020_35_dialog_content = "Aku baik-baik saja.",
  ui_story_5029_50290020_36_dialog_content = "Mengapa Anda mengisi di sana tanpa berbicara dengan saya?",
  ui_story_5029_50290020_37_dialog_content = "Itu hal berbahaya yang kamu lakukan!",
  ui_story_5029_50290020_38_dialog_content = "Jangan meremehkan saya, PlayerName.",
  ui_story_5029_50290020_39_dialog_content = "*Batuk*... Maksudku, bukankah aku membuatnya utuh kembali?",
  ui_story_5029_50290020_40_dialog_content = "Saya pikir Anda jatuh untuk selamanya ...",
  ui_story_5029_50290020_41_dialog_content = "Jangan khawatir.",
  ui_story_5029_50290020_42_dialog_content = "Saya mendapatkan pelatihan Illumina selama bertahun-tahun. Bukit ini bukan apa-apa.",
  ui_story_5029_50290020_43_dialog_content = "Dan periksa ini!",
  ui_story_5029_50290020_44_dialog_content = "Kami akhirnya mendapatkan... *Batuk*",
  ui_story_5029_50290020_45_dialog_content = "Kamu pasti terluka karena batuk seperti ini.",
  ui_story_5029_50290020_46_dialog_content = "Aku baik-baik saja, sungguh.",
  ui_story_5029_50290020_47_dialog_content = "Pencuri itu mungkin tidak pergi jauh.",
  ui_story_5029_50290020_48_dialog_content = "Ayo tangkap dia!",
  ui_story_5029_50290020_49_dialog_content = "Aduh...",
  ui_story_5029_50290020_50_dialog_content = "Vice…",
  ui_story_5029_50290020_51_dialog_content = "Pergelangan kaki Anda terlihat merah... Apakah bengkak?",
  ui_story_5029_50290020_52_dialog_content = "Jangan memaksakan diri dan bawakan Anda dokter.",
  ui_story_5029_50290020_53_dialog_content = "Tidak, kita sudah hampir menangkap pencurinya!",
  ui_story_5029_50290020_54_dialog_content = "Saya tidak akan mendukung ini, PlayerName.",
  ui_story_5029_50290020_55_dialog_content = "Apakah Anda tidak ingin membawanya sebanyak yang saya lakukan?",
  ui_story_5029_50290020_56_option_content = "Meyakinkan Vice",
  ui_story_5029_50290020_57_dialog_content = "Anda terus mengatakan bahwa Anda baik-baik saja, tapi saya bukan anak kecil.",
  ui_story_5029_50290020_58_dialog_content = "Aku tahu kau terluka di musim gugur.",
  ui_story_5029_50290020_59_dialog_content = "Aku akui aku menginginkan pelakunya, tapi aku tidak ingin lukamu semakin parah.",
  ui_story_5029_50290020_60_dialog_content = "PlayerName…",
  ui_story_5029_50290020_61_dialog_content = "Laird berkata yang perlu kami lakukan hanyalah menemukan kotak perak itu.",
  ui_story_5029_50290020_62_dialog_content = "Bagian itu sudah selesai, jadi jangan memaksakan diri, oke?",
  ui_story_5029_50290020_63_dialog_content = "Baiklah, aku akan mendengarkanmu kali ini.",
  ui_story_5029_50290020_64_dialog_content = "Terima kasih, Nama Pemain, Nona Vice!",
  ui_story_5029_50290020_65_dialog_content = "Untuk mengembalikan apa yang hilang dalam waktu sesingkat itu.",
  ui_story_5029_50290020_66_dialog_content = "Saya mendengar Nona Vice adalah Kapten Tim Ekspedisi Illumina?",
  ui_story_5029_50290020_67_dialog_content = "Tidak heran Anda melakukan pekerjaan detektif yang hebat! Merupakan kehormatan bagi saya untuk mendapatkan bantuan Anda!",
  ui_story_5029_50290020_68_dialog_content = "Saya sangat menghargai Anda memberi saya dokter yang hebat juga.",
  ui_story_5029_50290020_69_dialog_content = "Tapi bagaimana Anda bisa terluka begitu parah hanya dengan mengambil sebuah kotak?",
  ui_story_5029_50290020_70_dialog_content = "Hei, apakah itu kotak perak yang hilang di sebelahnya?",
  ui_story_5029_50290020_71_dialog_content = "Ini terlihat agak biasa.",
  ui_story_5029_50290020_72_dialog_content = "Saya juga sangat berterima kasih atas bantuan Putri Carleen.",
  ui_story_5029_50290020_73_dialog_content = "Silakan menikmati masa tinggal Anda di Harbour City!",
  ui_story_5029_50290020_74_dialog_content = "Jangan lupakan aku, Fia!",
  ui_story_5029_50290020_75_dialog_content = "Oh tentu. Kerja bagus, Detektif Fia.",
  ui_story_5029_50290020_76_dialog_content = "Saya memberi semua orang bayaran serta pesta khusus Harbour City.",
  ui_story_5029_50290020_77_dialog_content = "Silakan, lewat sini.",
  ui_story_5029_50290020_78_option_content = "Setuju dengan Vice",
  ui_story_5029_50290020_79_dialog_content = "Ya, saya ingin mendapatkan pencuri itu.",
  ui_story_5029_50290020_80_dialog_content = "Tapi aku juga tidak bisa mengabaikan lukamu.",
  ui_story_5029_50290020_81_dialog_content = "Ada apa denganmu hari ini?",
  ui_story_5029_50290020_82_dialog_content = "Sebanyak yang telah kita lalui, kapan kau melihatku kembali?",
  ui_story_5029_50290020_83_dialog_content = "Tidak pernah. Anda selalu bersemangat.",
  ui_story_5029_50290020_84_dialog_content = "Percayalah, Nama Pemain!",
  ui_story_5029_50290020_85_dialog_content = "Luka daging ini bukanlah apa-apa.",
  ui_story_5029_50290020_86_dialog_content = "Belum lagi pelakunya mungkin melakukan kejahatan lain ...",
  ui_story_5029_50290020_87_dialog_content = "Kami satu-satunya yang bisa membawanya masuk.",
  ui_story_5029_50290020_88_dialog_content = "Ya!",
  ui_story_5029_50290021_1_dialog_content = "Bagus, Kylo!",
  ui_story_5029_50290021_2_dialog_content = "Terima kasih kepada Kyllo yang mengintai lorong ke sisi lain gunung.",
  ui_story_5029_50290021_3_dialog_content = "Atau aku tidak akan pernah bisa mengikuti pelakunya.",
  ui_story_5029_50290021_4_dialog_content = "Tapi dia bergerak jauh lebih cepat dari kita di jalan-jalan kota.",
  ui_story_5029_50290021_5_dialog_content = "Bukankah kita masih memiliki Kyllo?",
  ui_story_5029_50290021_6_dialog_content = "lihat...",
  ui_story_5029_50290021_7_dialog_content = "Kami mengandalkanmu, Kyllo!",
  ui_story_5029_50290021_8_dialog_content = "Pergi tangkap pelakunya!",
  ui_story_5029_50290021_9_dialog_content = "halo?",
  ui_story_5029_50290021_10_dialog_content = "Ada apa, Kyu? Kenapa kamu berhenti?",
  ui_story_5029_50290021_11_dialog_content = "Pencuri itu ada di sana!",
  ui_story_5029_50290021_12_dialog_content = "lihat...",
  ui_story_5029_50290021_13_dialog_content = "Jalanan menjadi terlalu ramai bagi Kyllo untuk mengetahui di mana dia berada.",
  ui_story_5029_50290021_14_dialog_content = "Tidak apa-apa. Aku membawa suar.",
  ui_story_5029_50290021_15_dialog_content = "Saya hanya akan menandai orang itu, dan Anda menghentikannya pergi dengan kotak perak.",
  ui_story_5029_50290021_16_dialog_content = "Mengerti, Kylo?",
  ui_story_5029_50290021_17_dialog_content = "Lihat!",
  ui_story_5029_50290021_18_dialog_content = "Serangan Sinyal Fatal Fia!",
  ui_story_5029_50290021_19_dialog_content = "…?",
  ui_story_5029_50290021_20_dialog_content = "Geram... Lo!",
  ui_story_5029_50290021_21_dialog_content = "Itu dia, Kyllo, gigit tangannya!",
  ui_story_5029_50290021_22_dialog_content = "halo halo!",
  ui_story_5029_50290021_23_dialog_content = "!",
  ui_story_5029_50290021_24_dialog_content = "Aku tidak pernah tahu kau begitu bodoh, Fia.",
  ui_story_5029_50290021_25_dialog_content = "Sejujurnya, saya juga tidak.",
  ui_story_5029_50290021_26_dialog_content = "<color=#828282>Ledakan!</color>",
  ui_story_5029_50290021_27_dialog_content = "Apa... Kenapa kau memecat yang lain?",
  ui_story_5029_50290021_28_dialog_content = "Ups... Sekarang, kemana perginya yang satu itu?",
  ui_story_5029_50290021_29_dialog_content = "Abaikan tembakan kedua, Kyllo!",
  ui_story_5029_50290021_30_dialog_content = "Pertahankan pegangan Anda, jangan biarkan dia pergi dengan kotak itu!",
  ui_story_5029_50290021_31_dialog_content = "…!",
  ui_story_5029_50290021_32_dialog_content = "Pelakunya tersandung!",
  ui_story_5029_50290021_33_dialog_content = "Kyllo dan kotaknya ada di tanah...",
  ui_story_5029_50290021_34_dialog_content = "Apakah kamu baik-baik saja, Kylo?",
  ui_story_5029_50290021_35_dialog_content = "Lihat!",
  ui_story_5029_50290021_36_dialog_content = "Pekerjaan yang sangat baik melindungi kotak!",
  ui_story_5029_50290021_37_dialog_content = "Anda melakukan pekerjaan yang luar biasa hari ini!",
  ui_story_5029_50290021_38_dialog_content = "Kembalikan saja kotaknya dan kami akan dibayar!",
  ui_story_5029_50290021_39_dialog_content = "Oh tidak, pelakunya sedang menuju pelabuhan.",
  ui_story_5029_50290021_40_dialog_content = "Anda tidak bisa pergi dari saya!",
  ui_story_5029_50290021_41_dialog_content = "Ayo tangkap dia!",
  ui_story_5029_50290021_42_dialog_content = "Berhenti!",
  ui_story_5029_50290021_43_dialog_content = "Apa? Maksudmu aku?",
  ui_story_5029_50290021_44_dialog_content = "Kau yang menembak, kan? Cukup ceroboh di sana ...",
  ui_story_5029_50290021_45_dialog_content = "Sekarang beri tahu saya siapa yang mengirim Anda untuk menyerang saya!",
  ui_story_5029_50290021_46_dialog_content = "Oh-oh, tembakan kedua mengenai penjaga...",
  ui_story_5029_50290021_47_dialog_content = "Maksud Anda, Anda melepaskan lebih dari satu tembakan?",
  ui_story_5029_50290021_48_dialog_content = "Sekarang Anda mengganggu kedamaian di Harbour City. Ikut denganku!",
  ui_story_5029_50290021_49_dialog_content = "Uh, aku punya hal yang lebih penting untuk dilakukan sekarang daripada pergi bersamamu.",
  ui_story_5029_50290021_50_dialog_content = "Apakah Anda menolak penangkapan?",
  ui_story_5029_50290021_51_dialog_content = "Tunggu sebentar, saya pikir kita memiliki kesalahpahaman di sini.",
  ui_story_5029_50290021_52_dialog_content = "Apakah kamu saudaranya?",
  ui_story_5029_50290021_53_dialog_content = "Tidak, aku tidak punya saudara! Dia adalah binatang ajaib saya.",
  ui_story_5029_50290021_54_dialog_content = "Jadi, kaki tangan? Kalian semua ikut denganku!",
  ui_story_5029_50290021_55_dialog_content = "Ahem, kami memang bertindak tergesa-gesa, Fia...",
  ui_story_5029_50290021_56_dialog_content = "Tembakan kedua adalah kesalahan kami, jadi mengapa Anda tidak meminta maaf?",
  ui_story_5029_50290021_57_dialog_content = "Hmph.",
  ui_story_5029_50290021_58_dialog_content = "Fi!",
  ui_story_5029_50290021_59_dialog_content = "Baik... Aku kacau. Maaf.",
  ui_story_5029_50290021_60_dialog_content = "Permintaan maaf.",
  ui_story_5029_50290021_61_dialog_content = "Jika maaf berhasil, mengapa kita membutuhkan penjaga untuk menjaga ketertiban?",
  ui_story_5029_50290021_62_dialog_content = "Kita akan turun ke stasiun!",
  ui_story_5029_50290021_63_option_content = "Setuju untuk pergi dengan penjaga",
  ui_story_5029_50290021_64_dialog_content = "Baiklah, kita akan pergi.",
  ui_story_5029_50290021_65_dialog_content = "Apa yang kamu bicarakan, PlayerName? Bagaimana dengan pelakunya...",
  ui_story_5029_50290021_66_dialog_content = "Laird berkata yang perlu kami lakukan hanyalah menemukan kotak perak itu.",
  ui_story_5029_50290021_67_dialog_content = "Betapapun aku ingin menangkapnya, kita tidak bisa membicarakan jalan keluar dengan penjaga.",
  ui_story_5029_50290021_68_dialog_content = "Jadi jangan memperburuk keadaan.",
  ui_story_5029_50290021_69_dialog_content = "Baik, selama saya dibayar.",
  ui_story_5029_50290021_70_dialog_content = "Apa yang kamu bisikkan?",
  ui_story_5029_50290021_71_dialog_content = "Kami akan ikut denganmu, tapi kau harus membawa kami ke sarang.",
  ui_story_5029_50290021_72_dialog_content = "Laird tidak punya waktu untuk ini.",
  ui_story_5029_50290021_73_dialog_content = "Aku yakin laird akan menyelesaikan ini semua.",
  ui_story_5029_50290021_74_dialog_content = "Mereka adalah tamu saya dan saya akan bertanggung jawab atas apa yang mereka lakukan.",
  ui_story_5029_50290021_75_dialog_content = "Ini seharusnya cukup bagi Anda untuk membersihkan tanda suar, saya kira?",
  ui_story_5029_50290021_76_dialog_content = "Sangat! Terima kasih, tuanku!",
  ui_story_5029_50290021_77_dialog_content = "Terima kasih, PlayerName dan Nona Fia!",
  ui_story_5029_50290021_78_dialog_content = "Untuk mengembalikan apa yang hilang dalam waktu sesingkat itu.",
  ui_story_5029_50290021_79_dialog_content = "Kudengar Nona Fia juga seorang ahli ekstrozoologi?",
  ui_story_5029_50290021_80_dialog_content = "Saya sudah membaca buku tentang mereka, jadi kita harus bicara kapan-kapan!",
  ui_story_5029_50290021_81_dialog_content = "Hmm, saya tidak berpikir saya akan memiliki siswa ...",
  ui_story_5029_50290021_82_dialog_content = "Uh, kurasa bukan itu yang ada di pikiran laird, Fia.",
  ui_story_5029_50290021_83_dialog_content = "Bagaimanapun, itu kehormatan saya untuk mendapatkan bantuan Anda!",
  ui_story_5029_50290021_84_dialog_content = "Semuanya baik-baik saja!",
  ui_story_5029_50290021_85_dialog_content = "Tapi jika penjaga tidak menghentikan kami, kami akan membawa pelakunya kembali!",
  ui_story_5029_50290021_86_dialog_content = "Jangan bilang Fia menyiarkannya ke seluruh kota...",
  ui_story_5029_50290021_87_dialog_content = "Itu tidak akan lagi menjadi penyelidikan rahasia.",
  ui_story_5029_50290021_88_dialog_content = "Jangan khawatir. Meskipun orang-orang melihat pengejaran, mereka tidak tahu mengapa itu terjadi.",
  ui_story_5029_50290021_89_dialog_content = "Saya juga sangat berterima kasih untuk Putri Carleen dan bantuan Miss Vice.",
  ui_story_5029_50290021_90_dialog_content = "Silakan menikmati masa tinggal Anda di Harbour City!",
  ui_story_5029_50290021_91_dialog_content = "Saya memberi semua orang bayaran serta pesta khusus Harbour City.",
  ui_story_5029_50290021_92_dialog_content = "Silakan, lewat sini.",
  ui_story_5029_50290021_93_option_content = "Menolak untuk pergi dengan penjaga",
  ui_story_5029_50290021_94_dialog_content = "Maaf, tapi aku punya masalah yang lebih mendesak untuk ditangani, dan itu untuk laird.",
  ui_story_5029_50290021_95_dialog_content = "Harap mengerti bahwa jika Anda bersikeras untuk ikut campur ...",
  ui_story_5029_50290021_96_dialog_content = "Anda akan bertanggung jawab atas kegagalan kami dalam tugas.",
  ui_story_5029_50290021_97_dialog_content = "Anu…",
  ui_story_5029_50290021_98_dialog_content = "Apakah Anda punya bukti? Mengapa saya harus percaya Anda?",
  ui_story_5029_50290021_99_dialog_content = "Jika Anda tidak percaya kami, kita bisa pergi melihat sarang sekarang.",
  ui_story_5029_50290021_100_dialog_content = "Kemudian kita akan melihat apa yang dia katakan.",
  ui_story_5029_50290022_1_dialog_content = "Woah!",
  ui_story_5029_50290022_2_dialog_content = "Saya belum pernah melihat begitu banyak makanan sejak saya tiba di Harbour City!",
  ui_story_5029_50290022_3_dialog_content = "Kurasa laird tahu bagaimana memperlakukan tamunya.",
  ui_story_5029_50290022_4_dialog_content = "Aku kelaparan karena semua berlarian hari ini! Aku sedang menggali!",
  ui_story_5029_50290022_5_dialog_content = "Santai saja. Tidak ada yang melawanmu.",
  ui_story_5029_50290022_6_dialog_content = "Apakah seluruh peti Nightium ini untuk kita?",
  ui_story_5029_50290022_7_dialog_content = "Laird sangat murah hati!",
  ui_story_5029_50290022_8_dialog_content = "Karena kita semua mendapat bagian, bagaimana kita membaginya?",
  ui_story_5029_50290022_9_dialog_content = "Siapa yang paling banyak mengerjakan...",
  ui_story_5029_50290022_10_dialog_content = "Saya ingat Anda tidak menghitung kacang seperti ini ketika Anda masih di sekolah.",
  ui_story_5029_50290022_11_dialog_content = "Yah, salahkan hidup.",
  ui_story_5029_50290022_12_dialog_content = "Tidak semua orang bisa menjadi bangsawan kaya Lumopolis menunggu tangan dan kaki oleh orang lain.",
  ui_story_5029_50290022_13_dialog_content = "Dalam hal ini, Anda dapat melewatkan bagian saya.",
  ui_story_5029_50290022_14_dialog_content = "Apa, seseorang yang tidak menginginkan bagiannya? Aku akan mengambilnya!",
  ui_story_5029_50290022_15_dialog_content = "Saya dapat membeli sesuatu untuk Shira agar dia tidak mengeluh tentang saya!",
  ui_story_5029_50290022_16_dialog_content = "Bukankah lebih adil membagi porsi Carleen secara merata?",
  ui_story_5029_50290022_17_dialog_content = "Buka lebar-lebar, Kyllo!",
  ui_story_5029_50290022_18_dialog_content = "Fia, hewan peliharaan tidak diperbolehkan di atas meja.",
  ui_story_5029_50290022_19_dialog_content = "Kyllo adalah teman saya, bukan hewan peliharaan!",
  ui_story_5029_50290022_20_dialog_content = "(Rasanya tegang di antara mereka bertiga...)",
  ui_story_5029_50290022_21_dialog_content = "(Dan mengapa laird belum kembali? Dia mungkin bisa mengurangi ketegangan.)",
  ui_story_5029_50290022_22_dialog_content = "(Huh. Kalau saja aku tahu...)",
  ui_story_5029_50290022_23_dialog_content = "Tuan tanah...",
  ui_story_5029_50290022_24_dialog_content = "Apa?!",
  ui_story_5029_50290022_25_dialog_content = "(Fiuh, dia akhirnya kembali.)",
  ui_story_5029_50290022_26_dialog_content = "(Apa yang Zane bisikkan ke laird?)",
  ui_story_5029_50290022_27_dialog_content = "(Dan mengapa laird terlihat sangat tidak bahagia?)",
  ui_story_5029_50290022_28_dialog_content = "(Dia terengah-engah ...)",
  ui_story_5029_50290022_29_dialog_content = "(Mengapa saya mendapat firasat buruk?)",
  ui_story_5029_50290022_30_dialog_content = "(Apa yang sedang terjadi?)",
  ui_story_5029_50290022_31_dialog_content = "(Pelakunya?!)",
  ui_story_5029_50290022_32_dialog_content = "(Apakah pelakunya kembali lagi?)",
  ui_story_5029_50290022_33_dialog_content = "(Apa yang dia lakukan kali ini...?)",
  ui_story_5029_50290022_34_dialog_content = "<color=#828282>Ding...</color>",
  ui_story_5029_50290022_35_dialog_content = "Selamat datang kembali, tamu tersayang.",
  ui_story_5029_50290022_36_dialog_content = "Apa kau kecewa melihatku?",
  ui_story_5029_50290022_37_dialog_content = "Sekarang Anda tahu betapa sulitnya mengendalikan nasib Anda.",
  ui_story_5029_50290022_38_dialog_content = "Dan sepertinya kamu tidak puas dengan ending yang kamu tulis.",
  ui_story_5029_50290022_39_dialog_content = "Anda memiliki banyak pertanyaan? Ha ha ha...",
  ui_story_5029_50290022_40_dialog_content = "Bukan hanya dalam mimpi, tapi juga dalam kehidupan nyata.",
  ui_story_5029_50290022_41_dialog_content = "Itu memberi kita jawaban yang jelas.",
  ui_story_5029_50290022_42_dialog_content = "Tapi sekali lagi, bagaimana Anda bisa membuat cerita Anda sendiri jika Anda terus memberikan kendali kepada orang lain?",
  ui_story_5029_50290022_43_dialog_content = "Untungnya, kami masih punya waktu.",
  ui_story_5029_50290022_44_dialog_content = "Tetapi premisnya adalah Anda masih ingin mengubah bagaimana mimpi itu berakhir.",
  ui_story_5029_50290023_1_dialog_content = "Bagaimana menurutmu, Carleen?",
  ui_story_5029_50290023_2_dialog_content = "...",
  ui_story_5029_50290023_3_dialog_content = "Pria itu cukup licik untuk tidak meninggalkan jejak.",
  ui_story_5029_50290023_4_dialog_content = "Aku juga tidak bisa merasakan lokasinya.",
  ui_story_5029_50290023_5_dialog_content = "Tidak pantas posisiku sebagai Kapten Penjaga kehilangan jejak pelakunya.",
  ui_story_5029_50290023_6_dialog_content = "Ini adalah kesalahanku. Jika saya tidak merasa bodoh, kami sudah memilikinya sekarang.",
  ui_story_5029_50290023_7_dialog_content = "Jangan katakan itu. Anda mengambil pukulan untuk saya.",
  ui_story_5029_50290023_8_dialog_content = "Tapi aku bisa melakukannya dengan cara yang lebih baik!",
  ui_story_5029_50290023_9_dialog_content = "Dan pria itu adalah pelari tercepat yang pernah saya lihat.",
  ui_story_5029_50290023_10_dialog_content = "Dia mendaki bukit yang curam dengan begitu mudah. Bahkan Eclipsites tidak bisa menandingi itu.",
  ui_story_5029_50290023_11_dialog_content = "Berhentilah mencoba menghiburku, PlayerName.",
  ui_story_5029_50290023_12_dialog_content = "Aku tahu kamu cuma berusaha membuatku senang.",
  ui_story_5029_50290023_13_dialog_content = "Tapi apakah Anda menyadari?",
  ui_story_5029_50290023_14_dialog_content = "Persyaratan untuk menjadi seorang ksatria bukanlah berapa banyak pertempuran yang Anda pimpin dan lawan ...",
  ui_story_5029_50290023_15_dialog_content = "Tapi keberanian untuk mengambil tanggung jawab atas tindakan Anda, termasuk kegagalan.",
  ui_story_5029_50290023_16_dialog_content = "Carleen…",
  ui_story_5029_50290023_17_dialog_content = "Kenapa kau menatapku seperti itu?",
  ui_story_5029_50290023_18_dialog_content = "Sementara saya menyadari sejak lama bahwa Anda lebih tenang dan bertekad daripada kita semua di sekitar usia Anda ...",
  ui_story_5029_50290023_19_dialog_content = "Tapi saya pikir Anda telah tumbuh lebih dewasa akhir-akhir ini.",
  ui_story_5029_50290023_20_dialog_content = "Saya akan menganggap itu sebagai pujian. Terima kasih.",
  ui_story_5029_50290023_21_dialog_content = "Anda selalu tampak seperti Anda memegang kendali.",
  ui_story_5029_50290023_22_dialog_content = "Hah?",
  ui_story_5029_50290023_23_dialog_content = "Mungkin aku salah...",
  ui_story_5029_50290023_24_dialog_content = "Tapi rasanya seperti Anda memaksakan diri untuk menjadi seseorang yang sempurna dan tanpa cela.",
  ui_story_5029_50290023_25_dialog_content = "...",
  ui_story_5029_50290023_26_dialog_content = "Jadi saya tidak bisa menahan perasaan sedih semakin keras Anda mendorong diri sendiri.",
  ui_story_5029_50290023_27_dialog_content = "Sedih karena Anda tidak bisa riang seperti saya.",
  ui_story_5029_50290023_28_dialog_content = "Sedih karena Anda tidak bisa mengeluarkan emosi Anda.",
  ui_story_5029_50290023_29_dialog_content = "Sedih karena sudah berbuat banyak, namun masih diolok-olok karena terlindung dan dimanjakan.",
  ui_story_5029_50290023_30_dialog_content = "...",
  ui_story_5029_50290023_31_dialog_content = "Hehe... Hahaha!",
  ui_story_5029_50290023_32_dialog_content = "Mengapa kamu tertawa?",
  ui_story_5029_50290023_33_dialog_content = "Maaf, saya juga tidak tahu kenapa.",
  ui_story_5029_50290023_34_dialog_content = "Tidak ada yang pernah mengatakan itu kepada saya sebelumnya, jadi saya kehilangan jawaban.",
  ui_story_5029_50290023_35_dialog_content = "Yah, semoga kau tidak keberatan aku memuntahkan semua omong kosong itu...",
  ui_story_5029_50290023_36_dialog_content = "Saya mungkin masih merasakan efek bel berbunyi.",
  ui_story_5029_50290023_37_dialog_content = "Kita harus fokus pada apa yang harus dikatakan pada laird.",
  ui_story_5029_50290023_38_dialog_content = "Ini tidak seperti kita tangan kosong. Kami mendapatkan kotak itu kembali.",
  ui_story_5029_50290023_39_dialog_content = "Belum lagi kami secara tidak sengaja menemukan harta karun lain.",
  ui_story_5029_50290023_40_dialog_content = "Harta karun lainnya?",
  ui_story_5029_50290023_41_dialog_content = "Cari, Nama Pemain.",
  ui_story_5029_50290023_42_dialog_content = "Hah?",
  ui_story_5029_50290023_43_dialog_content = "Lihat teras yang ditinggalkan di puncak gunung?",
  ui_story_5029_50290023_44_dialog_content = "Anda dapat melihat seluruh cakrawala Harbour City di malam hari.",
  ui_story_5029_50290023_45_dialog_content = "Kami berada di gunung di belakang Harbour City, kan?",
  ui_story_5029_50290023_46_dialog_content = "Tidak heran itu adalah pemandangan yang luar biasa.",
  ui_story_5029_50290023_47_dialog_content = "Aku tidak percaya tidak ada yang memberitahuku tentang ini!",
  ui_story_5029_50290023_48_dialog_content = "(Carleen sebenarnya tampak sangat senang...)",
  ui_story_5029_50290023_49_dialog_content = "Untuk apa Anda berdiri di sana, PlayerName?",
  ui_story_5029_50290023_50_dialog_content = "Pemandangannya luar biasa di sini!",
  ui_story_5029_50290023_51_dialog_content = "Lautan sekarang tertidur. Satu-satunya cahaya berasal dari kedipan di Harbour City.",
  ui_story_5029_50290023_52_dialog_content = "Seluruh kota seperti manik-manik mutiara yang terhampar rata di Astra...",
  ui_story_5029_50290023_53_dialog_content = "Sangat menakjubkan...",
  ui_story_5029_50290023_54_option_content = "Terima kasih, Carleen.",
  ui_story_5029_50290023_55_dialog_content = "Sama. Itulah tepatnya yang ingin saya katakan kepada Anda.",
  ui_story_5029_50290023_56_dialog_content = "Tapi aku bahkan tidak mengatakan untuk apa aku berterima kasih padamu...",
  ui_story_5029_50290023_57_dialog_content = "Sama. Aku juga tidak mengatakan itu.",
  ui_story_5029_50290023_58_dialog_content = "Kenapa kamu tiba-tiba bertingkah tidak dewasa?",
  ui_story_5029_50290023_59_dialog_content = "Bukankah Anda baru saja mengkritik saya karena canggih?",
  ui_story_5029_50290023_60_option_content = "Apakah ada sesuatu yang ingin Anda katakan kepada saya?",
  ui_story_5029_50290023_61_dialog_content = "Ya...",
  ui_story_5029_50290023_62_dialog_content = "Anda tahu, cakrawala Lumopolis sama cantiknya dengan Harbour City.",
  ui_story_5029_50290023_63_dialog_content = "Tapi saya selalu dalam perjalanan menuju misi, jika belum menjalankan misi.",
  ui_story_5029_50290023_64_dialog_content = "Saya selalu merasa Lumopolis tidak akan berjalan tanpa saya.",
  ui_story_5029_50290023_65_dialog_content = "Semakin aku berpikir seperti itu, semakin keras aku menekan...",
  ui_story_5029_50290023_66_dialog_content = "Jadi saya tidak pernah berhenti untuk menikmati pemandangan spektakuler.",
  ui_story_5029_50290023_67_dialog_content = "Saat itu, saya tidak akan pernah menduga bahwa suatu hari, bertahun-tahun kemudian ...",
  ui_story_5029_50290023_68_dialog_content = "Saya tidak hanya tidak akan menyelesaikan misi, tetapi bahkan berhenti untuk mencium aroma mawar.",
  ui_story_5029_50290023_69_dialog_content = "Ya, Anda tidak akan pernah berpikir Anda akan melihat hari di masa lalu.",
  ui_story_5029_50290023_70_dialog_content = "Dia tidak akan pernah berharap dalam sejuta tahun untuk menemukan seorang Caelestite berdiri di sampingnya.",
  ui_story_5029_50290023_71_dialog_content = "Kedengarannya seperti saya merusak Anda atau sesuatu ...",
  ui_story_5029_50290023_72_dialog_content = "Tapi aku sangat senang itu kamu.",
  ui_story_5029_50290023_73_dialog_content = "Anggap itu sebagai jawaban saya untuk Anda.",
  ui_story_5029_50290023_74_dialog_content = "Jawaban apa?",
  ui_story_5029_50290023_75_dialog_content = "Apakah itu Caelestit yang berbeda yang berbicara denganku beberapa waktu yang lalu?",
  ui_story_5029_50290023_76_dialog_content = "Anu…",
  ui_story_5029_50290023_77_dialog_content = "Lihat, apakah itu sirkus?",
  ui_story_5029_50290023_78_dialog_content = "Dan di sana, bukankah itu hotel mewah yang kita selidiki hari ini?",
  ui_story_5029_50290023_79_dialog_content = "(Kelihatannya Carleen telah mengecewakan semua penjagaannya saat ini.)",
  ui_story_5029_50290023_80_dialog_content = "(Aku belum pernah melihatnya tersenyum dan bercanda dengan begitu bebas...)",
  ui_story_5029_50290023_81_dialog_content = "(Mungkin sisi anak ini akan tetap menjadi rahasia.)",
  ui_story_5029_50290023_82_dialog_content = "(Rahasia hanya antara aku dan dia.)",
  ui_story_5029_50290023_83_dialog_content = "<color=#828282>Ding...</color>",
  ui_story_5029_50290023_84_dialog_content = "Selamat datang kembali, tamu tersayang.",
  ui_story_5029_50290023_85_dialog_content = "Apa kau kecewa melihatku?",
  ui_story_5029_50290023_86_dialog_content = "Maaf, tapi saya tidak sengaja melihat rahasia Anda.",
  ui_story_5029_50290023_87_dialog_content = "Tapi tolong jangan kecewa.",
  ui_story_5029_50290023_88_dialog_content = "Mimpi hanya bisa terbentuk di atas fondasi yang didasarkan pada kenyataan.",
  ui_story_5029_50290023_89_dialog_content = "Itu berarti Anda dan dia cenderung mengalami situasi yang sama dalam hidup.",
  ui_story_5029_50290023_90_dialog_content = "Namun, tidak seperti dalam mimpi, tidak ada trik seperti itu dalam kenyataan.",
  ui_story_5029_50290023_91_dialog_content = "Pasti ada kesulitan menyesuaikan diri dengan hidup dalam fantasi yang saya buat.",
  ui_story_5029_50290023_92_dialog_content = "Ngomong-ngomong, apakah Anda puas dengan akhir ini?",
  ui_story_5029_50290023_93_dialog_content = "Tidakkah kamu merasa ada yang hilang?",
  ui_story_5029_50290023_94_dialog_content = "Yang ingin saya katakan adalah... kita masih punya waktu.",
  ui_story_5029_50290023_95_dialog_content = "Tetapi premisnya adalah Anda masih ingin mencari misteri dan jawaban dalam mimpi.",
  ui_story_5029_50290024_1_dialog_content = "Ketemu!",
  ui_story_5029_50290024_2_dialog_content = "Dia bersembunyi di semak-semak di sana...",
  ui_story_5029_50290024_3_dialog_content = "Hah?",
  ui_story_5029_50290024_4_dialog_content = "Lihat dari dekat. Bajunya terlihat! Aku akan mendapatkan dia!",
  ui_story_5029_50290024_5_dialog_content = "Tunggu...",
  ui_story_5029_50290024_6_dialog_content = "Tidak bisa membiarkan dia pergi lagi.",
  ui_story_5029_50290024_7_dialog_content = "Tracking Strike!",
  ui_story_5029_50290024_8_dialog_content = "<color=#828282>Duaar!</color>",
  ui_story_5029_50290024_9_dialog_content = "Ups...",
  ui_story_5029_50290024_10_dialog_content = "Vice!",
  ui_story_5029_50290024_11_dialog_content = "Maaf, Nama Pemain...",
  ui_story_5029_50290024_12_dialog_content = "Mengapa permintaan maaf?",
  ui_story_5029_50290024_13_dialog_content = "Saya telah berpikir, dan saya merasa kadang-kadang saya sangat ceroboh, selalu berusaha untuk menyelesaikan tugas secepat yang saya bisa...",
  ui_story_5029_50290024_14_dialog_content = "Itu sebabnya saya sering mengabaikan ancaman di sekitar saya.",
  ui_story_5029_50290024_15_dialog_content = "Sama seperti beberapa detik yang lalu.",
  ui_story_5029_50290024_16_dialog_content = "Aku menyeretmu ke boondocks bersamaku untuk mengejar pelakunya tanpa berpikir.",
  ui_story_5029_50290024_17_dialog_content = "Hanya untuk jatuh ke dalam perangkapnya.",
  ui_story_5029_50290024_18_dialog_content = "Tidak hanya pergelangan kaki saya yang terkilir, tetapi Anda juga harus menggendong saya kembali.",
  ui_story_5029_50290024_19_dialog_content = "Jadi, aku minta maaf!",
  ui_story_5029_50290024_20_dialog_content = "Huff... Tidak apa-apa, Vice.",
  ui_story_5029_50290024_21_dialog_content = "Kami membuat keputusan untuk mengejarnya bersama. Ini bukan semua salahmu.",
  ui_story_5029_50290024_22_dialog_content = "Dan akulah yang membawamu ke jebakan...",
  ui_story_5029_50290024_23_dialog_content = "Jadi jika ada yang harus meminta maaf, itu aku.",
  ui_story_5029_50290024_24_dialog_content = "Tidak perlu menghiburku, PlayerName.",
  ui_story_5029_50290024_25_dialog_content = "Aku tahu aku kacau. Makanya pelakunya tidak kami tangkap.",
  ui_story_5029_50290024_26_dialog_content = "Apakah kamu ingat?",
  ui_story_5029_50290024_27_dialog_content = "Jika Anda tidak mengacaukan dan membuat lubang di Soroz...",
  ui_story_5029_50290024_28_dialog_content = "Aku tidak akan pernah bertemu denganmu, apalagi keluar dari bawah tanah.",
  ui_story_5029_50290024_29_dialog_content = "Itu berbeda.",
  ui_story_5029_50290024_30_dialog_content = "Saya sudah memeriksa dengan seksama sebelum ...",
  ui_story_5029_50290024_31_dialog_content = "Tahan, jadi Anda selalu merasa itu berantakan?",
  ui_story_5029_50290024_32_dialog_content = "Bukan?",
  ui_story_5029_50290024_33_dialog_content = "Anda telah mengejek saya di kepala Anda selama ini!",
  ui_story_5029_50290024_34_dialog_content = "Hei, santai saja di tengkorakku!",
  ui_story_5029_50290024_35_dialog_content = "Maaf... Apa aku menyakitimu?",
  ui_story_5029_50290024_36_dialog_content = "Tidak juga, tapi aku mulai lelah.",
  ui_story_5029_50290024_37_dialog_content = "Letakkan saja aku di rerumputan di sana.",
  ui_story_5029_50290024_38_dialog_content = "Ya. Hati-hati dengan pergelangan kaki Anda ...",
  ui_story_5029_50290024_39_dialog_content = "Fiuh. Ini adalah hari yang panjang dan berat. Sekarang saya bisa istirahat sebentar.",
  ui_story_5029_50290024_40_dialog_content = "Apakah saya terlalu berat?",
  ui_story_5029_50290024_41_dialog_content = "Tidak sama sekali, hanya saja...",
  ui_story_5029_50290024_42_dialog_content = "Hanya apa?",
  ui_story_5029_50290024_43_dialog_content = "Itu terlalu jauh dari rumah.",
  ui_story_5029_50290024_44_dialog_content = "Saya pikir Anda akan mengolok-olok saya lagi.",
  ui_story_5029_50290024_45_dialog_content = "Vice.",
  ui_story_5029_50290024_46_dialog_content = "Ya?",
  ui_story_5029_50290024_47_dialog_content = "Aku tidak akan pernah mengolok-olok Anda.",
  ui_story_5029_50290024_48_dialog_content = "...",
  ui_story_5029_50290024_49_dialog_content = "Anda membawa saya keluar dari bawah tanah dan mendorong saya untuk bergerak maju.",
  ui_story_5029_50290024_50_dialog_content = "Tanpa Anda, saya tidak akan pernah mengenal begitu banyak orang dan melihat begitu banyak pemandangan.",
  ui_story_5029_50290024_51_dialog_content = "Oke, oke, aku paham, kok.",
  ui_story_5029_50290024_52_dialog_content = "Anda sudah banyak menyebutkan itu. Mengapa mengangkatnya lagi?",
  ui_story_5029_50290024_53_dialog_content = "Mungkin karena semua orang berpikir Anda bekerja keras dalam kasus ini demi uang.",
  ui_story_5029_50290024_54_dialog_content = "Tapi mereka lupa kau salah satu Illumina. Uang tidak berguna untuk diri sendiri.",
  ui_story_5029_50290024_55_dialog_content = "Anda ingin uang itu untuk melengkapi pengeluaran Colossus, bukan?",
  ui_story_5029_50290024_56_dialog_content = "Anda melihat melalui itu ... Tidak apa-apa, dan kami adalah mitra!",
  ui_story_5029_50290024_57_dialog_content = "Itu bagian dari pekerjaan saya.",
  ui_story_5029_50290024_58_dialog_content = "Banyak yang terlintas di pikiranku saat aku menggendongmu.",
  ui_story_5029_50290024_59_dialog_content = "Anda selalu ada untuk menjemput saya, menawarkan dorongan, dan mendorong saya untuk bersandar pada teman-teman.",
  ui_story_5029_50290024_60_dialog_content = "Tapi aku tidak pernah menyadari...",
  ui_story_5029_50290024_61_dialog_content = "Sebenarnya, Vice, Anda tidak perlu memasang muka juga.",
  ui_story_5029_50290024_62_dialog_content = "Apa?",
  ui_story_5029_50290024_63_dialog_content = "Kamu bisa seperti hari ini...",
  ui_story_5029_50290024_64_dialog_content = "Bersandarlah pada temanmu dan bersandarlah padaku sesekali!",
  ui_story_5029_50290024_65_dialog_content = "PlayerName…",
  ui_story_5029_50290024_66_option_content = "Terima kasih untuk semua yang Anda lakukan!",
  ui_story_5029_50290024_67_dialog_content = "Karena Anda mengatakannya seperti itu, yang bisa saya katakan adalah...",
  ui_story_5029_50290024_68_dialog_content = "Sama-sama!",
  ui_story_5029_50290024_69_dialog_content = "Kurasa aku masih akan bersandar padamu di masa depan.",
  ui_story_5029_50290024_70_dialog_content = "Sama. Aku akan bersandar padamu juga!",
  ui_story_5029_50290024_71_dialog_content = "Ini bagus.",
  ui_story_5029_50290024_72_dialog_content = "Apa yang bagus?",
  ui_story_5029_50290024_73_dialog_content = "Matahari terbenam di sini.",
  ui_story_5029_50290024_74_dialog_content = "Andai kakiku tidak terluka.",
  ui_story_5029_50290024_75_option_content = "Kau baik-baik saja?",
  ui_story_5029_50290024_76_dialog_content = "Aku baik-baik saja...",
  ui_story_5029_50290024_77_dialog_content = "Aku hanya memikirkan semua yang terjadi hari ini.",
  ui_story_5029_50290024_78_dialog_content = "Mengingat setiap detail ketika kami memeriksa perpustakaan.",
  ui_story_5029_50290024_79_dialog_content = "Mengingat ketika kita melihat pertunjukan di teater.",
  ui_story_5029_50290024_80_dialog_content = "Mengingat betapa sibuknya kamu tanpa henti setelah aku terluka.",
  ui_story_5029_50290024_81_dialog_content = "Saya tidak pernah memperhatikan seberapa baik Anda menjaga seseorang sebelumnya.",
  ui_story_5029_50290024_82_dialog_content = "Anda benar-benar teman yang bisa diandalkan.",
  ui_story_5029_50290024_83_dialog_content = "Itu setara untuk kursus!",
  ui_story_5029_50290024_84_dialog_content = "Dan saya ingin menikmati momen ini...",
  ui_story_5029_50290024_85_dialog_content = "<color=#828282>Wuuss!</color>",
  ui_story_5029_50290024_86_dialog_content = "Rasakan semilir angin membelai rerumputan dan rambutku.",
  ui_story_5029_50290024_87_dialog_content = "Rasakan matahari terbenam melukis awan merah dan oranye.",
  ui_story_5029_50290024_88_dialog_content = "Rasakan kedamaian yang tenang hanya dengan kami berdua.",
  ui_story_5029_50290024_89_dialog_content = "Saya bahkan berpikir saya pasti bisa terbiasa dengan ini.",
  ui_story_5029_50290024_90_dialog_content = "Kedengarannya bagus, tapi...",
  ui_story_5029_50290024_91_dialog_content = "Anda ingin saya menggendong Anda di punggung saya lebih banyak, bukan?",
  ui_story_5029_50290024_92_dialog_content = "Dan inilah aku, mengira bola lampu menyala di kepalamu.",
  ui_story_5029_50290024_93_dialog_content = "Saya kira Anda masih tidak tahu bagaimana berbicara dengan gadis-gadis.",
  ui_story_5029_50290024_94_dialog_content = "Aku hanya akan tetap menonton matahari terbenam.",
  ui_story_5029_50290024_95_dialog_content = "Ehem, aku hanya bercanda.",
  ui_story_5029_50290024_96_dialog_content = "Lalu bagaimana dengan ini?",
  ui_story_5029_50290024_97_dialog_content = "Setelah Anda pulih sepenuhnya, kami kembali ke sini dan menyaksikan matahari terbenam lagi.",
  ui_story_5029_50290024_98_dialog_content = "Anda berjanji!",
  ui_story_5029_50290024_99_dialog_content = "Siapa pun yang mengingkari akan menjadi cacing semangka!",
  ui_story_5029_50290024_100_dialog_content = "Itu bukan aku!",
  ui_story_5029_50290024_101_dialog_content = "(Vice mungkin terluka, tapi dia tampak lebih santai dan puas diri dari biasanya.)",
  ui_story_5029_50290024_102_dialog_content = "(Angin mulai menjadi dingin, menuju ke paru-paru.)",
  ui_story_5029_50290024_103_dialog_content = "(Seluruh dunia tiba-tiba terasa jauh bagi saya. Saya hanya bisa mendengar detak jantung saya.)",
  ui_story_5029_50290024_104_dialog_content = "(Saya sudah menantikannya ...)",
  ui_story_5029_50290024_105_dialog_content = "(Janji antara hanya aku dan dia.)",
  ui_story_5029_50290024_106_dialog_content = "<color=#828282>Ding...</color>",
  ui_story_5029_50290024_107_dialog_content = "Selamat datang kembali, tamu tersayang.",
  ui_story_5029_50290024_108_dialog_content = "Apa kau kecewa melihatku?",
  ui_story_5029_50290024_109_dialog_content = "Maaf, tapi saya tidak sengaja melihat rahasia Anda.",
  ui_story_5029_50290024_110_dialog_content = "Tapi tolong jangan kecewa.",
  ui_story_5029_50290024_111_dialog_content = "Mimpi hanya bisa terbentuk di atas fondasi yang didasarkan pada kenyataan.",
  ui_story_5029_50290024_112_dialog_content = "Itu berarti Anda dan dia cenderung mengalami situasi yang sama dalam hidup.",
  ui_story_5029_50290024_113_dialog_content = "Namun, tidak seperti dalam mimpi, tidak ada trik seperti itu dalam kenyataan.",
  ui_story_5029_50290024_114_dialog_content = "Pasti ada kesulitan menyesuaikan diri dengan hidup dalam fantasi yang saya buat.",
  ui_story_5029_50290024_115_dialog_content = "Omong-omong, apakah Anda puas dengan akhir ini?",
  ui_story_5029_50290024_116_dialog_content = "Tidakkah kamu merasa ada yang hilang?",
  ui_story_5029_50290024_117_dialog_content = "Yang ingin saya katakan adalah... kita masih punya waktu.",
  ui_story_5029_50290024_118_dialog_content = "Tetapi premisnya adalah Anda masih ingin mencari misteri dan jawaban dalam mimpi.",
  ui_story_5029_50290025_1_dialog_content = "Itu terlalu keren, PlayerName!",
  ui_story_5029_50290025_2_dialog_content = "Anda mendukung itu berarti berjaga-jaga dengan hanya beberapa kata!",
  ui_story_5029_50290025_3_dialog_content = "Yah, itu hanya suar sinyal yang tidak sengaja mengenainya.",
  ui_story_5029_50290025_4_dialog_content = "Itu tidak berbahaya, tapi dia masih ingin menerimaku!",
  ui_story_5029_50290025_5_dialog_content = "Apakah itu merugikan atau tidak, kita salah untuk memukul orang yang melihatnya.",
  ui_story_5029_50290025_6_dialog_content = "Anda cukup banyak menepisnya.",
  ui_story_5029_50290025_7_dialog_content = "Setelah kami menangkap pelakunya, Anda harus menawarkan permintaan maaf yang tulus.",
  ui_story_5029_50290025_8_dialog_content = "Kita akan membicarakannya setelah kita menangkap pelakunya.",
  ui_story_5029_50290025_9_dialog_content = "Jadi, bisakah kamu merasakan orang itu?",
  ui_story_5029_50290025_10_dialog_content = "Tidak. Terlalu banyak orang di sini.",
  ui_story_5029_50290025_11_dialog_content = "BENAR. Pelabuhan ini penuh dengan pengunjung di sini untuk perayaan.",
  ui_story_5029_50290025_12_dialog_content = "Pelakunya juga tahu itu, dan karena itulah dia lari ke sini.",
  ui_story_5029_50290025_13_dialog_content = "Bagaimanapun, biarkan aku mencoba lagi.",
  ui_story_5029_50290025_14_dialog_content = "Benar. Aku juga tidak bisa menunggu. Aku akan memeriksa kerumunan.",
  ui_story_5029_50290025_15_dialog_content = "Ikut denganku, Kyu!",
  ui_story_5029_50290025_16_dialog_content = "Apa yang terjadi, Kylo?",
  ui_story_5029_50290025_17_dialog_content = "Chow, chow, lo...",
  ui_story_5029_50290025_18_dialog_content = "Apa yang kamu makan, Kyu?",
  ui_story_5029_50290025_19_dialog_content = "No nom...",
  ui_story_5029_50290025_20_dialog_content = "Oh, betapa menjijikkan.",
  ui_story_5029_50290025_21_dialog_content = "Berhenti, Kyu. Itu bisa beracun!",
  ui_story_5029_50290025_22_dialog_content = "Hee, kamu tidak tahu banyak, kan?",
  ui_story_5029_50290025_23_dialog_content = "Ini adalah es krim rumput laut. Ini mungkin terlihat menjijikkan, tapi itu benar-benar memuaskan dahaga!",
  ui_story_5029_50290025_24_dialog_content = "Yah, tentu saja, saya tahu apa ini ...",
  ui_story_5029_50290025_25_dialog_content = "Hei, kemana perginya es krimku?",
  ui_story_5029_50290025_26_dialog_content = "Tunggu sebentar. Anjingmu memakan es krimku!",
  ui_story_5029_50290025_27_dialog_content = "Saya menabung waktu yang lama untuk itu! Anda harus membayar saya kembali!",
  ui_story_5029_50290025_28_dialog_content = "Eh, Kyllo memakan makananmu? Saya minta maaf...",
  ui_story_5029_50290025_X28_dialog_content = "Jangan minta maaf padaku. Saya akan memaafkan Anda jika Anda memberi saya cukup uang untuk membeli lima es krim.",
  ui_story_5029_50290025_X29_dialog_content = "Tapi saya tidak punya uang untuk saya ...",
  ui_story_5029_50290025_X30_dialog_content = "Kalau begitu, mengapa Anda tidak menjual anak anjing Anda?",
  ui_story_5029_50290025_X31_dialog_content = "Aku akan membayarmu kembali... tapi aku tidak akan menjual Kyllo! Juga, Kyllo bukan anak anjing.",
  ui_story_5029_50290025_29_dialog_content = "Jika itu bukan anjing, maka Anda!",
  ui_story_5029_50290025_30_dialog_content = "Aku tidak...",
  ui_story_5029_50290025_31_dialog_content = "Anda seorang doggy yang mencuri es krim orang lain!",
  ui_story_5029_50290025_32_dialog_content = "Ini kalung untukmu, Fia.",
  ui_story_5029_50290025_33_dialog_content = "Kami pikir Anda akan terlihat hebat di dalamnya!",
  ui_story_5029_50290025_34_dialog_content = "Betulkah? Terima kasih! Aku akan memakainya sekarang!",
  ui_story_5029_50290025_35_dialog_content = "Lihat, semuanya, Fia berjalan-jalan dengan kalung anjing!",
  ui_story_5029_50290025_36_dialog_content = "Fia adalah doggy, Fia adalah doggy!",
  ui_story_5029_50290025_37_dialog_content = "Saya tidak...",
  ui_story_5029_50290025_38_dialog_content = "aku bukan anjing...",
  ui_story_5029_50290025_39_dialog_content = "Berhenti menangis dan ambilkan aku es krim, doggy!",
  ui_story_5029_50290025_40_dialog_content = "Hei, kenapa kamu jahat?",
  ui_story_5029_50290025_41_dialog_content = "Ada apa dengan sikap?",
  ui_story_5029_50290025_42_dialog_content = "Saya korban di sini. Anjingnya memakan es krim saya!",
  ui_story_5029_50290025_X42_dialog_content = "Saya akan meminta maaf kepada Anda atas namanya. Saya minta maaf...",
  ui_story_5029_50290025_43_dialog_content = "Ini dia. Itu lebih dari cukup bagimu untuk membeli sepuluh es krim lagi.",
  ui_story_5029_50290025_44_dialog_content = "Itu lebih baik.",
  ui_story_5029_50290025_45_dialog_content = "Aku belum selesai.",
  ui_story_5029_50290025_46_dialog_content = "Anda tahu Fia tidak melakukannya dengan sengaja, jadi mengapa mengacaukannya?",
  ui_story_5029_50290025_47_dialog_content = "Seberapa tangguh kamu untuk memilih seorang gadis dan membuatnya menangis?",
  ui_story_5029_50290025_48_dialog_content = "...",
  ui_story_5029_50290025_49_dialog_content = "Anda tidak akan lolos lain kali jika saya memergoki Anda melakukannya lagi!",
  ui_story_5029_50290025_50_dialog_content = "Mengerti?",
  ui_story_5029_50290025_51_dialog_content = "Mengerti...",
  ui_story_5029_50290025_52_dialog_content = "Kemudian bersumpah itu tidak akan terjadi lagi.",
  ui_story_5029_50290025_53_dialog_content = "Itu tidak akan terjadi lagi.",
  ui_story_5029_50290025_54_dialog_content = "Semuanya baik-baik saja sekarang, Fia.",
  ui_story_5029_50290025_55_dialog_content = "Anda suka berkelahi sepanjang waktu, jadi kenapa Anda membiarkan seorang anak kecil mengintimidasi Anda?",
  ui_story_5029_50290025_56_dialog_content = "Jika tuanmu tahu...",
  ui_story_5029_50290025_57_dialog_content = "Wah!",
  ui_story_5029_50290025_58_dialog_content = "Anda terlambat, Nama Pemain.",
  ui_story_5029_50290025_59_dialog_content = "Apa?",
  ui_story_5029_50290025_60_dialog_content = "Ah, maaf, saya terlambat.",
  ui_story_5029_50290025_61_dialog_content = "Wah... Kyllo bukan anjing, dan aku bukan anjing.",
  ui_story_5029_50290025_62_dialog_content = "Aku tahu Kyllo tidak bermaksud... Kenapa anak laki-laki itu meletakkan es krimnya di sembarang tempat...",
  ui_story_5029_50290025_X62_dialog_content = "Belum lagi, Fia sudah meminta maaf...",
  ui_story_5029_50290025_63_dialog_content = "Aku tahu... Tidak apa-apa. Ini sudah berakhir sekarang.",
  ui_story_5029_50290025_64_dialog_content = "Wah... Aku benci anak kecil yang tidak masuk akal!",
  ui_story_5029_50290025_65_dialog_content = "Bukankah kamu sendiri anak-anak?",
  ui_story_5029_50290025_66_dialog_content = "Aku bukan anak kecil! Aku sudah dewasa!",
  ui_story_5029_50290025_67_dialog_content = "Dan dan...",
  ui_story_5029_50290025_68_dialog_content = "Saya tidak akan pernah menggertak atau mengejek anak-anak lain...",
  ui_story_5029_50290025_69_dialog_content = "Saya tahu itu! Tapi saya juga tahu Anda kadang-kadang mencoba untuk memilih orang dewasa.",
  ui_story_5029_50290025_70_dialog_content = "Tidak!",
  ui_story_5029_50290025_71_dialog_content = "Lihat!",
  ui_story_5029_50290025_72_dialog_content = "Lihat, bahkan Kyllo mengkhawatirkanmu.",
  ui_story_5029_50290025_73_dialog_content = "Mengapa kita tidak mencari tempat untuk duduk dan berbicara?",
  ui_story_5029_50290025_74_dialog_content = "Oke.",
  ui_story_5029_50290025_75_dialog_content = "Jika, dan maksudku jika, aku pernah mengatakan sesuatu yang membuatmu marah...",
  ui_story_5029_50290025_76_dialog_content = "Maaf…",
  ui_story_5029_50290025_77_option_content = "Tidak masalah!",
  ui_story_5029_50290025_78_dialog_content = "Aku tahu kamu anak yang baik.",
  ui_story_5029_50290025_79_dialog_content = "Terkadang sedikit kejam dengan kata-kata, tetapi Anda peduli dengan semua orang dan membantu mereka.",
  ui_story_5029_50290025_80_dialog_content = "Bukankah membelikan gurumu hadiah adalah alasan mengapa kamu mencari hadiah?",
  ui_story_5029_50290025_81_dialog_content = "Itu hanya sebagian saja.",
  ui_story_5029_50290025_82_dialog_content = "Jika saya mendapat cukup biaya perjalanan dari guru saya, Kyllo dan saya tidak akan menderita seperti ini!",
  ui_story_5029_50290025_83_dialog_content = "Dan aku tidak akan dipilih oleh seorang anak...",
  ui_story_5029_50290025_84_dialog_content = "Oh ya, berjanjilah, PlayerName!",
  ui_story_5029_50290025_85_option_content = "Janji? Itu tiba-tiba...",
  ui_story_5029_50290025_86_dialog_content = "Sebenarnya, saya sangat ingin bermain dengan anak-anak seusia saya ketika saya masih kecil.",
  ui_story_5029_50290025_87_dialog_content = "Tapi mereka selalu mencelaku dan akhirnya menjadikanku sasaran lelucon mereka.",
  ui_story_5029_50290025_88_dialog_content = "Pada saat itu, saya berharap saya memiliki kakak laki-laki yang perkasa.",
  ui_story_5029_50290025_89_dialog_content = "Seseorang yang bisa memberi pelajaran pada anak-anak itu.",
  ui_story_5029_50290025_90_dialog_content = "Dan saya juga ingin menjadi seseorang yang mereka iri suatu hari nanti.",
  ui_story_5029_50290025_91_dialog_content = "Namun…",
  ui_story_5029_50290025_92_dialog_content = "Saya hanya bisa tinggal di sepanjang hari.",
  ui_story_5029_50290025_93_dialog_content = "Jika saya melihat mereka, saya akan berpura-pura tidak peduli.",
  ui_story_5029_50290025_94_dialog_content = "Tapi itu hanya mendorong mereka. aku merasa sangat tidak berdaya...",
  ui_story_5029_50290025_95_dialog_content = "Anak itu membawa saya kilas balik.",
  ui_story_5029_50290025_96_dialog_content = "Pada saat itu, saya adalah anak malang itu lagi.",
  ui_story_5029_50290025_97_dialog_content = "Tapi kali ini berbeda. Seseorang berdiri untukku!",
  ui_story_5029_50290025_98_dialog_content = "Dan itu kamu, PlayerName...",
  ui_story_5029_50290025_99_dialog_content = "Jadi saya terus berpikir, kalau saja Anda adalah kakak laki-laki, PlayerName.",
  ui_story_5029_50290025_100_dialog_content = "Dan andai saja kau bersamaku dan melindungiku selama ini, PlayerName.",
  ui_story_5029_50290025_101_dialog_content = "Tidak masalah. Aku beberapa tahun lebih tua darimu dan aku cocok dengan peran itu.",
  ui_story_5029_50290025_102_dialog_content = "Plus, Anda bukan anak yang tidak berdaya lagi.",
  ui_story_5029_50290025_103_dialog_content = "Anda berhasil menjadi ahli ekstrozoologi.",
  ui_story_5029_50290025_104_dialog_content = "Itu bukan sesuatu yang bisa dilakukan rekan Anda.",
  ui_story_5029_50290025_105_dialog_content = "Saya tidak peduli.",
  ui_story_5029_50290025_106_dialog_content = "Saya ingin Anda membela saya mulai sekarang seperti yang Anda lakukan hari ini!",
  ui_story_5029_50290025_107_dialog_content = "Oke, aku berjanji.",
  ui_story_5029_50290025_108_dialog_content = "Janji?",
  ui_story_5029_50290025_109_dialog_content = "Ya, aku berjanji.",
  ui_story_5029_50290025_110_dialog_content = "PlayerName, kakakku...",
  ui_story_5029_50290025_111_dialog_content = "Pekerjaan pertamamu sebagai kakak adalah...",
  ui_story_5029_50290025_112_dialog_content = "Jangan biarkan siapa pun tahu aku menangis hari ini!",
  ui_story_5029_50290025_113_dialog_content = "Atau aku akan digoda lagi.",
  ui_story_5029_50290025_114_dialog_content = "Baiklah, aku berjanji tidak akan ada yang tahu.",
  ui_story_5029_50290025_115_dialog_content = "Fiuh, aku dipukul...",
  ui_story_5029_50290025_116_dialog_content = "Tentu saja. Menangis menguras banyak hal darimu.",
  ui_story_5029_50290025_117_dialog_content = "Dan inilah kami...",
  ui_story_5029_50290025_118_dialog_content = "Masih gagal menangkap pelakunya.",
  ui_story_5029_50290025_119_dialog_content = "Tidak apa-apa, dan kami mendapatkan kembali kotak perak itu.",
  ui_story_5029_50290025_120_dialog_content = "Zzz...",
  ui_story_5029_50290025_121_dialog_content = "Dia bahkan bisa tertidur sambil duduk?",
  ui_story_5029_50290025_122_dialog_content = "(Fia sedang tidur dengan nyaman di antara kerumunan yang ramai.)",
  ui_story_5029_50290025_123_dialog_content = "(Bintik basah dari air matanya di bajuku perlahan mengering di bawah sinar matahari.)",
  ui_story_5029_50290025_124_dialog_content = "(Jika aku punya adik perempuan, dia mungkin seumuran Fia sekarang...)",
  ui_story_5029_50290025_125_dialog_content = "<color=#828282>Ding...</color>",
  ui_story_5029_50290025_126_dialog_content = "Selamat datang kembali, tamu tersayang.",
  ui_story_5029_50290025_127_dialog_content = "Apa kau kecewa melihatku?",
  ui_story_5029_50290025_128_dialog_content = "Maaf, tapi saya tidak sengaja melihat rahasia Anda.",
  ui_story_5029_50290025_129_dialog_content = "Tapi tolong jangan kecewa.",
  ui_story_5029_50290025_130_dialog_content = "Mimpi hanya bisa terbentuk di atas fondasi yang didasarkan pada kenyataan.",
  ui_story_5029_50290025_131_dialog_content = "Itu berarti Anda dan dia cenderung mengalami situasi yang sama dalam hidup.",
  ui_story_5029_50290025_132_dialog_content = "Namun, tidak seperti dalam mimpi, tidak ada trik seperti itu dalam kenyataan.",
  ui_story_5029_50290025_133_dialog_content = "Pasti ada kesulitan menyesuaikan diri dengan hidup dalam fantasi yang saya buat.",
  ui_story_5029_50290025_134_dialog_content = "Omong-omong, apakah Anda puas dengan akhir ini?",
  ui_story_5029_50290025_135_dialog_content = "Tidakkah kamu merasa ada yang hilang?",
  ui_story_5029_50290025_136_dialog_content = "Yang ingin saya katakan adalah... Kita masih punya waktu.",
  ui_story_5029_50290025_137_dialog_content = "Tetapi premisnya adalah Anda masih ingin mencari misteri dan jawaban dalam mimpi.",
  ui_story_5029_50290026_1_dialog_content = "(Hmm...)",
  ui_story_5029_50290026_2_dialog_content = "(Ini adalah perpustakaan laird.)",
  ui_story_5029_50290026_3_dialog_content = "(Mengapa saya di sini lagi?)",
  ui_story_5029_50290026_4_dialog_content = "(Aneh, kenapa saya bilang 'lagi'?)",
  ui_story_5029_50290026_5_dialog_content = "Anda dapat dengan bebas menjelajahi rumah untuk mencari petunjuk.",
  ui_story_5029_50290026_6_dialog_content = "Saya akan berada di sini di lobi jika Anda memiliki pertanyaan.",
  ui_story_5029_50290026_7_dialog_content = "(Sepertinya saya pernah mendengarnya berkali-kali sebelumnya ...)",
  ui_story_5029_50290026_8_option_content = "Bicaralah dengan Zane",
  ui_story_5029_50290026_9_option_content = "Lihat sekeliling",
  ui_story_5029_50290026_10_dialog_content = "(Tidak!)",
  ui_story_5029_50290026_11_dialog_content = "(Sekarang bukan waktunya untuk membuat pilihan itu.)",
  ui_story_5029_50290026_12_dialog_content = "(Jika ini terus berlanjut, kita tidak akan pernah menemukan pelakunya yang sebenarnya.)",
  ui_story_5029_50290026_13_dialog_content = "(Jika kita tidak dapat menemukan pelakunya, laird bisa berada dalam bahaya... dan aku mungkin akan terjebak di sini selamanya.)",
  ui_story_5029_50290026_14_dialog_content = "(Tunggu, terjebak di sini? Apa yang kupikirkan? Lagi pula...)",
  ui_story_5029_50290026_15_option_content = "Datang ke sini, semuanya!",
  ui_story_5029_50290026_16_option_content = "Carleen, Vice, Fi!",
  ui_story_5029_50290026_17_dialog_content = "Mengapa begitu keras, PlayerName?",
  ui_story_5029_50290026_18_dialog_content = "Apakah Anda menemukan sesuatu?",
  ui_story_5029_50290026_19_dialog_content = "Ayo cepat! Saya merasa saya sangat dekat untuk mendapatkan petunjuk penting!",
  ui_story_5029_50290026_20_dialog_content = "Kasus ini bukan permainan atau balapan.",
  ui_story_5029_50290026_21_dialog_content = "Saya harap kita bisa bekerja sama!",
  ui_story_5029_50290026_22_dialog_content = "Mengapa? Bukankah kita harus membagi hadiah secara merata?",
  ui_story_5029_50290026_23_dialog_content = "Temui saya jika Anda tidak dapat menemukan pasangan, PlayerName.",
  ui_story_5029_50290026_24_dialog_content = "Saya tidak keberatan bekerja dengan Anda.",
  ui_story_5029_50290026_25_dialog_content = "Dengar, kita tidak punya banyak waktu.",
  ui_story_5029_50290026_26_dialog_content = "Jika kita tidak bekerja sama untuk menangkap pelakunya, akan ada dampak serius.",
  ui_story_5029_50290026_27_dialog_content = "Eh, kita semua tahu itu.",
  ui_story_5029_50290026_28_dialog_content = "Tolong percaya padaku, aku punya firasat.",
  ui_story_5029_50290026_29_dialog_content = "Pelakunya akan segera melarikan diri dengan kotak perak, dan kita tidak bisa menangkap mereka sendirian.",
  ui_story_5029_50290026_30_dialog_content = "Kita harus mengidentifikasi pelakunya sebelum itu dan mendahului!",
  ui_story_5029_50290026_31_dialog_content = "Tapi mengapa kami harus mempercayai firasat Anda?",
  ui_story_5029_50290026_32_dialog_content = "Fia, jangan sampai Kyllo mendekati sudut kafe.",
  ui_story_5029_50290026_33_dialog_content = "Atau mungkin terpotong oleh pisau yang dilapisi selai stroberi.",
  ui_story_5029_50290026_34_dialog_content = "Benarkah?",
  ui_story_5029_50290026_35_dialog_content = "Carleen, ada sebuah buku yang sangat tua di atas meja di lantai dua.",
  ui_story_5029_50290026_36_dialog_content = "Mungkin akan berantakan jika Anda mengambilnya dan sarangnya akan tidak senang.",
  ui_story_5029_50290026_37_dialog_content = "Oh?",
  ui_story_5029_50290026_38_dialog_content = "Vice, bunga di lobi yang menurutmu cantik ternyata beracun. Cobalah untuk tidak terlalu dekat.",
  ui_story_5029_50290026_39_dialog_content = "Tapi tidak apa-apa selama Anda tidak menelannya.",
  ui_story_5029_50290026_40_dialog_content = "Apa? Bagaimana Anda tahu saya ingin memeriksanya?",
  ui_story_5029_50290026_41_dialog_content = "Aku punya firasat.",
  ui_story_5029_50290026_42_dialog_content = "Apakah Anda sudah menggeledah seluruh rumah saat kami tidak melihat?",
  ui_story_5029_50290026_43_dialog_content = "Mungkin saja...",
  ui_story_5029_50290026_44_dialog_content = "Dalam hal ini, Anda harus memiliki rencana yang sempurna agar kami dapat bekerja sama.",
  ui_story_5029_50290026_45_dialog_content = "Saya tidak akan menyebutnya sempurna, tetapi Anda pasti bisa mengikutinya.",
  ui_story_5029_50290026_46_dialog_content = "<color=#828282>Suatu saat nanti</color>",
  ui_story_5029_50290026_47_dialog_content = "PlayerName benar, dealer di sini untuk bernegosiasi adalah Jomu.",
  ui_story_5029_50290026_48_dialog_content = "Seperti yang diinstruksikan PlayerName, saya berjanji untuk mengatur pertemuan lain antara dia dan laird.",
  ui_story_5029_50290026_49_dialog_content = "Dan dia menumpahkan semuanya!",
  ui_story_5029_50290026_50_dialog_content = "Saya melihat laird mengunci pintu dan pergi, jadi saya mengambil kunci dan menyelinap masuk.",
  ui_story_5029_50290026_51_dialog_content = "Secara bersinggungan, skill lockpicking saya adalah yang teratas bahkan di Rediesel Wrench.",
  ui_story_5029_50290026_52_dialog_content = "Aku pergi setelah meletakkan beberapa salinan Shinnosuke Sinsa di tempat yang paling mencolok.",
  ui_story_5029_50290026_53_dialog_content = "Ya, selanjutnya adalah Duchess Beverly dari Lumopolis. Dia berkata...",
  ui_story_5029_50290026_54_dialog_content = "Saya menunggu lama dan melihat seorang pria berambut hijau meninggalkan perpustakaan.",
  ui_story_5029_50290026_55_dialog_content = "Setelah saya memastikan tidak ada orang di sekitar, saya masuk untuk mencari lencana yang hilang.",
  ui_story_5029_50290026_56_dialog_content = "Tetapi saya tidak dapat menemukannya seumur hidup saya, dan saya mendengar seseorang datang, jadi saya pergi.",
  ui_story_5029_50290026_57_dialog_content = "Beverly pasti berbicara tentang Manae, yang kalian panggil Sanae. Dia berkata...",
  ui_story_5029_50290026_58_dialog_content = "Saya menyadari pintu tidak terkunci dan masuk diam-diam.",
  ui_story_5029_50290026_59_dialog_content = "Saya membersihkan pecahan vas yang saya sembunyikan di bawah sofa dan menggantinya dengan vas baru.",
  ui_story_5029_50290026_60_dialog_content = "Saya pikir tidak ada yang akan tahu, tapi Mr Cook masih tahu...",
  ui_story_5029_50290026_61_dialog_content = "Mr Cook berjanji untuk tidak melaporkan saya dan mengatakan kepada saya untuk memastikan pintu dan jendela terkunci.",
  ui_story_5029_50290026_62_dialog_content = "Itu sebabnya pintu terkunci ketika sarang kembali.",
  ui_story_5029_50290026_63_dialog_content = "Urutan urutannya benar.",
  ui_story_5029_50290026_64_dialog_content = "Saya baru saja menemukan tiga saksi yang bisa membuktikan itu juga.",
  ui_story_5029_50290026_65_dialog_content = "Segera setelah laird mengunci pintu, pria berambut hijau itu kembali.",
  ui_story_5029_50290026_66_dialog_content = "Saya memang melihat seorang wanita bangsawan muda yang cantik pada waktu makan malam.",
  ui_story_5029_50290026_67_dialog_content = "Saya melihat \"Manae\" menyelinap ke kamar laird. Dia tampak mencurigakan.",
  ui_story_5029_50290026_68_dialog_content = "Firasatmu benar hari ini, PlayerName.",
  ui_story_5029_50290026_69_dialog_content = "Tidak hanya identitas sebenarnya yang ditemukan, tetapi bahkan para saksi juga!",
  ui_story_5029_50290026_70_dialog_content = "Tapi kita masih kembali ke titik awal.",
  ui_story_5029_50290026_71_dialog_content = "Ketiganya pergi ke perpustakaan, tetapi satu demi satu.",
  ui_story_5029_50290026_72_dialog_content = "Itu berarti pelakunya pasti salah satu dari ketiganya...",
  ui_story_5029_50290026_73_dialog_content = "Tapi Anda sepertinya tidak mencurigai salah satu dari mereka, PlayerName.",
  ui_story_5029_50290026_74_dialog_content = "Tidak bisakah ada orang keempat?",
  ui_story_5029_50290026_75_dialog_content = "Keempat?",
  ui_story_5029_50290026_76_dialog_content = "Itu kemungkinan.",
  ui_story_5029_50290026_77_dialog_content = "Mungkin seseorang yang ada di sekitar kita jadi kita mengabaikannya.",
  ui_story_5029_50290026_78_dialog_content = "Fia, apakah Kyllo menyelinap menggigit logam apa pun kemarin?",
  ui_story_5029_50290026_79_dialog_content = "Lo, lo?",
  ui_story_5029_50290026_80_dialog_content = "Kyllo tidak sebodoh itu!",
  ui_story_5029_50290026_81_dialog_content = "Saya pikir Zane mungkin pelakunya.",
  ui_story_5029_50290026_82_dialog_content = "Zane? Mustahil.",
  ui_story_5029_50290026_83_dialog_content = "Semakin tidak mungkin, semakin mungkin!",
  ui_story_5029_50290026_84_dialog_content = "Seluruh rantai logika rusak ketika bahkan hanya satu tautan yang hilang.",
  ui_story_5029_50290026_85_dialog_content = "Jadi kami mengabaikan sesuatu.",
  ui_story_5029_50290026_86_dialog_content = "Kami melihatnya, tetapi mengabaikannya.",
  ui_story_5029_50290026_87_dialog_content = "Hei, apakah kamu tidak akan menanyai Zane?",
  ui_story_5029_50290026_88_dialog_content = "Apa hanya aku yang mengira dia tersangka?",
  ui_story_5029_50290026_89_dialog_content = "Mengira...",
  ui_story_5029_50290026_90_dialog_content = "Sanae?",
  ui_story_5029_50290026_91_dialog_content = "Anda curiga Sanae, Nama pemain?",
  ui_story_5029_50290026_92_dialog_content = "Bukan saya...",
  ui_story_5029_50290026_93_dialog_content = "Seseorang menekankannya padaku.",
  ui_story_5029_50290026_94_dialog_content = "Lihat!",
  ui_story_5029_50290026_95_dialog_content = "Kenapa kamu menatap ke luar jendela, Kyllo?",
  ui_story_5029_50290026_96_dialog_content = "Hanya ada pohon di luar...",
  ui_story_5029_50290026_97_dialog_content = "(Oh tidak, dia sudah bergerak?)",
  ui_story_5029_50290026_98_dialog_content = "Hei, lihat, siapa pria menyeramkan di luar sana?",
  ui_story_5029_50290027_1_dialog_content = "(Apakah kita terlambat?)",
  ui_story_5029_50290027_2_dialog_content = "(Tidak, masih ada kesempatan!)",
  ui_story_5029_50290027_3_dialog_content = "(Kita bisa melakukan ini jika kita bekerja sama!)",
  ui_story_5029_50290027_4_dialog_content = "(Tarik napas... Sekarang pikirkan sesuatu untuk menangkap pelakunya.)",
  ui_story_5029_50290027_5_dialog_content = "Itu aneh, memakai begitu banyak di hari yang panas seperti ini.",
  ui_story_5029_50290027_6_dialog_content = "Apakah dia menggali di luar sana?",
  ui_story_5029_50290027_7_dialog_content = "(Penggalian...)",
  ui_story_5029_50290027_8_dialog_content = "(Saya mengerti, dia menguburnya di taman belakang!)",
  ui_story_5029_50290027_9_dialog_content = "Dengarkan aku, itu pencuri yang mencuri kotak perak itu!",
  ui_story_5029_50290027_10_dialog_content = "Dia menggali kotak dan akan lari.",
  ui_story_5029_50290027_11_dialog_content = "Apa yang kita tunggu? Ayo tangkap dia!",
  ui_story_5029_50290027_12_dialog_content = "Tunggu, Fia.",
  ui_story_5029_50290027_13_dialog_content = "Siap memimpin, PlayerName?",
  ui_story_5029_50290027_14_dialog_content = "Eh, semua orang...?",
  ui_story_5029_50290027_15_dialog_content = "Bukankah itu ide Anda untuk bekerja sama?",
  ui_story_5029_50290027_16_dialog_content = "Ini bukan melawan Eclipsites, tapi kamu masih yang terbaik dalam memimpin tim.",
  ui_story_5029_50290027_17_dialog_content = "Yah, oke!",
  ui_story_5029_50290027_18_dialog_content = "Fia, ambil Kyllo dan potong dia di kaki bukit.",
  ui_story_5029_50290027_19_dialog_content = "Ini akan menjadi masalah jika kita membiarkan dia masuk ke gunung.",
  ui_story_5029_50290027_20_dialog_content = "Siap!",
  ui_story_5029_50290027_21_dialog_content = "Vice, Carleen, mengapitnya dari kiri dan kanan.",
  ui_story_5029_50290027_22_dialog_content = "Dan ambil senjatamu untuk berjaga-jaga.",
  ui_story_5029_50290027_23_dialog_content = "Aku akan mengikutinya kalau-kalau dia mundur.",
  ui_story_5029_50290027_24_dialog_content = "Siap!",
  ui_story_5029_50290027_25_dialog_content = "Anda tidak akan lolos kali ini.",
  ui_story_5029_50290027_26_dialog_content = "Bagaimana situasinya?",
  ui_story_5029_50290027_27_dialog_content = "Itu berhasil! Pelakunya sedang menuju pelabuhan.",
  ui_story_5029_50290027_28_dialog_content = "Huff... Dia terlalu cepat untukku.",
  ui_story_5029_50290027_29_dialog_content = "Tidak apa-apa, aku membawa suar.",
  ui_story_5029_50290027_30_dialog_content = "Aku hanya akan menandai pria itu, Kyllo, dan kau hentikan dia pergi dengan kotak perak itu.",
  ui_story_5029_50290027_31_dialog_content = "Lihat!",
  ui_story_5029_50290027_32_dialog_content = "Aneh, kenapa rasanya aku mengatakan hal yang sama sebelumnya?",
  ui_story_5029_50290027_33_dialog_content = "Sudahlah... Serangan Sinyal Fatal Fia!",
  ui_story_5029_50290027_34_dialog_content = "…?",
  ui_story_5029_50290027_35_dialog_content = "Geram... Lo!",
  ui_story_5029_50290027_36_dialog_content = "Itu dia, Kyllo, gigit tangannya!",
  ui_story_5029_50290027_37_dialog_content = "halo halo!",
  ui_story_5029_50290027_38_dialog_content = "Oh tidak, pelakunya melemparkan kotak itu ke Kyllo!",
  ui_story_5029_50290027_39_dialog_content = "Hati-hati, Kyu!",
  ui_story_5029_50290027_40_dialog_content = "<color=#828282>Bum!</color>",
  ui_story_5029_50290027_41_dialog_content = "Kotak ini berat!",
  ui_story_5029_50290027_42_dialog_content = "Luar biasa, Vice menangkap kotak untuk Kyllo!",
  ui_story_5029_50290027_43_dialog_content = "Jaga kotaknya, Kyllo. Carleen dan sisanya akan saya tangani.",
  ui_story_5029_50290027_44_dialog_content = "Mendorong dengan cepat, Vice, kita harus mengejar pelakunya.",
  ui_story_5029_50290027_45_dialog_content = "Tidak masalah. Sniping jarak jauh adalah keahlian saya!",
  ui_story_5029_50290027_46_dialog_content = "Tracking Strike!",
  ui_story_5029_50290027_47_dialog_content = "Ugh...",
  ui_story_5029_50290027_48_dialog_content = "Wow, tembakan yang bagus, Vice! Anda memukul pantatnya!",
  ui_story_5029_50290027_49_dialog_content = "Apakah Anda santai sehingga Anda tidak akan menyakitinya, Vice?",
  ui_story_5029_50290027_50_dialog_content = "Pelakunya mencoba berdiri...",
  ui_story_5029_50290027_51_dialog_content = "Dia tidak akan pergi. Carleen ada di dia sekarang!",
  ui_story_5029_50290027_52_dialog_content = "Ini sudah berakhir. Tidak ada jalan keluar.",
  ui_story_5029_50290027_53_dialog_content = "Apa-apaan…?!",
  ui_story_5029_50290027_54_dialog_content = "Tidak ada bayangan di mana tombak menunjuk!",
  ui_story_5029_50290027_55_dialog_content = "Ugh...",
  ui_story_5029_50290027_56_dialog_content = "Akhirnya. Muncul.",
  ui_story_5029_50290027_57_dialog_content = "Kami menangkap pelakunya.",
  ui_story_5029_50290027_58_dialog_content = "Kerja sama tim yang hebat, Vice.",
  ui_story_5029_50290027_59_dialog_content = "Ya, kerja tim yang hebat.",
  ui_story_5029_50290027_60_dialog_content = "Itu spektakuler bagaimana Anda memakukannya dari jarak sejauh itu.",
  ui_story_5029_50290027_61_dialog_content = "Tapi tetap saja, dia berlari terlalu cepat.",
  ui_story_5029_50290027_62_dialog_content = "Untungnya, kami mendapat Carleen, Kapten Penjaga Lumopolis.",
  ui_story_5029_50290027_63_dialog_content = "Dengan kehadiranmu, tidak ada penjahat yang bisa berharap untuk melarikan diri.",
  ui_story_5029_50290027_64_dialog_content = "Berhenti, aku mulai merinding.",
  ui_story_5029_50290027_65_dialog_content = "Saya memuji Anda. Apa yang salah dengan itu?",
  ui_story_5029_50290027_66_dialog_content = "Saya yakin tidak akan menahan diri untuk menerima semua pujian itu dari Anda.",
  ui_story_5029_50290027_67_dialog_content = "Tunggu, Vice dan Carleen... Jangan lupakan aku!",
  ui_story_5029_50290027_68_dialog_content = "Tentu saja kami tidak akan melupakanmu.",
  ui_story_5029_50290027_69_dialog_content = "Fia melakukan pekerjaan yang bagus dengan memblokir celah gunung.",
  ui_story_5029_50290027_70_dialog_content = "Ya, saya melakukan itu, bukan?",
  ui_story_5029_50290027_71_dialog_content = "Tapi jangan abaikan yang paling penting dari semua ini!",
  ui_story_5029_50290027_72_dialog_content = "Kami tidak akan menyadari bahwa orang menyeramkan di taman itu adalah pelakunya.",
  ui_story_5029_50290027_73_dialog_content = "Vice dan Carleen mengacu pada Anda, Kyllo!",
  ui_story_5029_50290027_74_dialog_content = "lihat?",
  ui_story_5029_50290027_75_dialog_content = "Ehem, itu benar.",
  ui_story_5029_50290027_76_dialog_content = "Bagus, Kyllo, kamu pantas mendapatkan hadiah malam ini!",
  ui_story_5029_50290027_77_dialog_content = "Lo, lo, lo!",
  ui_story_5029_50290027_78_dialog_content = "Hei, apa yang PlayerName katakan kepada pelakunya?",
  ui_story_5029_50290027_79_dialog_content = "Apakah itu benar-benar Anda?",
  ui_story_5029_50290027_80_dialog_content = "Hmph.",
  ui_story_5029_50290027_81_dialog_content = "Itu sebabnya Anda mencoba segalanya untuk membuat saya mencurigai orang lain.",
  ui_story_5029_50290027_82_dialog_content = "Semua penyamaran itu hanya untuk mencuri ini?",
  ui_story_5029_50290027_83_dialog_content = "...",
  ui_story_5029_50290027_84_dialog_content = "Kerja bagus dengan perencanaan hari ini, PlayerName.",
  ui_story_5029_50290027_85_dialog_content = "Ya.",
  ui_story_5029_50290027_85X1_dialog_content = "Jika Anda tidak membuat kami bekerja sama di momen penting, kami tidak mungkin menangkap belut licin ini.",
  ui_story_5029_50290027_86_dialog_content = "Tapi aku penasaran, kita hanya menganggap orang ini sebagai pria menyeramkan di taman...",
  ui_story_5029_50290027_87_dialog_content = "Bagaimana Anda tahu dia mencuri kotak itu? Apakah itu salah satu firasat Anda?",
  ui_story_5029_50290027_88_dialog_content = "Anda mempelajari pelajaran Anda jika Anda telah melewatinya cukup lama.",
  ui_story_5029_50290027_89_dialog_content = "Hah?",
  ui_story_5029_50290027_90_dialog_content = "Aku penasaran siapa pelakunya. Apakah itu Zane?",
  ui_story_5029_50290027_91_dialog_content = "Nama Pemain dipatok Sanae beberapa saat yang lalu.",
  ui_story_5029_50290027_92_dialog_content = "Orang ini belum terungkap, tapi jelas belum Sanae.",
  ui_story_5029_50290027_93_dialog_content = "Dia sengaja menyesatkan saya untuk curiga Sanae.",
  ui_story_5029_50290027_94_dialog_content = "Pelayan laird, saksi untuk Sanae masuk ke perpustakaan...",
  ui_story_5029_50290027_95_dialog_content = "Memasak.",
  ui_story_5029_50290027_96_dialog_content = "...",
  ui_story_5029_50290028_1_dialog_content = "Memasak?",
  ui_story_5029_50290028_2_dialog_content = "Sanae menyebut nama itu sebelumnya.",
  ui_story_5029_50290028_3_dialog_content = "Masak malah mengingatkan Sanae untuk mengunci pintu, meskipun... Dia terdengar seperti pria yang baik!",
  ui_story_5029_50290028_4_dialog_content = "Telah melakukan Sanae sebutkan di mana dia bertemu Cook?",
  ui_story_5029_50290028_5_dialog_content = "Ya, perpustakaan... Oh.",
  ui_story_5029_50290028_6_dialog_content = "Itu benar, Cook adalah orang keempat di perpustakaan.",
  ui_story_5029_50290028_7_dialog_content = "Saya melakukan kesalahan dengan memperlakukan saksi sebagai tidak bersalah.",
  ui_story_5029_50290028_8_dialog_content = "Maksudmu pria yang kau tangkap ini adalah Cook?",
  ui_story_5029_50290028_9_dialog_content = "Hei, ini lairdnya!",
  ui_story_5029_50290028_10_dialog_content = "Saya hanya akan melalui proses deduksi saya.",
  ui_story_5029_50290028_11_dialog_content = "Kami belum benar-benar membuka kedok pelakunya.",
  ui_story_5029_50290028_12_dialog_content = "Semuanya baik. Saya ingin mendengar alasan Anda juga, PlayerName.",
  ui_story_5029_50290028_13_dialog_content = "Jika saya benar ...",
  ui_story_5029_50290028_14_dialog_content = "<color=#828282>Kriek...</color>",
  ui_story_5029_50290028_15_dialog_content = "Apakah seseorang di sini?",
  ui_story_5029_50290028_16_dialog_content = "Saya akan kembali untuk itu di lain hari.",
  ui_story_5029_50290028_17_dialog_content = "Heh, betapa beruntungnya.",
  ui_story_5029_50290028_18_dialog_content = "Aku hanya mengantarkan koran, tapi sarangnya tidak ada di dalam, dan perpustakaannya tidak terkunci.",
  ui_story_5029_50290028_19_dialog_content = "Barang-barang berharganya adalah milikku sekarang!",
  ui_story_5029_50290028_20_dialog_content = "<color=#828282>Kriek...</color>",
  ui_story_5029_50290028_21_dialog_content = "Siapa di sana?",
  ui_story_5029_50290028_22_dialog_content = "Itu dia? Yah, gadis itu seharusnya mudah dibodohi.",
  ui_story_5029_50290028_23_dialog_content = "Selama dia tidak melihatku dengan kotak itu.",
  ui_story_5029_50290028_24_dialog_content = "Biarkan saya melemparkan kotak itu keluar jendela dan mengambilnya nanti.",
  ui_story_5029_50290028_25_dialog_content = "<color=#828282>Bum!</color>",
  ui_story_5029_50290028_26_dialog_content = "(Tikus, itu menabrak xerophyte di dekat jendela ...)",
  ui_story_5029_50290028_27_dialog_content = "Suara berisik apa itu?",
  ui_story_5029_50290028_28_dialog_content = "Apa yang kamu lakukan di perpustakaan laird selarut ini?",
  ui_story_5029_50290028_29_dialog_content = "aku, eh...",
  ui_story_5029_50290028_30_dialog_content = "Apakah Anda memecahkan sesuatu dari laird lagi?",
  ui_story_5029_50290028_31_dialog_content = "Saya membeli pengganti baru. Tidak ada yang akan memperhatikan.",
  ui_story_5029_50290028_32_dialog_content = "Tolong, jangan beri tahu laird atau kepala pelayan...",
  ui_story_5029_50290028_33_dialog_content = "Atau aku akan dipecat.",
  ui_story_5029_50290028_34_dialog_content = "Yah, seharusnya tidak apa-apa jika Anda membawa pengganti.",
  ui_story_5029_50290028_35_dialog_content = "Hah?",
  ui_story_5029_50290028_36_dialog_content = "Aku akan berpura-pura tidak pernah melihatmu di sini.",
  ui_story_5029_50290028_37_dialog_content = "Tapi ingat untuk mengunci semua pintu dan jendela.",
  ui_story_5029_50290028_38_dialog_content = "Oleh karena itu, orang yang mengikuti Beverly bukan Sanae. Itu adalah Koki!",
  ui_story_5029_50290028_39_dialog_content = "Gadis bodoh itu. Dia bahkan menyapu lantai sesudahnya dan menghapus jejak kakiku.",
  ui_story_5029_50290028_40_dialog_content = "Heh, rencana yang sempurna!",
  ui_story_5029_50290028_41_dialog_content = "Suara...",
  ui_story_5029_50290028_42_dialog_content = "...",
  ui_story_5029_50290028_43_dialog_content = "Ini benar-benar kamu, Koki?!",
  ui_story_5029_50290028_44_dialog_content = "Kamu benar! Sungguh detektif yang hebat, PlayerName!",
  ui_story_5029_50290028_45_dialog_content = "Jika saya tidak terburu-buru untuk pergi, Anda tidak akan pernah tahu itu saya!",
  ui_story_5029_50290028_46_dialog_content = "Tidak, Anda masih meninggalkan petunjuk.",
  ui_story_5029_50290028_47_dialog_content = "Tak mungkin!",
  ui_story_5029_50290028_48_dialog_content = "Apakah Anda lupa tentang koran di kafe?",
  ui_story_5029_50290028_49_dialog_content = "Laird menahan audiensi sepanjang hari, dan dia tidak mendapatkan kertas yang seharusnya Anda kirim.",
  ui_story_5029_50290028_50_dialog_content = "Tapi bagaimana koran kemarin bisa sampai di kafe?",
  ui_story_5029_50290028_51_dialog_content = "...",
  ui_story_5029_50290028_52_dialog_content = "Saya pikir Anda tampak mencurigakan pertama kali saya bertemu Anda.",
  ui_story_5029_50290028_53_dialog_content = "Anda memiliki masalah bergerak, namun ada lumpur di sepatu Anda.",
  ui_story_5029_50290028_54_dialog_content = "Sekarang saya menyadari Anda mengubur kotak di taman untuk membuat orang keluar jalur.",
  ui_story_5029_50290028_54X1_dialog_content = "Begitulah cara Anda mendapatkan lumpur di sepatu itu.",
  ui_story_5029_50290028_55_dialog_content = "Dengan semua petunjuk, hanya masalah waktu sebelum Anda tahu.",
  ui_story_5029_50290028_56_dialog_content = "Sayang sekali saya tidak bisa melakukannya lebih cepat, atau kami tidak membutuhkan semua upaya ini.",
  ui_story_5029_50290028_57_dialog_content = "Bukankah kakimu masih terluka, Cook?",
  ui_story_5029_50290028_58_dialog_content = "Apakah itu hal pertama yang ingin Anda ketahui dari saya?",
  ui_story_5029_50290028_59_dialog_content = "Itu tidak akan sembuh begitu cepat jika aku tidak begitu membencimu.",
  ui_story_5029_50290028_60_dialog_content = "Saya ingin Anda tahu, saya memalsukan kecacatan hanya untuk mengusir Anda setelah saya mencuri barang berharga Anda.",
  ui_story_5029_50290028_61_dialog_content = "Saya tidak mengerti. Mengapa Anda melakukan hal seperti itu ...",
  ui_story_5029_50290028_62_dialog_content = "Jika Anda membutuhkan uang, Anda bisa saja memberi tahu saya.",
  ui_story_5029_50290028_63_dialog_content = "Jangan meneteskan air mata buaya. Ini tidak pernah tentang uang!",
  ui_story_5029_50290028_64_dialog_content = "Saya hanya ingin mengambil milik Anda yang paling berharga sehingga Anda akan merasakan bagaimana rasanya kehilangannya!",
  ui_story_5029_50290028_65_dialog_content = "Laird tidak pernah memperlakukanmu dengan buruk, Cook.",
  ui_story_5029_50290028_66_dialog_content = "Dia bahkan memberimu waktu istirahat untuk pemulihan, dan begini caramu membalasnya?",
  ui_story_5029_50290028_67_dialog_content = "Hahaha…",
  ui_story_5029_50290028_68_dialog_content = "Keluarga saya telah melayani laird selama beberapa generasi.",
  ui_story_5029_50290028_69_dialog_content = "Dan aku tidak melakukan kesalahan sebelumnya. Tapi kamu?",
  ui_story_5029_50290028_70_dialog_content = "Tahun lalu, aku jatuh dari tebing dan kakiku terluka saat mencoba menyelamatkanmu.",
  ui_story_5029_50290028_71_dialog_content = "Tapi tak lama kemudian, Anda menemukan Zane untuk menggantikan saya.",
  ui_story_5029_50290028_72_dialog_content = "Sementara itu, saya hanya bisa membantu pelayan dengan tugas-tugas kasar.",
  ui_story_5029_50290028_73_dialog_content = "Kemudian Anda berencana untuk menendang saya keluar seperti saya tersesat?",
  ui_story_5029_50290028_74_dialog_content = "Saya tidak akan pernah melakukan itu.",
  ui_story_5029_50290028_75_dialog_content = "Aku mendengarnya dengan telingaku sendiri! Anda memberi tahu kepala pelayan bahwa begitu saya pergi, Zane bisa mendapatkan tempat tinggal saya ...",
  ui_story_5029_50290028_76_dialog_content = "Apakah ini harga untuk kesetiaan keluargaku kepada keluargamu?",
  ui_story_5029_50290028_77_dialog_content = "Anda salah paham tentang laird...",
  ui_story_5029_50290028_78_dialog_content = "Jangan khawatir, Zane, kau akan berakhir sepertiku suatu hari nanti!",
  ui_story_5029_50290028_79_dialog_content = "Huh.",
  ui_story_5029_50290028_80_dialog_content = "Apakah dia mengatakan yang sebenarnya, laird?",
  ui_story_5029_50290028_81_dialog_content = "Iya dan tidak.",
  ui_story_5029_50290028_82_dialog_content = "Anda adalah pelari yang hebat, Cook, tetapi tidak akan pernah sama lagi setelah cedera.",
  ui_story_5029_50290028_83_dialog_content = "Jadi aku selalu merasa sangat berhutang budi padamu.",
  ui_story_5029_50290028_84_dialog_content = "Anda setia seperti Anda pintar.",
  ui_story_5029_50290028_85_dialog_content = "Jika Anda tidak terikat pada layanan saya, Anda akan menjadi pengusaha hebat.",
  ui_story_5029_50290028_86_dialog_content = "Jadi saya pikir saya akan mengumpulkan dana awal untuk memungkinkan Anda mencobanya.",
  ui_story_5029_50290028_87_dialog_content = "Sayangnya, saya tidak punya waktu untuk memberi tahu Anda ...",
  ui_story_5029_50290028_88_dialog_content = "Apa yang kamu katakan?!",
  ui_story_5029_50290028_89_dialog_content = "Ini tidak bisa...",
  ui_story_5029_50290028_90_dialog_content = "Apakah Anda mengatakan saya salah paham?",
  ui_story_5029_50290028_91_dialog_content = "Kenapa begitu?",
  ui_story_5029_50290028_92_dialog_content = "Kau bahkan tidak pernah melirikku akhir-akhir ini. Bagaimana Anda berpikir untuk melakukan itu untuk saya?",
  ui_story_5029_50290028_93_dialog_content = "Jangan coba-coba membodohiku dengan kebohongan seperti itu!",
  ui_story_5029_50290028_94_dialog_content = "Anda hanya mencoba membenarkan diri sendiri.",
  ui_story_5029_50290028_95_dialog_content = "Betul sekali. Anda tidak berani mengakuinya di hadapan sang putri, bukan?",
  ui_story_5029_50290028_96_dialog_content = "Jadi Anda datang dengan penjelasan omong kosong seperti itu, kan?",
  ui_story_5029_50290028_97_dialog_content = "Semua yang dia katakan adalah kebenaran. Saya dapat menjamin itu!",
  ui_story_5029_50290028_98_dialog_content = "Kamu diam!",
  ui_story_5029_50290028_99_dialog_content = "Aku tidak percaya aku salah membacamu.",
  ui_story_5029_50290028_100_dialog_content = "Kenapa kamu...",
  ui_story_5029_50290028_101_dialog_content = "Anda terlalu pendendam untuk menjalankan bisnis.",
  ui_story_5029_50290028_102_dialog_content = "Anda bukan hakim saya atau masa depan saya!",
  ui_story_5029_50290028_103_dialog_content = "Saya melayani Anda selama bertahun-tahun dan di sinilah Anda, masih mencoba menipu saya ...",
  ui_story_5029_50290028_104_dialog_content = "Ha.",
  ui_story_5029_50290028_105_dialog_content = "Hanya seorang tolol yang akan jatuh cinta pada kebohonganmu!",
  ui_story_5029_50290028_106_dialog_content = "Meludah!",
  ui_story_5029_50290028_107_dialog_content = "Anda akan menyesali ini...",
  ui_story_5029_50290028_108_dialog_content = "Di sekitar sini mulai ramai.",
  ui_story_5029_50290028_109_dialog_content = "Bawa Cook kembali, Zane.",
  ui_story_5029_50290028_110_dialog_content = "Siap, Pak!",
  ui_story_5029_50290028_111_dialog_content = "Maafkan aku, laird...",
  ui_story_5029_50290028_112_dialog_content = "Terlepas dari itu, saya berterima kasih kepada Anda semua karena telah memulihkan kotak dan Cook.",
  ui_story_5029_50290028_113_dialog_content = "Oh, ini kotakmu.",
  ui_story_5029_50290028_114_dialog_content = "Kuncinya mungkin rusak, jadi periksa apakah semuanya masih ada di dalam.",
  ui_story_5029_50290028_115_dialog_content = "Terima kasih.",
  ui_story_5029_50290028_116_dialog_content = "<color=#828282>Klik.</color>",
  ui_story_5029_50290028_117_dialog_content = "Ya, tidak ada yang hilang.",
  ui_story_5029_50290028_118_dialog_content = "<color=#828282>Wuush…</color>",
  ui_story_5029_50290028_119_dialog_content = "Angin meniup sesuatu!",
  ui_story_5029_50290028_120_dialog_content = "Aku akan pergi mendapatkannya!",
  ui_story_5029_50290028_121_dialog_content = "Apakah ini...",
  ui_story_5029_50290028_122_dialog_content = "Hanya potret tua kecil.",
  ui_story_5029_50290028_123_dialog_content = "Itu pasti sangat berharga bagimu karena kamu menyimpannya di dalam kotak, kan?",
  ui_story_5029_50290028_124_dialog_content = "Ya.",
  ui_story_5029_50290028_125_dialog_content = "Tapi aku tidak pernah bisa kembali lagi.",
  ui_story_5029_50290028_126_dialog_content = "Sudahlah.",
  ui_story_5029_50290028_127_dialog_content = "Terima kasih, Nama Pemain, Putri Carleen, Merindukan Vice, dan Nona Fia.",
  ui_story_5029_50290028_128_dialog_content = "Jika Anda tidak keberatan, saya akan menyajikan pesta khusus Harbour City malam ini. Jangan ragu untuk datang.",
  ui_story_5029_50290028_129_dialog_content = "Saya pikir itu adalah sesuatu yang lebih berharga di dalam kotak.",
  ui_story_5029_50290028_130_dialog_content = "Tapi itu hanya potret. Saya tidak mengerti.",
  ui_story_5029_50290028_131_dialog_content = "Apakah Anda akan menempatkan pekerjaan tuan Anda di sana jika itu Anda?",
  ui_story_5029_50290028_132_dialog_content = "Tidak, saya akan meletakkan sesuatu milik saya sendiri.",
  ui_story_5029_50290028_133_dialog_content = "Orang dalam potret itu tampak familier...",
  ui_story_5029_50290028_134_dialog_content = "Ini sudah berakhir jadi mari kita santai saja, PlayerName.",
  ui_story_5029_50290028_135_dialog_content = "Saya percaya Elvis untuk menangani ini dengan baik.",
  ui_story_5029_50290028_136_dialog_content = "Lalu…",
  ui_story_5029_50290028_137_dialog_content = "Saya mendengar teras puncak gunung yang ditinggalkan di sekitar sini menawarkan pemandangan yang luar biasa.",
  ui_story_5029_50290028_138_dialog_content = "Maukah kamu ikut denganku?",
  ui_story_5029_50290028_139_dialog_content = "Tetap bugar adalah kegiatan rekreasi terbaik!",
  ui_story_5029_50290028_140_dialog_content = "Kudengar ada padang rumput yang cocok untuk jogging.",
  ui_story_5029_50290028_141_dialog_content = "Ayo, PlayerName, jangan lewatkan latihan hari ini!",
  ui_story_5029_50290028_142_dialog_content = "Tunggu, aku melihat orang-orang pergi ke festival makanan.",
  ui_story_5029_50290028_143_dialog_content = "Dan itu seharusnya lebih baik di malam hari!",
  ui_story_5029_50290028_144_dialog_content = "Bukankah kamu berjanji untuk mentraktirku dan Kyllo, PlayerName?",
  ui_story_5029_50290028_145_dialog_content = "Ayo coba jajanan pinggir jalan!",
  ui_story_5029_50290028_146_dialog_content = "Ayo joging di rumput!",
  ui_story_5029_50290028_147_dialog_content = "Mari kita melihat-lihat dari teras!",
  ui_story_5029_50290028_148_dialog_content = "Anu…",
  ui_story_5029_50290028_149_dialog_content = "Hmm…",
  ui_story_5029_50290028_150_dialog_content = "Apa yang harus dipilih...",
  ui_story_5029_50290028_151_dialog_content = "<color=#828282>Ding...</color>",
  ui_story_5029_50290028_152_dialog_content = "Selamat datang kembali, tamu tersayang.",
  ui_story_5029_50290028_153_dialog_content = "Anda tidak menyia-nyiakan kesempatan Anda malam ini.",
  ui_story_5029_50290028_154_dialog_content = "Selamat, Anda memecahkan teka-teki mimpi.",
  ui_story_5029_50290028_155_dialog_content = "Mengapa Anda terlihat sangat terkejut, tamu terkasih?",
  ui_story_5029_50290028_156_dialog_content = "Apakah Anda curiga saya telah memanipulasi mimpi Anda selama ini?",
  ui_story_5029_50290028_157_dialog_content = "Jika Anda bersikeras untuk berpikir bahwa ...",
  ui_story_5029_50290028_158_dialog_content = "Kenapa kamu tidak menolak ajakanku <color=#793f76>dari awal</color>?",
  ui_story_5029_50290028_159_dialog_content = "Tapi sekali lagi, sangat sedikit yang bisa melarikan diri dari mimpi yang aku jalin melalui sihir.",
  ui_story_5029_50290028_160_dialog_content = "Adapun saat ini, Anda hanya dapat menerima \"masa depan yang diintervensi oleh Jeno.\"",
  ui_story_5029_50290028_161_dialog_content = "Belum lagi hari sudah hampir subuh.",
  ui_story_5029_50290028_162_dialog_content = "Di sinilah perjalanan berakhir.",
  ui_story_5029_50290028_163_dialog_content = "Apapun itu, ingatlah...",
  ui_story_5029_50290028_164_dialog_content = "Keajaiban bersamamu."
}
return config
